const KEI=[{"id": "tagayasu", "kind": "tsuchi", "name": "耕す", "yomi": "たがやす", "en": "To till the soil", "rep": "tagayasu_a2.jpg", "lead": "土を起こすことは、人が土に触れるいちばん古い仕事のひとつ。掘り返し、砕き、また埋める——その繰り返しが、およそ1万年つづいてきた。", "layers": [["土に空気が入る", "耕すと土がほぐれ、隙間に空気と水の通り道ができて、根の伸びや水はけがよくなるとされる。いっぽうで耕しすぎは土の粒の集まり（団粒）を壊すことも知られていて、あえて耕さない栽培を選ぶ農家もある。どこまで起こすかは、いまも土ごとの判断である。"], ["1万年の手仕事", "農耕は約1万年前、西アジアの「肥沃な三日月地帯」で麦を育てることから始まったとされる。日本では弥生時代の遺跡から木の鍬や鋤が出土していて、のちに牛馬に犂（すき）を引かせる耕し方へつながっていく。鍬から機械まで、道具は変わっても動作の芯は同じで、土を反して空気に触れさせている。"], ["「田を返す」ことば", "「たがやす」は「田返す」に由来するとされる。漢字の「耕」も、すきを表す「耒」を部首に持つ。道具で土を反転させる動作そのものが、日本語と漢字の両方に埋めこまれている。"]], "invite": "プランターでも花壇の隅でもいい。移植ごてで土をひと掘りして、掘る前と後で、土の色と匂いがどう変わるかをくらべてみる。", "works": [{"t": "art", "f": "tagayasu_a1.jpg", "date": "1684年", "place": "中国（清）", "title": "山水図冊のうち「春耕」", "artist": "査士標", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1955.37.2", "note": "「春耕」と題した山水帖の一枚。画面の中ほど、水をたたえた田で牛を追う人影が、点のような小ささで描かれる。大きな山水のなかに、耕す人はこの大きさで置かれてきた。"}, {"t": "bun", "date": "18世紀後半", "place": "日本", "title": "『蕪村句集』より", "author": "与謝蕪村", "quote": "畑うつやうごかぬ雲もなくなりぬ", "src": "季語別「蕪村句集」（きごさいBASE）で本文確認。表記は「畑打や」とする本もある", "note": "畑打（はたうち）は春の季語で、鍬で畑の土を起こす仕事のこと。打ちつづけてふと見上げると、さっきまで動かなかった雲が消えている——耕す時間の長さが、雲の側から詠まれている。"}, {"t": "art", "f": "tagayasu_a2.jpg", "date": "1851年", "place": "フランス", "title": "種まく人（石版画）", "artist": "ジャン＝フランソワ・ミレー", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/49846", "note": "大股で種を蒔く農夫の石版画。よく見ると右上の丘では二頭の牛が犂を引いていて、蒔く人の背後に耕す人がいる。ミレーはこの主題を油彩でも繰り返し描いた。"}, {"t": "art", "f": "tagayasu_a3.jpg", "date": "1855–56年", "place": "フランス", "title": "土を掘る二人の男", "artist": "ジャン＝フランソワ・ミレー", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/7724", "note": "鋤を突き立てて土を起こす二人の男のエッチング。曲がった背中と道具の角度だけで、土の重さが伝わってくる。掘り返された手前の土は、画面のどこよりも荒れた線で彫られている。"}, {"t": "art", "f": "tagayasu_a4.jpg", "date": "1885年ごろ", "place": "オランダ", "title": "家の前で土を掘る農婦", "artist": "フィンセント・ファン・ゴッホ", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/28862", "note": "藁ぶきの家の前で、身をかがめて土を掘る女性の油彩。ミレーを敬愛したゴッホがオランダ時代に繰り返し描いた、土に向かう身体のひとつとされる。土と屋根と人が、ほとんど同じ色で塗られている。"}, {"t": "bun", "date": "1910年", "place": "日本", "title": "『土』", "author": "長塚節", "quote": "然し彼は重量ある唐鍬を振り翳して一鍬毎にぶつりと土をとつては後へそつと投げつゝ進む。（中略）土を切り起すことの上手なのは彼の天性である。", "src": "青空文庫『土』二八（https://www.aozora.gr.jp/cards/000118/card1745.html）で本文照合。ルビは省いた", "note": "貧しい農夫・勘次が、開墾の唐鍬（とうぐわ）を振るう場面。漱石の推薦で東京朝日新聞に連載され、1912年の単行本には漱石の序文「『土』に就て」が付いた。土を扱う小説の、土を扱う手つきの描写である。"}, {"t": "photo", "f": "tagayasu_p1.jpg", "date": "いま", "place": "千葉県松戸市", "title": "耕す（写真）", "author": "Namazu-tron", "lic": "CC BY-SA 3.0", "url": "https://commons.wikimedia.org/wiki/File:Une(Japanese)(ridge)-_between_plowed_furrows.JPG", "note": "ネギ畑に、鍬で立てられた畝がならぶ。起こされたばかりの土は粒の大きさがふぞろいで、その分だけ影が多い。版画の中の仕事と同じかたちが、いまも住宅地のとなりにある。"}], "no": "第一景"}, {"id": "ta", "kind": "tsuchi", "name": "田", "yomi": "た", "en": "Rice field", "rep": "ta_a3.jpg", "lead": "水を張り、苗を植え、水を落とす。田は人が土でつくる小さな湿地で、同じ場所で千年を超えて米が実りつづけてきた。", "layers": [["水を張るという発明", "田に水を張ると、多くの雑草の種は芽を出せなくなり、水が外から養分を運びこむ。畑とちがって同じ土地で毎年つくりつづけても連作障害が起きにくいとされ、それが土地を使いつぶさない米づくりを支えてきた。土と水の組み合わせでできた、長持ちする仕組みである。"], ["1万年前の長江から", "稲作は約1万年前、中国の長江中・下流域で始まったとされる。日本の水田稲作は約3000年前に九州北部へ伝わったと考えられていて、以来、水路とあぜが日本の土地の姿をつくり変えてきた。棚田は、その仕組みを斜面にまで持ちこんだかたちといえる。"], ["田という字", "「田」は、あぜ道で区切られた耕地を上から見たかたちを写した字とされる。田中や山田のように姓へ、新田や田端のように地名へと入りこみ、日本語の風景のいちばん深いところに埋まっている。"]], "invite": "電車や車の窓から田をひとつ探して、いまの季節の田の色をひとことで書きとめてみる。水色か、緑か、金色か。", "works": [{"t": "bun", "date": "905年ごろ", "place": "日本", "title": "『古今和歌集』巻四・秋歌上・一七二", "author": "よみ人しらず", "quote": "昨日こそ早苗とりしか いつのまに稲葉そよぎて秋風の吹く", "src": "『古今和歌集』巻四・秋歌上・172（題しらず・よみ人しらず）。かなづかい・宛字は本により揺れる", "note": "早苗をとって植えたのはつい昨日のようなのに、気づけば稲葉が秋風にそよいでいる——田のひと夏を、驚きひとつで言い切った歌。田植えから収穫前夜まで、時間はこの一首の中を流れている。"}, {"t": "bun", "date": "1689年", "place": "日本（須賀川）", "title": "『おくのほそ道』", "author": "松尾芭蕉", "quote": "風流の初やおくの田植うた", "src": "杉浦正一郎校註『おくのほそ道』（青空文庫 https://www.aozora.gr.jp/cards/002240/files/61619_78128.html）で本文照合", "note": "みちのくへ入って最初に出会った風流が、田植えの歌だったという発句。須賀川の宿で詠まれ、ここから脇・第三とつづけて三巻を巻いたと本文に記される。働く声を風流と聞きとめたところに、この句の芯がある。"}, {"t": "art", "f": "ta_a1.jpg", "date": "1730年代", "place": "日本", "title": "四季の百姓 二 田植の図", "artist": "鳥居清倍（二代）", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/5150", "note": "笠をかぶった早乙女たちが列になって苗を植え、天秤棒の男が苗籠を運ぶ。筆で彩色した初期の浮世絵（漆絵）で、百姓の四季を追う揃いものの夏の一枚。田植えが、描かれるべき年中行事だったことがわかる。"}, {"t": "art", "f": "ta_a2.jpg", "date": "1830–33年ごろ", "place": "日本", "title": "冨嶽三十六景 駿州大野新田", "artist": "葛飾北斎", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/87017", "note": "富士の裾野に新しく開かれた田（新田）。刈った葦を山と積んだ牛があぜをゆき、湿地と田の面が画面の半分を占める。名の主役は富士でも、大きく描かれているのは田で働く人と牛のほうである。"}, {"t": "art", "f": "ta_a3.jpg", "date": "1853年", "place": "日本", "title": "六十余州名所図会 信濃 更科田毎月鏡台山", "artist": "歌川広重", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/12530", "note": "信濃・更科の名所「田毎（たごと）の月」。斜面に重なる小さな田の一枚一枚に月が映るといわれ、広重は水面ごとに月影を描き分けてみせた。水を張った田が鏡になる——その一点が名所になった。"}, {"t": "photo", "f": "ta_p1.jpg", "date": "いま", "place": "新潟県十日町市・星峠", "title": "田（写真）", "author": "Koichi Hayakawa", "lic": "CC BY-SA 2.0", "url": "https://commons.wikimedia.org/wiki/File:Niigata-Sunrise_with_terraced_rice_fields_(Hoshitoge,_Tokamachi_City)-m_(52039917221).jpg", "note": "田植えどきの棚田は水鏡になる。夜明けの空と立木が、水を張った田にそのまま映っている。広重が描いた「田毎の月」と同じ現象が、いまも毎年めぐってくる。"}], "no": "第二景"}, {"id": "utsuwa", "kind": "tsuchi", "name": "うつわ", "yomi": "うつわ", "en": "Vessels born of earth", "rep": "utsuwa_a1.jpg", "lead": "水でこねると形になり、火をくぐると戻らなくなる。土のこの性質に、人は一万年以上前に気づいた。縄文の炎の飾りから手のひらの茶碗まで——器は、手のひらの中の大地である。", "layers": [["粘土という粒", "土の粒のうち、いちばん細かいものが粘土で、土壌学ではおよそ0.002mm以下の粒を指すとされる。水を含むと自在に形を変え、乾くと形を保ち、焼くと粒どうしが固く結びついて、水に戻らない硬さになる。この三段の変身が、土を器にした。"], ["最古級の道具", "土器は人類が発明した最古級の道具のひとつ。世界最古の土器は中国の洞窟遺跡から出た約2万年前のものとされ、日本列島でも青森県の大平山元遺跡から約1万6千年前の土器片が出ている——縄文土器は世界でも最古級とされる。金属より、文字より、車輪より古い。"], ["土を選ぶ文化", "茶の湯には「一楽二萩三唐津」という言いならわしがあるとされ、挙がるのはどれも磁器ではなく土ものの茶碗である。白く硬い磁器が石の粉を焼く「石もの」であるのに対し、陶器や土器は土を焼く「土もの」。土の色むらや手あとを「景色」と呼んで愛でる感性が、この国の器の文化を貫いてきた。"]], "invite": "家の茶碗をひとつ裏返して、高台（こうだい）を見てみる。釉薬のかかっていない足の部分に、その器がもとは土だったことが残っている。", "works": [{"t": "art", "f": "utsuwa_a1.jpg", "date": "前2500年ごろ（縄文時代中期）", "place": "日本", "title": "火焔土器（Fire-flame Cooking Vessel）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1984.68", "note": "炎が立ちのぼるような飾りを頭にいただく、高さ61cmの深鍋。煮炊きに使われた実用の器で、この形の土器は新潟県の信濃川流域を中心に出土するとされる。四千五百年前の台所道具が、彫刻と呼びたくなる造形をもっている。"}, {"t": "art", "f": "utsuwa_a2.jpg", "date": "400〜500年代（古墳時代）", "place": "日本", "title": "馬形埴輪", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1957.27", "note": "鈴飾りの馬具をつけた、高さ60cmほどの素焼きの馬。埴輪は粘土を輪に積んで形づくり、古墳の上に立て並べられた。馬具の意匠は同時代の朝鮮半島の馬装に似るとされ、土の造形が海を渡る交流まで写している。"}, {"t": "bun", "date": "720年（奈良時代）", "place": "日本", "title": "日本書紀 垂仁天皇三十二年", "author": "舎人親王ら撰", "quote": "埴を取りて人・馬及び種種の物の形を造作り……是の土物を号けて埴輪と謂ふ", "src": "『日本書紀』巻第六 垂仁天皇三十二年七月条（原文「取埴以造作人馬及種種物形……仍號是土物謂埴輪」）", "note": "殉死の代わりに土の人形を立てることを野見宿禰が進言し、埴輪が始まったと語る起源譚。埴（はに）はきめ細かな粘土の古語で、この一節が「埴輪」という名の由来を伝える。史実そのままではなく伝承とされるが、人の代わりを土でつくるという発想がここに刻まれている。"}, {"t": "bun", "date": "730年ごろ（奈良時代）", "place": "日本", "title": "万葉集 巻三・三四三（酒を讃むる歌）", "author": "大伴旅人", "quote": "なかなかに人とあらずは酒壺になりにてしかも酒に染みなむ", "src": "『万葉集』巻3-343（原文「中々尒人跡不有者酒壷二成而師鴨酒二染甞」）", "note": "なまじ人であるよりは、いっそ酒壺になってしまいたい——大宰府に赴任した晩年の歌人が詠んだ、酒を讃める十三首の一つとされる。人が器に生まれ変わることを夢想する歌で、器が暮らしにどれほど近いものだったかが透けて見える。"}, {"t": "art", "f": "utsuwa_a3.jpg", "date": "1300年代末〜1400年代（室町時代）", "place": "日本", "title": "壺（信楽焼）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1973.18", "note": "穀物を蓄えるための、高さ45cmほどの大壺。赤みは土に含まれる鉄の色で、肩の照りは窯の中で薪の灰が降り積もって溶けた自然釉とされる。釉薬を掛けない土そのものの肌を、のちの茶人たちは「景色」として愛でた。信楽は中世から続く産地で、日本六古窯の一つに数えられる。"}, {"t": "art", "f": "utsuwa_a4.jpg", "date": "1700年代後半（江戸時代）", "place": "日本", "title": "楽焼茶碗 富士の図", "artist": "楽了入", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/8591", "note": "黒い釉の肌に、富士の稜線と花枝が白く浮かぶ茶碗。作者の了入は楽家九代とされる。楽茶碗はろくろを使わず、手とへらだけで形をつくり出すとされ、手のひらの記憶がそのまま器になる。茶人の言いならわし「一楽二萩三唐津」の筆頭である。"}, {"t": "photo", "f": "utsuwa_p1.jpg", "date": "いま", "place": "インド", "title": "うつわ（写真）", "author": "Gannu03（Wikimedia Commons）", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File:Potter_shaping_clay_on_a_traditional_manual_potter%E2%80%99s_wheel_in_India_01.jpg", "note": "泥をまとった手回しのろくろの上で、小さな器が立ち上がりかけている。電気も型も使わない、手と回転と土だけの仕事。一万年以上続いてきた「土が器になる瞬間」は、いまも世界のどこかで毎日起きている。"}], "no": "第三景"}, {"id": "michi", "kind": "tsuchi", "name": "みち", "yomi": "みち", "en": "Paths of earth", "rep": "michi_a2.jpg", "lead": "歩くだけで、土は道になる。踏み固められた一筋は地図より古い記録で、万葉の墾道から東海道まで、人の行き来は大地に線として残ってきた。", "layers": [["踏み固めるという土木", "人が繰り返し歩くと、土の粒のあいだの隙間がつぶれて締め固まる。固くなった土は水がしみ込みにくく、草の根も張りにくくなるため、道筋だけが裸のまま残りつづける。歩くこと自体が、いちばん古い道づくりだった。"], ["土のままの街道", "江戸幕府は日本橋を起点に東海道など五街道を整えたとされるが、路面はおおむね土のままで、雨には泥に、日照りには埃になった。街道の並木は日陰を、一里塚は距離の目印をあたえる——どちらも土の道を歩き通すための設備だった。"], ["道という言葉", "地面の道を指す「みち」は、茶道・書道・剣道と、技や生き方の名にもなった。踏み固められて初めてできるもの、先に歩いた人の跡が残るもの——土の道の性質が、そのまま人の時間の比喩になっている。"]], "invite": "散歩の途中で、舗装が切れて土に変わる場所をひとつ探してみる。足音とやわらかさがどう変わるか、数歩ぶん、たしかめてみる。", "works": [{"t": "bun", "date": "8世紀（奈良時代）", "place": "日本", "title": "万葉集 巻十四・三三九九（東歌・信濃国の歌）", "author": "作者未詳", "quote": "信濃道は今の墾道刈りばねに足踏ましなむ沓はけ我が背", "src": "『万葉集』巻14-3399（原文「信濃道者伊麻能波里美知可里婆祢尓安思布麻之奈牟久都波氣和我世」）", "note": "信濃へ行く道はひらいたばかりの新道だから、切り株を踏んで怪我をしないよう、沓を履いていってね、あなた——旅立つ人を思う女性の歌とされる。木を伐り、株を残したまま土を踏み固めて道を通す。千三百年前の道普請の現場が、一首の中に残っている。"}, {"t": "art", "f": "michi_a1.jpg", "date": "1650年", "place": "オランダ", "title": "道端の三軒の切妻屋根の家", "artist": "レンブラント・ファン・レイン", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1962.22", "note": "画面の手前を、轍の刻まれた土の道が斜めに横切ってゆくエッチング。主役は藁葺きの家と大樹のようでいて、線がいちばん深く集まるのは足元の道である。17世紀オランダの田舎道は、こうして版画の中に踏み跡ごと残った。"}, {"t": "bun", "date": "1694年（元禄七年）", "place": "日本", "title": "この道や行く人なしに秋の暮", "author": "松尾芭蕉", "quote": "この道や行く人なしに秋の暮", "src": "『其便』所収。元禄七年九月、大坂での句とされる", "note": "亡くなるひと月足らず前、最晩年の句。目の前の秋の夕暮れの道と、誰もついて来ない俳諧の道が、ひとつの「この道」に重なって読まれてきた。「此道や行人なしに秋のくれ」など表記の異同が知られる。"}, {"t": "art", "f": "michi_a2.jpg", "date": "1833〜34年ごろ（江戸時代）", "place": "日本", "title": "東海道五十三次之内 平塚 縄手道", "artist": "歌川広重", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/25574", "note": "田のあいだを、一本の縄のようにジグザグと走る土の道。縄手（なわて）は田んぼの中の一筋道のこと。すれ違う旅人の足元の白さは、無数の足が踏み固めてきた色である。丸い高麗山の奥に、雪の富士がのぞく。"}, {"t": "art", "f": "michi_a3.jpg", "date": "1833〜34年ごろ（江戸時代）", "place": "日本", "title": "東海道五十三次之内 日坂 佐夜ノ中山", "artist": "歌川広重", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/25660", "note": "急坂の底に据わる丸い大石は、道のまん中にあった「夜泣き石」とされる。旅人たちが足を止めて眺めている。東海道の難所・佐夜の中山の坂は、のけぞるほどの勾配で描かれ、土の道が旅人の身体に何を要求したかを伝えている。"}, {"t": "art", "f": "michi_a4.jpg", "date": "1856年", "place": "フランス", "title": "路上にて（On the Road）", "artist": "ジュール・デュプレ", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/890", "note": "荷馬車が土の道の坂を越えてゆく油彩。轍は深くえぐれ、手前には雨あとの水たまりが光る。バルビゾンの画家たちが描いた農村の暮らしの足元では、いつも舗装のない道が天気ごとに姿を変えていた。"}, {"t": "photo", "f": "michi_p1.jpg", "date": "いま", "place": "山形県朝日町", "title": "みち（写真）", "author": "Syuzo Tsushima（Wikimedia Commons）", "lic": "CC BY 2.0", "url": "https://commons.wikimedia.org/wiki/File:Rural_footpath_(10835903875).jpg", "note": "刈り入れどきの田のあいだを、野道が曲がりながら奥へ続く。轍のあいだに草の筋が残るのは、車輪の通らない中央だけ土が締め固まらないから。広重が平塚に描いた縄手道と同じ形が、いまも稲干しの風景の中にある。"}], "no": "第四景"}, {"id": "tane", "kind": "tsuchi", "name": "種", "yomi": "たね", "en": "Seed / sowing", "rep": "tane_a3.jpg", "lead": "手のひらにのるほど小さく、乾いていて、音もしない。それを土に落とすとき、人は結果を見ないまま託している。芽が出るかどうかを決めるのは、種と、土と、そのあとの天気である。", "layers": [["種のなかみ", "種は、これから芽と根になる胚と、そのための養分（胚乳、または子葉に蓄えられる）と、それを包む種皮からできているとされる。発芽に欠かせないのは水・適した温度・酸素の三つで、光や肥料は必ずしも要らないとされる（光があると芽を出しやすい種、逆に光で抑えられる種もある）。小さな粒のなかに、はじめの数日ぶんの食料が畳んで入っている。"], ["土のなかで眠っている種", "土の中には、まだ芽を出していない種が数えきれないほど埋まっている。この集まりを土壌シードバンク（埋土種子）と呼ぶ。休眠している種は、温度・光・乾燥といった刺激で眠りが破れるまで待ちつづけ、百年を超えて生き残る例も知られている。アメリカでは1879年に植物学者ウィリアム・ビールが種を詰めた瓶を土に埋め、時期をおいて掘り出す実験を始めた。2021年に掘り出された瓶では、141年目の種から20粒が発芽したと報告されている。土は、いま生えている植物の名簿だけでなく、これから生えうる植物の名簿も抱えている。"], ["あずける、という仕事", "人は種を選び、乾かし、貯えてきた。世界の作物の種を二重三重に守るため、ノルウェー領スヴァールバル諸島の永久凍土のなかにつくられた世界種子貯蔵庫は2008年2月26日に開設され、2024年末の時点で130万点を超える種子が預けられているとされる。日本では、1951年に千葉市検見川の泥炭層から見つかった、およそ2000年前とされる蓮の実が、翌1952年に花を咲かせた（大賀ハス）。預ける先が俵でも、土でも、氷でも、していることは同じで──いま食べずに、あとへ渡している。"]], "invite": "乾いた大豆かあずきをひと晩水に浸けて、指で二つに割ってみる。ふくらんだ子葉のあいだに、これから芽になる小さな部分が畳まれている。", "works": [{"t": "bun", "date": "1世紀後半", "place": "地中海世界", "title": "マタイ傳福音書 第十三章（種播く者の譬）", "author": "作者不詳（伝マタイ）", "quote": "視よ、種播く者まかんとて出づ。播くとき路の傍らに落ちし種あり、鳥きたりて啄む。土うすき磽地に落ちし種あり……良き地に落ちし種あり、あるひは百倍、あるひは六十倍、あるひは三十倍の實を結べり", "src": "文語訳（大正改訳）新約聖書『マタイ傳福音書』第十三章3〜8節。ウィキソース「マタイ伝福音書-第十三章 (文語訳)」（https://ja.wikisource.org/wiki/マタイ伝福音書-第十三章_(文語訳)）で本文照合。ルビは省き、5〜7節を中略した", "note": "同じ手から出た種でも、落ちた場所によって実りが変わる──道ばた、石まじりの浅い土、茨のなか、良い地。たとえの主題は人の心だが、並べて語られているのは四種類の土の状態である。土が主語になった、いちばん古い文章のひとつといえる。"}, {"t": "art", "f": "tane_a1.jpg", "date": "1574年", "place": "ネーデルラント（アントウェルペン）", "title": "道ばたに落ちた種（種播く人の譬 より）", "artist": "フィリップ・ハレ（原画：ヘラルト・ファン・フルーニンヘン）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2023.128.1", "note": "たとえ話を四枚に分けた連作の一枚目。手前でくつろぐのは寓意の人物たちで、肝心の種まく人は画面左、丘の道を大股で歩きながら腕を振っている小さな影のほうである。その頭上を鳥が舞い、耕された斜面にも降りている──「鳥きたりて啄む」の場面。人の物語の背景として、土の仕事はいつもこの大きさで描かれてきた。"}, {"t": "art", "f": "tane_a2.jpg", "date": "1700〜1750年ごろ（清）", "place": "中国・蘇州", "title": "蓮の実と菱", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2025.113", "note": "台に載せた鉢に、蜂の巣のような花托がふたつ。くぼみのひとつひとつに、緑の実がおさまっている。まわりは蓮の花びらと、黒みを帯びた菱の実。蘇州で色摺りの一枚絵がさかんに作られた時代の版画で、めでたい食べものとして描かれているものが、そのまま種である。蓮の実は殻が硬く、長く生きのびることで知られる。"}, {"t": "bun", "date": "18世紀後半", "place": "日本", "title": "『蕪村句集』より", "author": "与謝蕪村", "quote": "よもすがら音なき雨や種俵", "src": "きごさい歳時記「種俵（たねだわら）」の例句として『蕪村句集』出典で掲載（https://kigosai.sub.jp/001/archives/16477）。本文確認済み", "note": "種俵は、翌年まく種籾を入れておく俵のこと。春の季語である。一晩じゅう、音のない雨が降っている。俵の中で眠っている種と、外の雨。まだ何も起きていない時間だけが、この十七音になっている。"}, {"t": "art", "f": "tane_a3.jpg", "date": "1878年", "place": "アメリカ", "title": "種まく人（The Sower）", "artist": "ウィンスロー・ホーマー", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1942.1430", "note": "木口木版。肩から斜めに掛けた袋に手を入れ、右腕をいっぱいに伸ばして種を放つ。開いた指先から左へ、種の帯が霧のように広がっていく。後ろでは二頭の馬が農具を引き、その脇を人が歩く。耕す人と蒔く人が、ひとつの画面に収まっている。足元は起こされたばかりの、塊のまま乾いた土。"}, {"t": "art", "f": "tane_a4.jpg", "date": "1917年以前", "place": "北アメリカ・グレートベースン（パイユート）", "title": "種を貯える籠（Seed Storage Jar）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1917.414", "note": "柳の枝を皮つき・皮むきのまま用い、斜めに撚りながら編み上げた壺形の籠。底はとがり、肩が張り、口は小さくすぼまって、中の粒がこぼれない。草の実を集めて蓄えることが冬を越す備えだったとされる暮らしの器で、焼きものではなく編みもの。土に入れるまで、種を土から遠ざけておくためのかたちである。"}, {"t": "photo", "f": "tane_p1.jpg", "date": "いま", "place": "マリ・シカソ州ニンタブーゴロ村", "title": "種（写真）", "author": "Rik Schuiling / TropCrop-TCS", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File:2016.07-443-292ap_sorghum,sowing_Nintabougoro_vlge(Nafanga_Cmn.,Koutiala_Crc.,Sikasso_Rgn),ML_thu21jul2016-1012h.jpg", "note": "モロコシ（ソルガム）の種まき。2016年7月の雨季。短い柄の鍬で赤い土に穴をあけ、足元に置いたひょうたんの器から種を落とし、そのまま土をかぶせる。三人が同じ姿勢で並んで進んでいく。ホーマーの絵の、立って腕を振る蒔き方とはちがい、こちらは腰を折って一か所ずつ置いていく。同じ土のうえで、いまも人の手が種を置いている。"}], "no": "第五景"}, {"id": "hatake", "kind": "tsuchi", "name": "畑", "yomi": "はたけ", "en": "Dry field", "rep": "hatake_a2.jpg", "lead": "田が水を張るのに対して、畑は水を張らない。土はいつも空気に触れたまま、筋状に盛られ、作物を替えられ、季節ごとに姿を変える。乾いた土との付き合い方が、そのまま景になったものが畑である。", "layers": [["水を張らない土", "田は夏のあいだ水をたたえるため、土の中の酸素が乏しい状態が続き、そこでの養分の動きが稲を支えるとされる。畑は水を張らないので、土はいつも空気に触れている。空気があると有機物の分解が進みやすく、そのぶん地力の消耗も早いとされ、堆肥を入れる、作物を替える、といった手入れが重ねられてきた。田と畑の違いは、育てるものの違いである前に、土に水を入れるかどうかの違いである。"], ["畝を立てるということ", "畝（うね）は、種をまき苗を植えるために、畑の土を幾筋も平行に盛り上げたもの。盛れば雨水は溝のほうへ落ちて水はけがよくなり、斜面にも日が当たるぶん地温が上がりやすいとされる。さらに、植える場所と人が歩く場所が分かれるので、土を踏み固めずに手入れができる。ひと筋の高まりが、水と熱と足の通り道をいっぺんに決めている。"], ["同じものを続けない", "同じ作物を同じ場所でつくりつづけると、生育が悪くなることがあり、連作障害と呼ばれる。そのため畑では、年ごとに作物を替える輪作が古くから行われてきた。中世のヨーロッパでは耕地を三つに分け、春まき・秋まき・休ませる地へと順に回す三圃式（さんぽしき）が広まったとされる。いっぽう水田の稲は同じ場所で長く作りつづけられるとされ、ここでも、張る田と替える畑という対比があらわれる。"]], "invite": "畑の前を通ったら、畝を一本、端から端まで目で追ってみる。盛り上がった背と、その両側の溝。雨あがりなら、水がどちらに残っているかまで見ると、畝の意味が身体でわかる。", "works": [{"t": "bun", "date": "8世紀（奈良時代）", "place": "日本（上野国）", "title": "万葉集 巻十四・三四〇六（東歌）", "author": "作者未詳", "quote": "上つ毛野佐野の茎立ち折りはやし我れは待たむゑ今年来ずとも", "src": "『万葉集』巻14-3406（原文「可美都氣野 左野乃九久多知 乎里波夜志 安礼波麻多牟恵 許登之許受登母」／仮名「かみつけの さののくくたち をりはやし あれはまたむゑ ことしこずとも」）。ウィキソース『万葉集/第十四巻』で本文照合", "note": "茎立（くくたち）は、蕪や菜の類が春に伸ばす花茎のこと。上野国の佐野（いまの群馬県高崎のあたり）の産で、いまも同じ地方で春先に摘む「かき菜」の類とみる説がある。恋の歌だが、待つ心にたとえられているのは、村の畑でつくられた春の菜である。"}, {"t": "art", "f": "hatake_a1.jpg", "date": "1570年", "place": "ネーデルラント（アントウェルペン）", "title": "四季 夏（The Four Seasons: Summer）", "artist": "ピーテル・ファン・デル・ヘイデン（ピーテル・ブリューゲル〈父〉の下絵による）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1995.16", "note": "下部の銘に六月・七月・八月の名が並ぶ「夏」の一枚。ブリューゲル（父）の下絵を、ファン・デル・ヘイデンが銅版に彫った。鎌をふるう男、束を運ぶ人、水差しをあおって喉を鳴らす男。右手では丸い実を山と盛った籠が頭の上を運ばれてゆく。奥には刈り終えた耕地と村と教会。水を張らない耕地の、一年でいちばん忙しい日である。"}, {"t": "bun", "date": "1814年（文化十一年）", "place": "日本", "title": "『七番日記』より", "author": "小林一茶", "quote": "大根引大根で道を教へけり", "src": "『七番日記』文化十一年十二月の項。「大根引き大根で道を教えけり」と表記する本もある", "note": "道を尋ねられた人が、いま抜いたばかりの大根で行く先を指してみせた。畑の手を止めずに答えているところが可笑しい。大根引は冬の季語で、土から出たばかりの白さが、そのまま道しるべになっている。"}, {"t": "art", "f": "hatake_a2.jpg", "date": "1830〜33年ごろ（江戸時代）", "place": "日本", "title": "冨嶽三十六景 駿州片倉茶園ノ不二", "artist": "葛飾北斎", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/86985", "note": "駿河・片倉の茶園。萌黄いろの斜面に茶の木が点々と続き、そのふちに渡した長い板の台へ、藍と緑の衣の人々が並んで腰かける。丸い笠が点々と光る。かたわらでは大きな桶に葉が集められ、馬の背に荷が積まれ、板橋を荷が渡ってゆく。富士を背にしているのは、水を張らない斜面の耕地である。"}, {"t": "art", "f": "hatake_a3.jpg", "date": "1880年ごろ", "place": "フランス", "title": "菜園の女（Woman in the Kitchen Garden）", "artist": "カミーユ・ピサロ", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/55787", "note": "画面の手前いっぱいに、キャベツの厚い葉が渦を巻いて広がる。そのただ中で、腰を折って背を見せる女がひとり。奥には木立と家並みが低く沈む。エッチングとアクアチントの黒が、葉の重なりと畝のあいだの影を深くしている。花の庭ではなく、食べるための菜園を、風景として正面から彫った一枚。"}, {"t": "art", "f": "hatake_a4.jpg", "date": "1899年", "place": "フランス", "title": "蕎麦の収穫（The Harvest of Buckwheat）", "artist": "ポール・セリュジエ", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/235046", "note": "赤く色づいた蕎麦の茎が畑いっぱいに立ち、刈られた束が円錐に並ぶ。黒い衣の二人が身をかがめて刈っている。蕎麦は種をまいてから二、三か月で実り、地力の乏しい土地にも耐えるとされ、作者が長く暮らしたブルターニュでは「黒い小麦（blé noir）」と呼ばれて食を支えた。土の色と作物の色が、ほとんど同じ赤で塗られている。"}, {"t": "photo", "f": "hatake_p1.jpg", "date": "いま", "place": "東京都杉並区", "title": "畑（写真）", "author": "おむこさん志望（Wikimedia Commons）", "lic": "CC BY 3.0", "url": "https://commons.wikimedia.org/wiki/File:Japanese_radish_field.jpg", "note": "住宅地のあいだに残る大根畑。黒いフィルムを掛けた畝が幾筋も並び、葉のあいだから白い肩がのぞく。フィルムは地温を保ち雑草を抑えるためのもので、盛り上げた土のかたちはそのまま残っている。一茶が詠んだ「大根引」の相手は、いまも同じ姿でここにいる。"}], "no": "第六景"}, {"id": "doro", "kind": "tsuchi", "name": "泥", "yomi": "どろ", "en": "Mud", "rep": "doro_a2.jpg", "lead": "土に水が混ざると、泥になる。足を取られ、服を汚し、たいてい嫌われる——その同じ泥から、田の米も、蓮の花も、日干しレンガの家も立ち上がってくる。", "layers": [["粘土が水を含むと", "土の粒は大きさで呼び分けられ、細かいほうから粘土・シルト・砂となる。粘土はおよそ0.002mm以下の粒とされ、シルトと砂を分ける境目は分類のしかたによって0.02mmとも0.05mmとも決められている。粘土の粒はごく薄い板が重なった構造をもつものが多く、水を含むとその板のあいだに水が入って粒どうしが滑るため、力を加えた形がそのまま残るとされる——これが可塑性と呼ばれる性質である。泥は、この細かい土と水が混ざったもので、水が抜ければまた固まり、縮んでひび割れる。"], ["泥でできた家", "水でこねた土を型に詰め、日に干して固める日干しレンガ（アドベ）は、西アジアで新石器時代から使われたとされ、いまも西アジア・北アフリカ・中南米・アメリカ南西部などに広く残る。土を枠のなかで突き固める版築、木や竹の下地に藁を混ぜた土を塗る土壁も、それぞれの土地で長く使われてきた。焼かないので燃料がいらず、材料は足元にある。泥は、人が最も長く使ってきた建材のひとつとされる。"], ["泥に染まらぬ", "日本語の「泥」は、泥をかぶる・泥を塗る・泥仕合・泥沼と、汚れと不名誉の側にかたよって使われる。いっぽう蓮は、泥の中から茎を伸ばして汚れない花を開くものとして、仏教美術で繰り返し描かれてきた。北宋の周敦頤は『愛蓮説』に「予独り蓮の淤泥（おでい）より出でて染まらざるを愛す」と書いている。同じ泥が、汚れの名にも、汚れなさの証にもなっている。"]], "invite": "雨あがりの土を少しつまんで、指のあいだで転がしてみる。細い紐のように伸びれば粘土が多く、ぼろぼろ崩れれば砂が多い。泥のねばりは、粒の細かさの手ざわりである。", "works": [{"t": "bun", "date": "905年ごろ", "place": "日本", "title": "『古今和歌集』巻第三・夏歌・一六五", "author": "僧正遍昭", "quote": "はちす葉のにごりにしまぬ心もてなにかは露を玉とあざむく", "src": "『古今和歌集』巻第三・夏歌・165（詞書「蓮の露を見てよめる」・僧正遍昭）。wakastream.jp（https://wakastream.jp/article/10000395TrQq）ほかで本文照合。表記は本により「蓮葉の」「にごりに染まぬ」とも揺れる", "note": "歌が言っているのは「にごり」で、泥という語は出てこない。ただし、蓮が泥の中に地下茎を張り、その濁りに染まらない葉を水面に立てる——という見方が、この歌の前提にある。染まらぬはずの葉が、どうして露を玉のように見せて人をあざむくのか。清らかさのほうを、いたずらっぽく問い返した一首である。"}, {"t": "bun", "date": "1694年", "place": "日本", "title": "『炭俵』所収の発句", "author": "松尾芭蕉", "quote": "青柳の泥にしだるる塩干かな", "src": "季語別「芭蕉全句集」（きごさいBASE https://kigosai.sub.jp/bs/?page_id=25579）の季語「塩干」の項で本文確認・出典『炭俵』。ウィキソース『芭蕉俳句全集』春の部「汐干」では「靑柳の泥にしだるゝ汐干哉」と表記", "note": "潮が引いて、岸の柳の細い枝が、あらわになった泥の上まで垂れている。「塩干（汐干）」は春の季語で、潮干狩の潮のこと。芽吹いたばかりの青い柳と、下に広がる泥。きれいなものと汚れたものを、一本の枝がつないでいる。"}, {"t": "art", "f": "doro_a1.jpg", "date": "1765年", "place": "日本", "title": "蓮を摘む（Gathering Lotus Flowers）", "artist": "鈴木春信", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/20010", "note": "蓮の葉と蕾のあいだに舟を寄せ、ひとりが舷から身を乗り出して水面へ手を伸ばす。もうひとりは長い棹を手に立っている。右手には蒲らしい水辺の草が茂る。蓮の地下茎（蓮根）は水底の泥の中にあるが、この絵に泥は写らない——摘む手の先にあるのは、水と葉だけである。"}, {"t": "art", "f": "doro_a2.jpg", "date": "1830年代なかば", "place": "日本（江戸・洲崎）", "title": "江都名所 洲崎しほ干狩", "artist": "歌川広重", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1985.315", "note": "潮が引いた洲崎の干潟。手前は舟の上からの眼で、帆柱と綱が画面を斜めに横切る。露出した泥の面に人が点々と散り、みな同じ角度に腰を折って貝を掘っている。右手の岸には松と茅葺きの屋根。洲崎は江戸湾ぞいの一帯で、春の潮干に貝がよく採れる場所として知られたと美術館の解説にある。遊山の絵に見えて、描かれているのは泥に手を入れる姿勢そのものである。"}, {"t": "art", "f": "doro_a3.jpg", "date": "1874年", "place": "アメリカ", "title": "グアダループ広場のカトリック教会（『第100子午線以西の地理探検と測量』第34図）", "artist": "ティモシー・オサリヴァン", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/210800", "note": "ウィーラー隊の1874年の測量で撮られた立体写真（ステレオカード）。左右にほぼ同じ写真が並び、専用の眼鏡でのぞくと立体に見える。台紙には「EXPEDITION OF 1874」の文字。作品名にそのまま採られた当時の説明文は、この教会が「日干しレンガ（adobe）で建てられた」もので、手前の墓地を囲むのも「高さ6フィートほどの日干しレンガの壁」だと記している。教会には梯子が立てかけられ、その前に小さな人影が数人。囲いの壁は、上端が波打つように丸くなっている。日干しレンガの壁は雨に削られやすく、塗り直しを重ねて保たれるとされる。"}, {"t": "art", "f": "doro_a4.jpg", "date": "1911年", "place": "フランス", "title": "氾濫した湿地——羊飼い（Le Marais inondé : Le Berger）", "artist": "オーギュスト・ルペール", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/135926", "note": "葉の落ちた柳が水の中に立ち、羊を積んだ平舟のわきを、男が棹を突いて舟を押していく。左手前には子を抱いた女が岸に立ち、奥には茅葺きの家。版の下の余白には、鉛筆で「Au Marais inondé - Le Berger」と書き込まれている。水はまだ引いていない。氾濫のあとに細かい土が積もることは古くから知られているが、その泥そのものは、この絵にはまだ現れていない。"}, {"t": "photo", "f": "doro_p1.jpg", "date": "いま", "place": "佐賀県佐賀市・東与賀", "title": "泥（写真）", "author": "Peka", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File:Mudflat_at_low_tide_in_Higashiyoka_in_May-2019_02.jpg", "note": "有明海に面した東与賀の干潟。潮が引くと、泥が水平線まで続く。表面は細かい粒が寄り集まってぼこぼこと起伏し、左手前には赤みを帯びた草が点々と生えている。広重が人を点々と置いたあの面は、実物ではこう見えている。"}], "no": "第七景"}, {"id": "ishi", "kind": "tsuchi", "name": "石", "yomi": "いし", "en": "Stone", "rep": "ishi_a1.jpg", "lead": "土を掘っていくと、どこかで石に当たる。石は砕けて土のもとになり、掘り下げた先では土の行きどまりにもなる——土のいちばん外側と、いちばん底に、同じものがある。", "layers": [["石が砕けて、土になる", "土のもとは岩石だとされる。日ざしと寒さで膨らみ縮み、割れ目に入った水が凍って押し広げ、根が入りこみ、水にとけやすい成分から順に流れ出す——そうして岩は少しずつ砕けて、砂や粘土のこまかい粒になる。そこへ落ち葉や生きものの遺骸が分解したものが混ざって、ようやく土と呼べるものになるとされる。どれくらいの時間がかかるかは、気候にも母岩の種類にも大きく左右されるので一つの数字では言えないが、土が一センチできるのに百年とも千年とも言われる。幅はあるにしても、人の一生よりはるかに長い。"], ["積むという技術", "石を、モルタルなどで固めずに積み上げるやり方を、空石積み（からいしづみ）や空積み（からづみ）と呼ぶ。噛み合わせと重心だけで立たせるので、隙間から水が抜け、背後の土に押されても少しずつ動いて崩れにくいとされる。ヨーロッパでは「空石積みの技術と知識」が2018年にユネスコの無形文化遺産に登録された（クロアチア・キプロス・フランス・ギリシャ・イタリア・スロベニア・スペイン・スイスの八か国による共同申請）。日本では、近江の穴太（あのう）を拠点にした石工集団・穴太衆が、自然石をほとんど加工せずに積む野面積み（のづらづみ）で知られ、城の石垣を築いたと伝えられる。"], ["石を立てる", "日本でいちばん古い庭の書とされる『作庭記』（十一世紀後半、橘俊綱の作とする説が有力）は、「石を立てん事、まづ大旨をこころうべき也」と書き出される。庭をつくることが、まず石を立てることだった。中国では、太湖のあたりで採れる穴だらけの石が庭や文人の机に据えられ、宋の米芾（べいふつ）は石を兄と呼んで拝んだと伝えられる。石を見る目安として「痩・皺・漏・透」の四字が挙げられてきた。日本では、神が降りるとされる岩を磐座（いわくら）と呼ぶ。動かないこと、変わらないことが、そのまま尊ばれてきた。"]], "invite": "河原や公園で足元の石をひとつ拾い、角が丸いか尖っているかを見てみる——丸いほど水に運ばれて長く転がってきた石だとされ、手のひらの上に、砕けて土になるまでの途中がある。", "works": [{"t": "art", "f": "ishi_a1.jpg", "date": "年代不詳", "place": "中国（江蘇省無錫）", "title": "太湖石（Taihu Garden Stone）", "artist": "自然の石（作者なし）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2022.23", "note": "人の背丈ほどの石灰岩が、台の上に一つだけ立っている。上のほうには向こう側が見える穴がひとつあき、下にも窪みがいくつも口をあけ、表面は薄い層が波打つように折り重なる。太湖（江蘇省）のあたりで採れるこの種の石は、庭に据えられたり、文人の机に「小さな山」として置かれたりしてきたと美術館は説明している。自然の力と人の手の両方でいまのかたちになったともあり、彫って作った像ではなく、選ばれた石である。写真は竹を植えた美術館の中庭で、背後に長椅子が写り込んでいる。"}, {"t": "bun", "date": "905年ごろ", "place": "日本", "title": "『古今和歌集』巻第七・賀歌・三四三", "author": "よみ人しらず", "quote": "わが君は千代に八千代にさざれ石の巌となりて苔のむすまで", "src": "ウィキソース『古今和歌集/巻七』で本文照合（原文「わか君は千世にやちよにさされいしのいはほとなりてこけのむすまて」／詞書「題しらす」・作者「よみ人しらす」）。中世に初句が「君が代は」の形になったとされる", "note": "さざれ石は小さな石のこと。それが積もり固まって巌（いわお）になり、その上に苔がつくまで、という言い方で時間の長さを測っている。祝いの歌の巻頭に置かれた一首で、長さの物差しに選ばれたのが、石の育つ速さだった。小石どうしが自然に固まった岩は実際にあり、さざれ石の名で各地に伝わる。"}, {"t": "art", "f": "ishi_a2.jpg", "date": "1300年代ごろ（元）", "place": "中国（元）", "title": "筠石喬柯図（Bamboo, Rock, and Tall Tree）", "artist": "倪瓚（げいさん／号は雲林）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1978.65", "note": "掛軸の下半分に、葉を落とした高い木と竹、そのあいだに一つの岩。岩は二つの峰をもち、渇いた薄墨でほとんど輪郭だけが引かれていて、紙の色がそのまま石の面になっている。上半分は詩や跋の書き込みで埋まり、朱の印がいくつも捺されている。表装の題簽には「倪雲林筠石喬柯」とある。竹と石を並べて描くのは、文人の絵の定番の組み合わせだった。"}, {"t": "bun", "date": "1689年（元禄2）", "place": "日本（出羽国・立石寺）", "title": "『おくのほそ道』立石寺", "author": "松尾芭蕉", "quote": "閑さや岩にしみ入る蝉の声", "src": "『おくのほそ道』立石寺の段。同行した曾良の『随行日記』には「山寺や石にしみつく蝉の声」の形で書きとめられている（ウィキペディア「閑さや岩にしみ入る蝉の声」で異同を確認）", "note": "岩山に堂が建つ立石寺で詠まれた句。音が岩に「しみ入る」と言うとき、岩は跳ね返すものではなく、吸うものになっている。曾良の日記に残る別の形では「石にしみつく」で、岩と石、しみ入るとしみつく、どちらもまだ固まっていない。"}, {"t": "art", "f": "ishi_a3.jpg", "date": "1816年（文化13）", "place": "日本（江戸）", "title": "写山楼画本より 石の図（Small Rock Sculpture, Design Twenty from Shazanrō Picture Book）", "artist": "谷文晁", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1985.375.x", "note": "見開きに石だけが刷られた木版の絵手本。右の頁には縦に伸びる一塊、左の頁には低い塊が二つ置かれ、輪郭は濃い墨、内側は薄い灰で刷り分けてある。左上には三字の題（「小石壁」と読める）と、朱の印が二つ。花も鳥も人もいない頁に、石だけが主役として並ぶ。写山楼は谷文晁の号のひとつで、弟子が絵を学ぶための手本として作られた本である。"}, {"t": "art", "f": "ishi_a4.jpg", "date": "1870〜78年", "place": "アメリカ（ロッキー山脈）", "title": "モルモン寺院のための花崗岩の切り出し（連作「ロッキー山脈の眺め」第119図）", "artist": "ウィリアム・ヘンリー・ジャクソン", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/108772", "note": "同じ写真を左右に並べた立体写真。花崗岩の巨石が積み重なる岩場に、十人ほどの男が散らばっている。上の岩に立つ者、岩の隙間に腰を下ろす者、手前の切り出された石の上に立つ者。右手には木のはしごが立てかけられ、手前の角の立った石には番号らしき数字が書かれている。丸みを帯びた自然の巨石と、直方体に断たれた石とが、一つの画面に並ぶ。台紙には内務省・合衆国地質調査所の刷り込みがある。"}, {"t": "photo", "f": "ishi_p1.jpg", "date": "いま（2011年）", "place": "滋賀県甲賀市", "title": "自然石を積んだ石垣（写真）", "author": "Motokoka", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File:Ano_Zumi.jpg", "note": "ほとんど加工していない自然石が、大きさも形もばらばらのまま噛み合って、まっすぐ奥へ伸びていく。石と石のあいだを埋めるものはなく、隙間からシダや草が生え、上端は土と草に覆われている。撮影者はこれを「穴太積」——穴太衆の積み方——と説明している。手前の左端だけは角を揃えた切り石で、積み方の違いがそのまま境目になっている。"}], "no": "第八景"}, {"id": "shio", "no": "第九景", "kind": "tsuchi", "name": "塩", "yomi": "しお", "en": "Salt — the sea that stayed in the ground", "rep": "shio_a4.jpg", "lead": "塩は、土の中に残された海である。岩塩の多くは、閉じこめられた海水が干上がった跡で、海から遠い土地の人はそれを掘り、あるいは塩水の湧く井戸を掘って煮た。土を舐めると海の味がする——サハラでも、アンデスでも、四川でも、その順序で塩は暮らしに入ってきた。", "layers": [["ことばと来歴", "鹽（塩）の字は、鹵（ろ）に監を添えたもので、鹵は塩気を含んだ土地や天然の塩をあらわす部首とされる。日本語の「しほ」は、潮と塩の両方を指した——『万葉集』の原文では、潮干が「塩干」と書かれている（巻三・二九三）。海の水も、そこから取り出したものも、同じ音で呼ばれていた。海から遠い土地では、塩は掘るものだった。紀元前五世紀のヘロドトスは、リビアの奥地に十日の行程ごとに塩の丘があり、雨が降らないので塩の塊で家を建てる人びとがいる、と書いた（『歴史』第四巻一八一〜一八五）。それから千八百年後、イブン・バットゥータはその砂漠の塩の村を実際に歩き、家も礼拝所も塩の板で建っていた、と記している（下の引用）。"], ["土と塩のしくみ", "海水にはおよそ3.5パーセントの塩が溶けている。それを閉じこめて干すと、水がおよそ九割飛んだあたりから食塩（鉱物としては岩塩＝ハライト）が沈み始める。石灰質、石膏、食塩、最後にカリウムやマグネシウムの塩——この順に沈むので、干上がった海の跡は層になって残る。こうしてできた岩の層を蒸発岩といい、岩塩の多くは、大陸の内側に取り残された海が干上がった跡である（内陸の塩湖が干上がってできたものもある）。地下に埋もれた塩の層を地下水が通れば、塩水になって湧く。四川の井戸の塩水も、アンデスのマラスに湧く塩水も、地表に海がないのに海の味がするのはそのためとされる。海の岸で塩をつくるのは、この蒸発を人の手でやり直すことである。塩田は日射と風で水を飛ばして海水を濃くする装置で、日本のように湿った土地では干すだけで塩にはならず、濃くした塩水を釜で煮つめた。"], ["文化", "日本には岩塩がなく、塩はずっと海から取ってきた。古くは海藻に海水をかけて濃い塩水をつくり煮た「藻塩」で、『万葉集』に「藻刈り塩焼き」と詠まれる。やがて砂浜が装置になった。海水を汲み上げて砂にまく揚浜式、潮の干満で海水を引き入れる入浜式（江戸時代に瀬戸内で広まり、行徳の塩浜もこの類とされる）、戦後の竹の枝に塩水を滴らせて風で干す流下式——そして1972年に塩田はすべて姿を消し、イオン交換膜で海水から塩を取る方式に変わった。能登には揚浜式の技術がいまも残る。海の向こうでは、塩は貨幣であり、都市を育てる富だった。サハラの塩は南の金と交換され、マリやソンガイの帝国を潤した。中国では塩は古くから国の専売で、揚州や天津の塩商は集めた富で画家を養い、庭園を築いた——この景の中国の一点は、そうして描かれた肖像である。"]], "invite": "台所の塩の袋を裏返して、原材料名と工程を読む。海水か、岩塩か、地下の塩水か。岩塩とあれば、それは数千万年から数億年前の海である——ひとつまみ舐めて、その海の味を確かめてみる。", "works": [{"t": "bun", "date": "700年代（奈良時代）", "place": "日本（筑前・志賀島）", "title": "『万葉集』巻三・二七八", "author": "石川少郎（石川君子）", "quote": "志賀の海女は藻刈り塩焼き暇なみ櫛笥の小櫛取りも見なくに", "src": "ウィキソース『万葉集/第三巻』歌番号 03/0278 で原文（然之海人者 軍布苅塩焼 無暇 髪梳乃小櫛 取毛不見久尓）と訓読を照合。訓読は同ページのもの（原文の「海人」を「海女」と訓んでいる）。左注に「石川朝臣君子、号して少郎子と曰ふ」とある", "note": "大意「志賀の海人は、藻を刈り塩を焼くのに忙しくて、櫛箱の小さな櫛を手に取って見る暇もない」。志賀は筑前（福岡）の志賀島。「藻刈り塩焼き」の四文字が、日本のいちばん古い製塩の手順である——海藻を刈り、それに海水をかけて濃い塩水をつくり、煮つめる。藻塩と呼ばれ、同じ『万葉集』の巻六・九三五には「朝なぎに玉藻刈りつつ夕なぎに藻塩焼きつつ海人娘女」（笠金村）、巻三・三五四には「縄の浦に塩焼く煙夕されば行き過ぎかねて山にたなびく」（日置少老）とある。煙が山にたなびくほど、岸辺で火が焚かれていた。日本の塩は最初から海のもので、土から掘る塩はこの列島にはなかった。"}, {"t": "bun", "date": "1355年（旅は1352年）", "place": "モロッコ（記述はサハラ・タガーザ）", "title": "『大旅行記（リフラ）』スーダン（西アフリカ）への旅", "author": "イブン・バットゥータ", "quote": "ses maisons et sa mosquée sont bâties avec des pierres de sel, ou du sel gemme; leurs toits sont faits avec des peaux de chameaux", "src": "デフレメリ＝サンギネッティ校訂・仏訳『Voyages d'Ibn Batoutah』第四巻（パリ・帝国印刷所、初版1858年）377〜379ページ。Internet Archive にある別々の二本のスキャン（コロンビア大学蔵の1874年刷／ハーバード大学蔵・Google撮影）で仏訳本文を相互照合。アラビア語原文は同書に併載。訳者二人はともに1883年没で著作権満了", "note": "大意「家も礼拝所も塩の石、つまり岩塩で建てられ、屋根は駱駝の皮でできている」。1352年2月、シジルマーサから隊商に加わって二十五日、着いたのが塩の村タガーザである。木は一本もなく、地面は砂ばかりで、その砂の下に塩の鉱山がある。掘ると、切り出して層にして地中に置いたかのような大きな塩の板が重なって出てくる、と彼は書く。駱駝一頭が運べるのは二枚。掘るのはマスーファ族の奴隷で、食べものは北から運ばれる棗と駱駝の肉と、南の黒人の国から来る雑穀。塩の駱駝一荷がワラタで金八〜十ミスカール、マリの町では二十〜三十、ときに四十——南の人びとは塩を切り分けて貨幣として使う、とも。水は塩からく、蠅がひどく、十日の滞在は難儀だった。タガーザは十六世紀に放棄され、採掘はその南のタウデニに移ったとされる。書いているのはタンジェ生まれのマグリブの法学者で、砂漠の北側から来た旅人の目である。"}, {"t": "bun", "date": "1637年（明・崇禎10）", "place": "中国（明・記述は四川と雲南）", "title": "『天工開物』作鹹第五・井塩", "author": "宋応星", "quote": "凡滇、蜀兩省遠離海濱，舟車艱通，形勢高上，其鹹脈即韞藏地中", "src": "中国語版ウィキソース『天工開物/井鹽』（『天工開物/作咸第五』の下位ページ）で本文照合。初版は1637年（崇禎10年）刊で著作権満了。⚠️ 二本目の電子テキスト（中國哲學書電子化計劃）は自動取得が認証を要求したため、照合はウィキソース一本による", "note": "大意「雲南と四川の二省は海辺から遠く、舟も車も通いにくく、地勢が高い。その塩の脈は、土の中に蔵されている」。この一文のあとに、井戸の掘り方が続く。蜀では川から遠くない石山の多くに井戸を穿って塩が取れる。井戸の口は径わずか数寸、小さな鉢で蓋ができるほどで、深さは十丈（およそ三十メートル）を越えてようやく塩水に届く。杵の先のような鉄の錐を竹に吊って石を突き、砕けた粉を竹に吊った鉄の皿で掬い上げる。深いものは半年、浅くても一月あまりで一本の井戸ができる。井戸の中を広くしないのは、広いと塩気が散って塩にならないからだという。塩水は節を抜いた竹の筒で汲み、牛に円盤を曳かせて轆轤を巻き、釜で煮ると「たちまち結んで色は真っ白」になる。さらに西川には火井があって、井戸の水は冷たいのに、竹の管で導いて釜の下に当てると水が沸く——「火の形を見ずして火の神を用いる、世間の大奇事なり」と著者は驚いている。天然ガスのことである。この掘り方を二百年伸ばした先に、1835年、四川自貢の燊海井が深さ千メートルを越えた（当時、世界でもっとも深い井戸とされる）。四川盆地の地下の塩水は、古い時代の海の名残とされる。"}, {"t": "art", "f": "shio_a1.jpg", "date": "1715年（清・康熙54）", "place": "中国（清）", "title": "安岐像（麓村高逸図／Portrait of An Qi）", "artist": "王翬・涂洛・楊晋", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1971.17", "note": "縦百二十二センチの掛軸。芭蕉の大きな葉と太湖石の下に、白い衣の男が敷物に座り、そばに童子と書物と布に包んだ琴、前を鶴が歩く。表装の錦にまで、友人たちの題詩がぎっしり書きこまれている（館の記載では七人）。塩は画面のどこにもない。所蔵館の説明はこう記す——像主の安岐は、朝鮮から来た塩商の二代目で、その富の一部を美術品の収集に使った。描かれた当時まだ四十歳にならず、道教の隠者のなりで、六朝以来の文人の肖像の型にはめて描かれている。太湖石と芭蕉と鶴は南方の庭と隠棲の暮らしを示し、この肖像は商人が士大夫の階級にあこがれた証拠である、と。三人の合作で、いちばん年長で有名なのが王翬。庭は均質な様式なのに、顔だけが不透明な絵具と陰影で描かれていて、そこが浮いて見える、とも館は書いている。安岐は号を麓村といい、自分の収集を記録した『墨縁彙観』の著者として知られる。塩の専売が生んだ富が、絵の中に塩ではなく隠者を置いた——館の記載を並べれば、そう読める。"}, {"t": "art", "f": "shio_a2.jpg", "date": "1783〜84年ごろ（天明3〜4）", "place": "日本（江戸・画題は摂津須磨）", "title": "風俗東之錦 須磨の汐汲（The Brine Maidens of Suma）", "artist": "鳥居清長", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/22565", "note": "大判、縦三十八センチ。松の枝の下に女が二人、天秤棒を肩にかけ、波の模様の桶を吊っている。左の一人は黒い上着、右の一人は千鳥を散らした赤い衣に、袖に波。足もとは砂で、うしろに波が寄せている。署名は清長画、右上の枠に「風俗東之錦」。館の題は「須磨の汐汲」で、それ以上の説明はない。汐汲みは、海水を桶で汲んで運ぶ仕事——塩をつくる手順のいちばん最初にあたる。須磨は『万葉集』にもう「須磨の海人の塩焼き衣」（巻三・四一三）と詠まれた塩の浜で、のちに在原行平と海人の姉妹・松風村雨の物語が重なり、能『松風』を経て、汐汲みは舞台の型になった。清長のこの二人は、塩を焼く人というより、江戸の女の姿に見える——重い桶が絵の中でこれほど軽く運ばれるのはそのためだが、そう読むのはこちら側である。二人のどちらが松風でどちらが村雨かも、館は書いていない。"}, {"t": "art", "f": "shio_a3.jpg", "date": "1785〜89年ごろ（1780年代後半）", "place": "日本（江戸・画題は陸奥）", "title": "六玉川 陸奥 野田の玉川（Women with Salt Pails; The Noda Tama River in Mutsu Province）", "artist": "窪俊満", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1940.1021", "note": "縦三十八センチの一枚。水辺に女が三人。まん中の一人が天秤棒を肩にかけ、片側に木の桶、もう片側に筒形の手桶を吊り、左の一人は小さな手桶を手に持って振り返る。うしろの一人は袖をかかげて風を受けている。奥に藁屋根の家と松、水の面、空には鳥がいくつも飛び、右下には紅葉した枝。館の題は「塩の桶を持つ女たち——陸奥の野田の玉川」で、六つの玉川を描いた揃いものの一枚。署名は俊満画、版元は伏見屋善六。野田の玉川は陸奥の歌枕で、いまの宮城県多賀城市、塩竈のすぐそばにある。能因の「夕されば潮風越してみちのくの野田の玉川千鳥鳴くなり」（『新古今和歌集』巻第六・冬歌・六四三）から、この玉川は千鳥と潮風で描かれるのがきまりで、空の鳥をその千鳥と見るのはこちら側の読みだが、桶を「塩の桶」と呼んでいるのは館である。須磨の汐汲みが物語から来ているのに対し、こちらは塩竈という塩の土地の名に引かれて桶が持ちこまれた——同じ十年のうちに、西と北の海辺の塩の仕事が、江戸ではどちらも女の姿になっている。"}, {"t": "art", "f": "shio_a4.jpg", "date": "1839〜40年ごろ（天保10〜11）", "place": "日本（江戸・下総行徳）", "title": "行徳塩浜之図（Salt Beach at Gyotoku）", "artist": "歌川広重", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/12808", "note": "縦十八センチ半、横五十二センチの横長の一枚（館の記載は絵半切の摺物）。手前から奥まで、平らな浜が広がり、藁で葺いた小屋のようなものが七つ八つ、そのあいだで人がかがんで働いている。浜の先に水が光り、鳥の列が飛び、遠くに青い山がひとつ。水平線には白い帆が並ぶ。右端の枠に「行徳塩浜ノ図」。行徳は下総（いまの千葉県市川市）、江戸湾の東の岸で、江戸の塩の産地だった。館の記載は題と技法だけで、絵のどれが何の道具かは書かれていない。潮の干満で海水を引き入れ、砂に染みこませて日で干し、塩のついた砂を集めて濃い塩水をとる入浜式が行徳で行われていたとされ、ここでかがんでいる人びとがその作業の途中だと読むのは、こちら側の推定である。塩そのものは白い粒として描かれていない——見えているのは、塩ができる前の浜の広さと、そこで働く人の小ささである。"}, {"t": "photo", "f": "shio_p1.jpg", "date": "1900年代はじめ", "place": "マリ・トンブクトゥ（撮影は当時の植民地の絵葉書業者）", "title": "トンブクトゥ、塩の隊商の到着（Tombouctou — Arrivée d'une caravane de sel）（絵葉書）", "author": "エドモン・フォルティエ（絵葉書業者・ダカール）", "lic": "パブリックドメイン", "url": "https://commons.wikimedia.org/wiki/File:Tombouctou-Arriv%C3%A9e_d%27une_caravane_de_sel_(AOF).jpg", "note": "砂の上を駱駝の列が横切っていく。十頭あまり、どれも胴の両側に四角い板を二枚、三枚とくくりつけている——それが塩である。列の中ほどに白い衣の人が数人立ち、うしろには草で葺いた丸い家々。上に印刷された説明は「トンブクトゥ、塩の隊商の到着。塩はおよそ三十キロの板で、トンブクトゥの北二十日のタウデニから来る」。イブン・バットゥータが「切り出して層にして置いたかのような塩の板」と書いてから五百五十年、駱駝はまだ塩の板を運んでいる。ただし撮ったのはダカールで絵葉書を売っていたフランス人で、植民地の目で切り取られた一枚である。写っている人びとの名前は記されていない。タガーザに代わってタウデニで塩が掘られるようになったのは十六世紀とされ、トンブクトゥへの塩の隊商（アザライ）はいまも続いているとされる。"}, {"t": "photo", "f": "shio_p2.jpg", "date": "いま", "place": "ペルー・クスコ県マラス", "title": "マラスの塩田（Salineras de Maras）（写真）", "author": "Diego Delso", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File:Salineras_de_Maras,_Maras,_Per%C3%BA,_2015-07-30,_DD_16.JPG", "note": "赤茶色の斜面が、白い縁どりの小さな池で埋めつくされている。池ごとに水の色が違う——乳白、淡い黄、褐色、そして干上がって真っ白になったもの。中ほどを、白い袋を肩にかついだ人が一人歩いている。ここはクスコの北西、聖なる谷を見おろす標高およそ三千メートルの斜面で、山の中から塩からい水が湧き、それを細い溝で段々の池に配って、日に干す。数千の池があるとされる。海から数百キロ離れた山の中で、湧き水が海の味をするのは、地下の古い塩の層を水が通ってくるからとされる——土の中に残った海が、ここでは水になって出てくる。インカより前から使われてきたとされる。撮影は2015年7月30日、南半球の冬にあたる乾季で、塩を採るのはこの季節とされる。撮影者の説明は「マラスの塩田（塩の蒸発池）」。"}]}, {"id": "tsukikatame", "no": "第十景", "kind": "tsuchi", "name": "版築", "yomi": "はんちく", "en": "Rammed earth — walls raised by pounding soil, layer upon layer", "rep": "tsukikatame_a2.jpg", "lead": "土を枠に入れて突き、締まったら枠を上げて、また突く。層を重ねて壁にする——版築。中国ではこれを夯土（こうど）と呼ぶ。西アジアやアフリカでは、同じ土を型で抜いて干した。材料は、どこでも足元の土しかない。", "layers": [["突くと、かさが減る", "版築は、板で枠を組み、その中に土を入れて杵で突き、締まったら枠を上へ移して、また突く。層が重なって壁になる。突くと何が起きるか——粒と粒のあいだの空気が押し出され、詰まって、密になる。同じ土でも締まり方は水加減で変わり、いちばん密になる水の量がある。土木の世界ではこれを最適含水比と呼び、突固め試験（JIS A 1210）で求める。乾きすぎても、水が多すぎても、密度は上がらない。土の中身も効く。砂ばかりでは固まらず、粘土ばかりでは乾くときに縮んでひび割れるので、砂と粘土がほどよく混じった土が向くとされる。ただし、突いた土が石になるわけではない。硬くなるだけで、中身は土のままである。"], ["四角くするか、枠の中で突くか", "土で壁を建てる道は、大きく二つある。ひとつは、泥を型に詰めて抜き、天日で干してから積む——日干し煉瓦。もうひとつは、枠の中でそのまま突き固める——版築。メソポタミア南部では前3千年紀の前半に、上が丸く盛り上がった煉瓦が使われた。エジプトではナイルの泥に藁を混ぜ、木の型で抜いて干した。中国では版築を夯土と呼び、河南の二里頭遺跡の基壇が古い例として挙げられる。城壁も、宮殿の基壇も、これで立った。中央アジアのオアシス都市、西アフリカの町、フランスのピゼ、スペインのタピアル、モロッコのタビア、日本の築地塀——枠の中で突く道は、呼び名を変えながら各地にある。アンデスのアドベのように、型で抜いて干す道を選んだ土地もある。どちらの道かは土地によって違う。共通しているのは材料のほうで、どこでも足元の土である。"], ["毎年、塗り直す", "土の建物は、完成しない。雨が当たれば表面から溶け、乾けば縮んでひびが入る。だから、直しつづけることが建て方の一部になっている。マリのジェンネでは、大モスクの壁を町ぐるみで塗り直す日がある。泥を練り、運び、手で塗る。壁から突き出ている椰子の棒は、壁を飾りながら、その日に登る足場も兼ねると説明される。日本の築地塀も、瓦の笠で雨を受け、傷めば土を足して直してきた。突き固めた層は風雨に少しずつ削られ、断面が縞になって現れる。土でつくるというのは、崩れないものを建てることではなく、崩れる速さより早く手を入れつづけることだ。手が止まれば、壁は元の土に戻っていく。"]], "invite": "紙コップを三つ——①乾いた土 ②握ると形が残るくらい ③水が滲むくらい——に同じ土を入れ、同じ回数だけ棒で突いて、かさの減り方を見くらべる。いちばんよく締まる水加減が、土ごとにある。", "works": [{"t": "art", "f": "tsukikatame_a1.jpg", "date": "前2900〜前2350年ごろ", "place": "メソポタミア（シュメール）", "title": "平凸煉瓦（Plano-convex brick）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/325521", "note": "底は平ら、上は丸く盛り上がっている。パンのような形をした日干しの煉瓦で、長さ21.2×幅15.9×厚さ6.7cm（館の記載は高6.7×幅15.9×奥行21.2cm）。館の記載では材料は「粘土、泥（Clay, mud）」——焼いてはいない。上の面のまん中に、押しつけたような浅いくぼみが一つある。この形の煉瓦には指で押した跡が残ることが多いと説明されるが、この一つがそうかどうかは、写真からは決められない。メソポタミア南部では、前3千年紀の前半の数百年、この形が使われた。斜めに立てて互い違いに並べる段（ヘリンボーン）と、平らに寝かせて積む段とが併用されたことが知られている。入口や隅は平積みで支えた（Delougaz, SAOC 7, 1933, pp.20-24）。土を四角くする方法が、まだ一つに決まっていない時代のかたちである。"}, {"t": "art", "f": "tsukikatame_a2.jpg", "date": "前1479〜前1425年ごろ", "place": "エジプト（テーベ）", "title": "煉瓦をつくる人々——レクミラの墓（Brickmakers, Tomb of Rekhmire）", "artist": "ニナ・ド・ガリス・デイヴィス（原寸の模写）", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/544649", "note": "テーベの岩窟墓の壁画を、20世紀に原寸のまま紙へ写した模写（テンペラ、48×68.5cm。年代は館が原画で記載している）。画面の左下に灰色の泥の山があり、その上で二人が働く。一人は前かがみになって鍬の先を泥に差し入れ、もう一人は立ったまま、運び手の頭の荷へ手を伸ばしている。画面の中ほどでは別の一人が、灰色の泥を盛った赤い台形の入れ物を頭に載せている。右下の一人は、二本の木を縄で結んだエジプトの鍬を両手で握っている。右上の男はかがみこんで、灰色の四角が段になって並ぶところへ手を伸ばす——干している煉瓦か、積んでいるところか。中央には青い顔料で書かれた文字が並び、鳥の記号が読める。泥、水、道具、運ぶ人。壁ができるまでにいる人の数が、そのまま描かれている。"}, {"t": "bun", "date": "前11〜前6世紀ごろ", "place": "中国（周）", "title": "『詩経』大雅・文王之什「緜」", "author": "作者不詳（周の詩）", "quote": "縮版以載，作廟翼翼。／捄之陾陾，度之薨薨。築之登登，削屢馮馮。", "src": "中国語版ウィキソース『詩經/緜』の本文で照合し、Chinese Text Project（ctext.org）の同篇（ジェームズ・レッグの英訳併記）と突き合わせた。引用の「／」は章の継ぎ目で、前半（縮版以載…）は第五章の末、後半（捄之陾陾…）は第六章にあたる（緜は九章章六句）。『詩経』に収める歌は前11〜前6世紀ごろの作、選集としてまとまったのは前6世紀ごろとされる。「緜」は、周の古公亶父が岐山のふもとへ移り、邑（むら）を建てるさまをうたう一篇", "note": "「版（板）を縄で締めて、順に上へ上げていき、廟をつくった」——工法の名が、そのまま歌になっている（「載」を「土を載せる」と読む説もあるが、照合したレッグ訳は「規則正しく上がるように」と読む）。続く四句は音の連なりで、すくう音（陾陾）、枠へ投げ入れる音（薨薨）、突く音（登登）、はみ出しを削る音（馮馮）。レッグの英訳も、籠で土を運び、掛け声とともに枠へ投げ入れ、拍子を合わせて突き、壁を削り整えた、と読む。締めくくりは「百堵皆興、鼛鼓弗勝」——壁がいっせいに立ち上がり、大太鼓の音も現場の音に勝てなかった。三千年近く前の建築現場の、音の記録である。ついでに言えば、同じ中国の古典『孟子』告子下には「傅説（ふえつ）は版築の間より挙げられた」とある。土を突いていた人が、宰相になったという話。"}, {"t": "art", "f": "tsukikatame_a3.jpg", "date": "前604〜前562年ごろ", "place": "メソポタミア（バビロン）", "title": "獅子の壁面（Panel with striding lion）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/322586", "note": "高さ99.7cm、幅230.5cm。横長の煉瓦が十段あまり積み上がり、その面をまたいで一頭の獅子が歩く。青緑の釉薬は全面に細かくひび割れ、いちばん下に黄色の一段が走る。館の記載は「セラミック、釉」——つまりこれは、焼いた土である。ネブカドネザル二世のころのバビロンで、イシュタル門から北へ延びる行列通りの壁を飾った一枚とされ、同じような獅子がいくつも並んでいたと説明される。獅子の輪郭は一枚の煉瓦に収まらず、何段にもまたがって型で起こされている。絵を壁に描いたのではなく、壁そのものを絵として焼いた。日干しの煉瓦は雨に弱い。都の見せる場所には、焼いた土が使われた。"}, {"t": "photo", "f": "tsukikatame_p1.jpg", "date": "1911年", "place": "中央アジア・トルクメニスタン（メルヴ）", "title": "日干し煉瓦の壁に囲まれた、丸屋根の建物（写真）", "author": "セルゲイ・プロクジン=ゴルスキー", "lic": "パブリックドメイン", "url": "https://commons.wikimedia.org/wiki/File%3ADomed_Adobe_Structures_Surrounded_by_an_Adobe_Wall.jpg", "note": "丸屋根が四つ横に並び、その手前にもう一つ低い丸屋根がある。うしろに角ばった高い壁が立ち、手前を長い土の塀が一直線に横切る。題は米国議会図書館の記載で、文字どおり「日干し煉瓦の壁に囲まれた、丸屋根の日干し煉瓦の建物」。屋根も壁も塀も、足元の地面と近い色をしている。地面から立ち上がったものが、そのまま建物になっているように見える。コモンズの説明は、古代メルヴ（いまのトルクメニスタン）のユースフ・ハマダーニー廟とモスクとする。撮影者は色フィルターを替えて三度写す方法を使っており、いま見えている色は、その三枚を後から重ねて作ったものである。"}, {"t": "photo", "f": "tsukikatame_p2.jpg", "date": "1911年ごろ", "place": "マリ（ジェンネ）", "title": "ジェンネの新しいモスク（La nouvelle mosquée de Dienné）", "author": "フェリックス・デュボワ", "lic": "パブリックドメイン", "url": "https://commons.wikimedia.org/wiki/File%3ADjenne_Mosque_Dubois_1911.jpg", "note": "本に刷られた図版（網点）。正面の壁に三つの塔が並び、その右手にもう一つ、窓の並ぶ角ばった塔が立つ。壁の上には尖った飾りがずらりと並び、塔の上のほうからは細い棒が何本も横へ突き出ている。壁面には太い柱が等間隔に並ぶ。柱の足元には、明るく平らな面がひろがる（水面かどうかは、この図版からは決められない）。図版の下には「ジェンネの新しいモスク」と刷ってある——新しい、というのは、この建物が1906〜07年に建て直されたばかりだったから。壁は日干しの土の煉瓦を積み、泥を塗って仕上げてある。突き出た棒は椰子で、壁を飾りながら、毎年の塗り直しのときの足場も兼ねると説明される。撮影者はこの図版を、1911年の本『わが美しきニジェール』に載せた。"}, {"t": "photo", "f": "tsukikatame_p3.jpg", "date": "いま（2017年）", "place": "中国・内モンゴル自治区（遼上京）", "title": "版築の層（写真）", "author": "BabelStone", "lic": "CC BY-SA 3.0", "url": "https://commons.wikimedia.org/wiki/File%3ALiao_Shangjing_2017_central_wall_rammed_earth_A.jpg", "note": "切り取られた土の壁の断面に、水平の縞が幾重にも走っている。一層ぶんの土を入れて突き、また入れて突く——その一回ずつが、一本の縞になって残っている。上には枯れ草、右手には藪。撮影者の説明は「遼の上京、南の城壁の東側の切り通しの版築」。遼の上京臨潢府は918年に築かれた都で、いまの内モンゴル自治区・バリン左旗にあたる。皇城の城壁は高さ9メートル、厚さ15メートルに達したとされる（この写真の面が皇城のものかは、撮影者の説明からは決められない）。突き固めただけの土が、千年を越えて、まだ立っている。"}]}, {"id": "sumi", "no": "第十一景", "kind": "tsuchi", "name": "炭", "yomi": "すみ", "en": "Sumi — charcoal: wood heated in an earthen kiln, starved of air, until only its carbon frame is left", "rep": "sumi_a2.jpg", "lead": "木を土で覆い、空気を絞って蒸し焼きにすると、燃えずに炭になる。あとに残るのは炭素の骨組みで、木の目までそのまま残る。炭を焼く窯は、土でできている。", "layers": [["燃やさずに、焼く", "炭は、燃えたあとの灰ではない。空気を絞って木を熱すると、水と、木酢やタールになる成分が煙になって出ていき、あとに炭素を主とした骨組みが残る。空気を絞って熱するこの操作を乾留（かんりゅう）という。炎を上げて燃えきってしまえば灰しか残らないから、炭焼きの仕事は「燃やさないこと」のほうにある。重さは乾いた木のおよそ二割から三割まで減り、残った側は炭素がおよそ八割から九割を占めるとされる。減るのに、形は残る。だから炭を割ると、年輪や、水を上げていた細い管の並びが断面に出てくる。炭素の骨組みだけになった炭は木のままより分解されにくいとされ、三千年をこえるものが土の中から炭のまま出てくる。アマゾンには炭の混じった黒い土があり、いまも肥沃だという報告があるが、炭がその理由なのかは決着していない。"], ["窯は土でできている", "炭窯は、土と石を積み、内側を粘土で塗り固めてつくる。木を立てて詰め、口を土でふさぎ、焚き口の空気だけを細く残す。中は見えないから、炭焼きは煙を読む。はじめは水気の多い白い煙、終わりに近づくと薄く青みがかった煙になる、と言われる。土で覆う形は日本だけのものではない。ヨーロッパでは木を山に積んで芝土と炭の粉で覆い、いまのアフリカや南アメリカでも、土をかぶせた堆が主なつくり方である。日本の窯は消し方で二つに分かれる。窯の口をふさいで中で消せば黒炭、千度ほどまで上げて赤いまま掻き出し、灰と土をかけて消せば白炭になるとされる。備長炭は紀州のウバメガシでつくる白炭で、名は元禄のころの炭問屋に由来すると言われる。"], ["黒い線として", "木炭は、そのまま描く道具になる。柳や葡萄の細い枝を炭にしたものが素描用で、紙にこすりつけると粒が残るから、指でぼかせるし、練り消しやパンで拭える。墨は、同じ黒でも作り方が違う。松や油を燃やしたときに立ちのぼる煤（すす）を集め、膠で練り固めたもの——木炭が「残ったもの」なら、煤は「上がったもの」で、どちらも炭素である。フランスのショーヴェ洞窟の黒い動物は木炭で描かれていて、絵の具そのものの炭素を測って年代が出されている。三万年をこえる昔に引かれた線が、いつ引かれたかを自分で名乗る。描くための炭が、そのまま日付にもなっている。"]], "invite": "木炭のひとかけを手に取り、切り口（木口の面）をよく見る。豆炭やオガ炭ではなく、木の形が残っているものがいい。年輪や、水を上げていた細い管の筋が見えたら、それが炭になる前の木である。折ってみると、折り口には縦に走る繊維の筋が出る。", "works": [{"t": "art", "f": "sumi_a1.jpg", "date": "前1473〜前1458年ごろ", "place": "エジプト（テーベ・ダイル＝アル＝バフリ）", "title": "炭のかけら三片（Three fragments of Charcoal）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/575410", "note": "館の題は Three fragments of Charcoal（炭のかけら三片）で、素材の欄も「charcoal」の一語だけ。ハトシェプストの葬祭殿を建てるとき、地面に掘って納めた基礎の埋納坑（Foundation Deposit 2a）から、1921〜22年のメトロポリタンの発掘で出てきた。長さ7cm。画面では、左の大きな塊に縦の割れが一本走り、表面に木の繊維の筋が横に流れ、上のほうには弧を描く線がある——年輪と読めるが、断定はしない。下半分から右にかけて、黄褐色の砂がこびりついている。題は三片と言うが、写真で分かれて見えるのは左の塊と右の小片の二つで、三片の切れ目までは読めない。その右の小さい一片は別番号の資料（22.3.261）で、同じ盆に並べて撮られている。三千五百年、土の中にあって、炭のまま出てきた。"}, {"t": "bun", "date": "前4世紀ごろ", "place": "ギリシャ（アテナイ）", "title": "『植物誌』第五巻第九章（火のための木——炭・薪・火きり）", "author": "テオプラストス", "quote": "The best charcoal is made from the closest wood, such as aria (holm-oak) oak arbutus; for these are the most solid, so that they last longest and are the strongest … whereas wood for charcoal should contain sap.", "src": "アーサー・ホート英訳『Enquiry into Plants』（ローブ古典叢書、1916年）第一巻、第五巻第九章1節。Internet Archive にある別々の二本のスキャン（トロント大学蔵 enquiryintoplant01theouoft ／ Google 撮影 enquiryintoplan01hortgoog）の全文で相互照合した。引用は英訳で、原文はギリシャ語。訳者アーサー・フェントン・ホート（1864〜1935）は著作権満了", "note": "「いちばん良い炭は、いちばん詰まった木からできる。アリア（トキワガシ）、オーク、イチゴノキ——これらがもっとも中身が固く、だから長持ちし、いちばん強い……炭にする木は、まだ水気を持っていなければならない」。中略した部分では、古い木ほど劣る、乾ききっているので燃えるときに爆ぜるから、と説かれる。二千三百年ほど前に、炭は木の種類で選び分けられていた。同じ章は用途による違いも書く——柔らかい炭が要る場面もあって、鉄では製錬のあとにクリの炭、銀山では松の炭。鍛冶屋はオークよりモミの炭を求める、モミは強くないが炎の立ちが早いから、と。そして、小枝の束はいちばん激しい炎を上げるけれども「中身がないので炭にはならない」。炭になるには、木の側に身がいる。"}, {"t": "art", "f": "sumi_a2.jpg", "date": "1430〜1521年", "place": "メキシコ（メシカ／アステカ）", "title": "日付の記号のある三足の火入れ（Tripod brazier with date glyph）", "artist": "中央高原の作り手（Central Highlands artist）", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/312582", "note": "焼いた土に化粧土。腰のくびれた筒形で、三つの球形の脚が本体を床から浮かせている。正面には方形の板が貼りつき、そこに浮き彫りの記号がある——館の題は、これを「日付の記号」と呼ぶ。板の中央には、点を打った丘のような形から先の尖ったものが立ち上がり、左右に翼のような曲線、下に格子と渦。その両脇に丸い突起が二つずつ、計四つ。板の左右にも、渦を並べた帯が続いていく。高さ35.9cm、幅・奥行きとも40.6cm。この器で何を燃やしたかは館の記載になく、炭だったのか薪だったのかは、この一点からは決められない。決められるのは、火を入れる器が土を焼いてつくられていたこと。火に耐えるために先に火を通されている——と読みたくなる。"}, {"t": "art", "f": "sumi_a3.jpg", "date": "1800年代〜1900年代（19〜20世紀）", "place": "南アフリカまたはモザンビーク（ツォンガ）", "title": "杖（Staff）", "artist": "「ヒヒの名手」と呼ばれる作者（The Baboon Master・おそらくツォンガの人）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2010.204", "note": "全長120.7cm。頭に男の胸像が二つ、背中合わせに立ち、その頭にのった円い輪を足場にして、ヒヒが四つ足で立っている。この輪は髪型の部品で、館の解説は、その髪型を isicoco と呼び、成人と結婚のしるしで、繊維か腱の輪に髪を編みこみ、その上を樹脂と炭と油を混ぜたもので覆って固めたものだと記す。炭を混ぜて固めた髪型が、木に彫られて頭の上にのっている。もうひとつ、胴の下部にある円い文様は、館の言う pokerwork——焼いた道具で木を焦がして描く線で、館は盾か葉を表すのかもしれないとする。柄にも細かい線の帯が巻いていて同じ手つきに見えるが、そちらは館の記載にない。木を焦がすことが、そのまま線になっている。"}, {"t": "art", "f": "sumi_a4.jpg", "date": "1877年", "place": "アメリカ（マサチューセッツ州ノースイーストン）", "title": "ノースイーストン、マサチューセッツ（North Easton, Massachusetts）", "artist": "ウィリアム・モリス・ハント", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1943.327", "note": "木炭だけで描かれ、枠の線まで木炭で引いてある。館の解説は、ハントを「チョークや黒鉛の鉛筆ではなく木炭で描いた、アメリカで最初期の画家のひとり」と紹介し、1877年に肖像画の仕事でこの町に滞在したあいだ、水車池ごしの町並みを何枚か描いたうちの一枚で、午後なかばの場面だと説く。左に葉の重い木、対岸に家並みと尖塔、水面にその影が下りている。右下の岸に、人が二人、数本の線だけで置かれている。紙は26.5×41.5cm。明るいところは紙のまま、暗いところは木炭の粒——木を焼いた粉が、木を描いている。"}, {"t": "art", "f": "sumi_a5.jpg", "date": "1887年（明治20）", "place": "日本", "title": "雪の中の炭窯（Charcoal Kiln in Snow）", "artist": "森寛斎", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/916592", "note": "絹に墨と彩色。雪をかぶった松と枯木のあいだに、雪をのせた窯の背があり、そこから灰色の煙が一本、ゆるく身をよじりながら立ちのぼる。窯の下には暗い焚き口が一つ開き、その上を弧を描く屋根らしいものが渡る。窯本体なのか、窯を覆う小屋なのかは、この一枚からは決められない。窯のわきに、蓑と笠をつけた人がひとり身を折り、手を下へ伸ばしている。足もとには切った木らしい黒い点が散る。本紙は縦127.3cm、横49.1cm。⚠️ 館の記載は1861年（江戸）とするが、画面左下の落款は「明治二十年夏　寛齋森公肅寫」と読め、それだと1887年になる。館の記載と画面が食い違うので、ここでは画面に書かれている年を採り、食い違いのほうを書き残す。"}, {"t": "photo", "f": "sumi_p1.jpg", "date": "いま", "place": "ガーナ北部", "title": "炭をつくる（写真）", "author": "Dnshitobu", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File:Covering_of_leakage_in_the_production_of_charcoal_in_Northern_Ghana.jpg", "note": "撮影者のつけた題は「北ガーナ、木炭づくりで漏れをふさぐ」、日付は2020年3月20日。切った丸太が何本も横たわり、そのすきまから白い煙が横へ流れている。手前は掘り返した土の畝。若い人がひとり身をかがめ、煙の出ているあたりへ腕を伸ばしている。奥に建物、右手は枯れ草。窯は建物ではなく、地面と、かぶせた土だけでできている。⚠️ 画像の説明文は「ガーナで撮影」としか書いておらず、場所や作り方の細かいことは記されていない。読めるのは題と、写っているものだけ。"}]}, {"id": "koe", "no": "第十二景", "kind": "tsuchi", "name": "肥", "yomi": "こえ", "en": "Manure — what a body puts out, put back into the soil", "rep": "koe_a1.jpg", "lead": "食べたものが体を通って外へ出る。それを土に入れると、また食べるものになって戻ってくる。この折り返しに、人は名前をつけ、建物を建て、値段までつけてきた。くさいものを、くさいまま扱ってきた歴史がある。", "layers": [["出したものが、また食べるものになる", "食べたもののうち、体が使わずに通り抜けた分と、いらなくなって捨てた分が、糞と尿になって外へ出る。そこには窒素・リン・カリウムが残っている。土に入れると、土の中の微生物がそれを分解し、やがて根から吸える形に変わる。だから畑に入れると、また食べるものになって戻ってくる。空気のおよそ八割は窒素だが、植物はその窒素をそのままでは使えない。いちど生きものの体を通った窒素が、畑ではそれだけ貴重だった。生のまま入れずに積んで寝かせるのが堆肥で、積んだ中は微生物のはたらきで温まり、五十度から七十度ほどまで上がることがあるとされる。家畜の糞に敷き藁が混ざったものが厩肥（きゅうひ）、人のものが下肥（しもごえ）。呼び分けはあるが、していることは同じで、外へ出たものを土へ返している。"], ["舟一艘、いくらの糞", "江戸のまわりの村では、下肥は買うものだった。屋敷や長屋の便所の中身を汲み取る権利を金で買い、舟で村へ運ぶ。値段は史料に残っている。天保十四（一八四三）年、武蔵・下総の二八三か村の惣代が勘定奉行へ出した願書によれば、寛政の取り決めでは舟一艘ぶんが代金三分から一両ほど、麦を作りつける時期は二分二朱から三分ほどだった。それが天保八（一八三七）年ごろから一両三分〜二両二分まで上がった、と訴えている（一両＝四分、一分＝四朱）。値上がりは何度も争いになり、寛政元（一七八九）年には江戸周辺の一〇一六か村が幕府へ値下げを願い出ている。糞は、値のつくものだった。"], ["くさいものに、名前と置き場所がある", "日本語だけでも、肥（こえ）・肥やし・下肥・厩肥・堆肥・糞と呼び分けがある。「肥」の字は、後一〇〇年ごろの字書『説文解字』に「多肉なり」とある——もとは肉づきのよいことを言う字で、人が肥えるのと土が肥えるのに、同じ一字をあてている。中国の『農書』（一一四九年）は、農家のかたわらに糞屋という建物を建て、中に煉瓦を敷きつめた深い池を掘って、漏らすなと書く。ヨーロッパでは、ウェルギリウスがわざわざ「恥じるな」と書いた。においを消してから扱うのではなく、くさいまま名前をつけ、置き場所を決め、値段をつけて扱ってきた。"]], "invite": "野菜くずをこまかく刻んで、鉢か花壇の土に浅く埋めてみる（土がかわかないよう、ときどき水をやる）。暖かい季節なら、二、三週間で形がくずれはじめる。掘り返して、埋めたものと土の境目がどこまで消えたかを見る。", "works": [{"t": "art", "f": "koe_a1.jpg", "date": "前100〜後100年ごろ（漢）", "place": "中国", "title": "豚小屋と便所の模型（Model of a Pigsty and Latrines）", "artist": "作者不詳", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/37716", "note": "灰色の素焼き。低い塀で囲った長方形の囲いがあり、奥と両側の塀の上端には瓦を伏せたような刻みが並ぶ。手前の隅には四方へ葺きおろした屋根の小さな小屋が張り出し、囲いの内側へ入口が開く。向かいの隅にも入口のある囲いがもうひとつ付く。館の解説は、当時の便所は豚小屋の上に建て、管で溜め（cesspool）につないでいたと説明する——題も「便所」を複数形で書いている。手前の隅のこの小屋がそれだろうと読むのは、こちら側。囲いの中には豚が、大小あわせて少なくとも四頭。奥に大きな一頭が横たわり、そのそばに小さいのが二頭、脚を伸ばして同じように横たわる。手前にもう一頭が立つ。中ほどに細長い餌桶がひとつ。手前の塀の上面（幅の広い天端）には、渦巻と菱形をスタンプで押した帯がある——豚の立つ床は、その一段奥で低い。右隅の囲いの天端にも同じ意匠がある。館の記載で40.6 × 21.6 × 27.9センチ。畑まで写ってはいない。ここにあるのは、出したものの行き先の、最初のひと続きだけである。"}, {"t": "bun", "date": "前1世紀（前29年ごろ）", "place": "ローマ（イタリア）", "title": "『農耕詩（ゲオルギカ）』第1巻80〜81行", "author": "ウェルギリウス", "quote": "ne saturare fimo pingui pudeat sola neve / effetos cinerem immundum iactare per agros", "src": "『農耕詩』第1巻80〜81行。ペルセウス・デジタル・ライブラリーが底本とする J. B. グリーノウ校訂『The Bucolics, Aeneid, and Georgics of Virgil』（ボストン、1881年）の TEI テキストで、行番号ごと照合した（l n=\"80\" / l n=\"81\"）。あわせてラテン語版ウィキソース「Georgicon (Greenough)/Liber I」の本文とも突き合わせている。81行の immundum を、グリーノウ版は inmundum と綴る（同語の異綴り）。ウェルギリウスは前70〜前19年の人で、『農耕詩』は前29年ごろの成立とされる", "note": "「肥えた糞で土を飽かせることを恥じるな。力を使いはたした畑に、汚れた灰を撒くことも」。二千年余り前の詩が、わざわざ「恥じるな（pudeat）」と言っている——つまり、恥ずかしいと思う人がいた。すぐ手前の行では、畑を一年おきに休ませること（alternis）を勧めていて、休ませることと糞を入れることが同じ息で並ぶ。fimus は家畜の糞、cinis は灰。畑から出ていった分を、糞と灰で戻す。少なくともこの詩の時点で、それは言葉になっている。"}, {"t": "art", "f": "koe_a2.jpg", "date": "200〜550年ごろ", "place": "ペルー北海岸（モチェ）", "title": "リャマ形の壺（Llama Vessel）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1990.128", "note": "赤い化粧土を塗った素焼き。脚を折りたたんで伏せたリャマの背から、あぶみ形の注ぎ口が立ち上がる。背にはふくらんだ荷が載り、縄が一本、撚りの刻みを見せて荷のきわを回り、肩から首のほうへ伸びる（脚を折って伏せているので、腹の側は見えない）。顔は横を向き、目のふちと口もとに白い化粧土。館の解説は、モチェの美術にリャマがくり返し現れる理由を決めかねている——生贄の獣だからか、肉と毛と「肥料」の源だからか、アンデスで唯一の荷を負う獣だからか。理由の候補のひとつに肥料が入っていること自体が、この土地でリャマの糞が何であったかを言っている。背中の荷は焼き物になった。落としていったほうは、ならなかった。高さ17.8センチ、奥行き23.1センチ。"}, {"t": "bun", "date": "1149年", "place": "中国（南宋）", "title": "『農書』巻上・糞田之宜篇第七", "author": "陳旉（ちんぷ）", "quote": "凡農居之側，必置糞屋，低為簷楹，以避風雨飄浸。且糞露星月，亦不肥矣。", "src": "『農書』（紹興十九年＝1149年成立）巻上・糞田之宜篇第七。中国語版ウィキソース「農書/卷上」の本文で引用し、同じくウィキソースにある別系統の翻刻「農書 (四庫全書本)/卷上」と突き合わせて照合した。四庫全書本は句読点を打たず「凡農居之側必置糞屋低為簷楹以避風雨飄浸且糞露星月亦不肥矣」と続けて書く。読みやすさのため句読点は前者に従った。陳旉は南宋の人で、洪興祖の後序に「其紹興己巳、年七十四」（1149年に七十四歳）とある", "note": "「農家のかたわらには、かならず糞屋を置く。軒を低くして、雨風が吹き込まないようにする。糞を星や月にさらせば、肥えなくなるからだ」。糞のための建物が、家の設計に入っている。中には煉瓦を敷きつめた深い池を掘り、漏らすなとも書く。掃いた土、燃やした灰、籾殻、刈った藁を積んで焼き、そこへ糞汁をかけて寝かせる。同じ章は俚諺（ことわざ）として「糞薬」——糞を使うのは薬を使うようなものだ——を引き、土の性質ごとにどの糞が合うかを選べという。章の終わりは、三年五年で地力は尽きるという言い方を退けて、手を入れつづければ「其力當常新壯矣（その力は常に新しく壮んであろう）」と書く。"}, {"t": "art", "f": "koe_a3.jpg", "date": "1585年以後", "place": "イタリア", "title": "糞を集める人（Manure Collector）", "artist": "アンニーバレ・カラッチに倣う", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/81804", "note": "褐色のインクのペン、下に黒チョークの跡。裸足の男が背を丸めてしゃがみ、右手で短い柄の平たい板（ちりとりのような道具）を地面に押しつけ、左手の枝箒でその上へ掃き寄せている。左うしろには、脚と長い柄のついた運搬の器がひとつ。上半分には塀と建物の輪郭だけが薄く引いてある。館の題は《糞を集める人》、作者の記載は「アンニーバレ・カラッチに倣う（After）」。カラッチはボローニャの物売りや職人を次々に写した一連の素描を残し、それはのちに『Le arti di Bologna（ボローニャの職）』という版画集になった——ゲッティ研究所が公開する1740年ローマ版には八十一葉の図がある。町の仕事の一覧の中に、落ちたものを拾う仕事が一枚ぶん入っている。26.8 × 16.4センチ。ただし、この一枚がその一連のどれにあたるかは、館の記載にはない。"}, {"t": "art", "f": "koe_a4.jpg", "date": "1855〜56年", "place": "フランス（バルビゾン）", "title": "肥やしの山から戻る農夫（Peasant Returning from the Manure Heap）", "artist": "ジャン＝フランソワ・ミレー", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1921.991", "note": "エッチング。石積みの壁と藁葺きのひさしのあいだで、帽子をかぶった男が木の手押し車を押している。荷台は黒い藁のようなもので山盛りになり、脇からこぼれかけている。男は両の握りをつかんで前へ体重をかける。足はどちらも木靴（サボ）で、二本とも地面についている。足もとは轍と泥。版の中、右下に J.-F. Millet の署名。ミレーは1849年にパリからバルビゾンへ移り、土の近くで暮らす人を描きつづけた、と館は記す。題は「肥やしの山から戻る」だが、車は空ではなく山盛りである。運び出すところなのか、積みに行くところなのかは、この一枚からは決められない。版の大きさは16.2 × 13.2センチ——手のひらほどの銅版に、重たい車が一台ある。"}, {"t": "photo", "f": "koe_p1.jpg", "date": "いま", "place": "インド・チャッティースガル州", "title": "牛糞を買う（写真）", "author": "Domino786", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File:Purchase_of_cow_dung.jpg", "note": "撮影者の説明は「ゴーダン・ニャーイ・ヨージナーによる牛糞の買い取り」、日付は2020年7月20日。地面に広げた大きなシートの上に、板を一枚かませて台秤が据えられ、その皿に牛糞が山盛りになっている。かたわらに、赤い数字を出す黄色い指示計が一台、コードでつながっている。腰をかがめて秤のほうへ身を寄せる人（手に紙片を持っている）、地面に座って帳面に書きこむ人、幕の前に立ち並ぶ人たち。うしろの幕には制度の名がデーヴァナーガリー文字で刷ってある。チャッティースガル州がこの制度を始めたのは2020年7月で、州が牛糞を1キロ2ルピーで買い取り、女性の自助グループが堆肥に変えて1キロ8ルピーで農家へ売る、と説明されている。江戸の値段争いから百八十年ほどたって、糞にはまだ値段がついている。"}]}, {"id": "gake", "no": "第十三景", "kind": "tsuchi", "name": "崖", "yomi": "がけ", "en": "Gake — a cliff or outcrop, one of the few places where the ground shows its own layers without being dug", "rep": "gake_a1.jpg", "lead": "土を垂直に切ると、そこだけ時間が見える。崖や露頭は、掘らなくても地面の中身が出ている場所で、ふつうは下にあるものほど古い。崖は、崩れているからこそ見えている。", "layers": [["下が古い、という決まり", "地層は下から順に積もっていくので、ひっくり返っていなければ、下にあるものほど古い——これを地層累重の法則という。デンマークのニコラウス・ステノが1669年にフィレンツェで出した『固体の中に自然に含まれる固体についての論文への序説』で示したとされ、いまも地層の新旧を読むときの大原則になっている。地面の中身が掘らずに見えている場所を露頭（ろとう）と呼び、崖はいちばん大きな露頭である。ただし、崖に出ている縞をそのまま時間の目盛りとして読むわけにはいかない。何も積もらなかった時間や、積もったあとで削られてしまった時間は、面一枚に潰れて消える（不整合）。崖の縞は、時間の連続した記録ではなく、残ったところだけの記録である。"], ["崩れるから、見えている", "崖が縞を見せているのは、そこが削られつづけている場所だからである。草や木に覆われた斜面では、地面の中は見えない。海が波で足もとをえぐり、雨水が表面を流し、凍結や乾湿の繰り返しが岩を割る——その結果として、断面がむき出しのまま保たれる。千葉県の屏風ヶ浦は、銚子市から旭市の刑部岬まで約10km、高さ40〜50mの海食崖が続き、2016年3月に国の名勝および天然記念物に指定された。いまは足もとに護岸が入り、後退は抑えられている。見えることと崩れることは、崖では同じひとつのことの表と裏になっている。⚠️ ただし、崖のそばが安全かどうかを判断するのは、この景の役目ではない。住んでいる自治体の出す情報と、気象庁の発表に従ってほしい。"], ["崖に通った人たち", "1800年代のヨーロッパとアメリカで、崖は絵の主題になり、同時に記録の対象にもなった。クールベは、生まれ育ったフランス東部・ジュラの石灰岩の崖と、ノルマンディーの海の崖を、繰り返し描いている。同じころアメリカ西部では、政府の測量隊が写真機を谷へ運び込み、崖を地形の資料として撮った。陸軍省の印章を刷った台紙に貼られたベルの写真や、番号を振ったオサリヴァンの写真がそれで、題も番号も付いている。いっぽうジャクソンは、測量隊の写真師をつとめたのち写真館を構え、崖を立体写真の札にして売った。同じ崖が、絵になり、資料になり、居間で覗く商品になる。どれも崖を見ることだが、見る側の目的は、それぞれ違っていた。"]], "invite": "切り通しや、土がむき出しの切土（きりど）の法面（のりめん）の前を通りかかったら、離れた場所から、色の変わり目が横に何本走っているかを数えてみる。ひっくり返っていなければ、いちばん下がいちばん古い。（人が積んだ盛土の縞は、地層ではない。）", "works": [{"t": "bun", "date": "1845年（初版は1839年）", "place": "イギリス（記述は南アメリカ・パタゴニア）", "title": "『ビーグル号航海記』第八章 バンダ・オリエンタルとパタゴニア", "author": "チャールズ・ダーウィン", "quote": "The uprising movement has been interrupted by at least eight long periods of rest, during which the sea ate deeply back into the land, forming at successive levels the long lines of cliffs or escarpments, which separate the different plains as they rise like steps one behind the other.", "src": "1845年版『Journal of researches into the natural history and geology of the countries visited during the voyage of H.M.S. Beagle round the world』第八章「Banda Oriental and Patagonia」のうち「Geology of Patagonia」の段。英語版ウィキソースが1845年版のスキャン（Darwin Journal of Researches.djvu, pp.164-198）から起こした本文で照合し、Project Gutenberg の同書テキスト（#944）と突き合わせた。両者は句読点だけが違い、Gutenberg は ate と cliffs のあとに読点を置く。ここではスキャンから起こしたウィキソース側の綴りを採った。ダーウィンは1809〜1882年の人", "note": "「隆起は、少なくとも八回の長い休みによって中断された。その休みのあいだ、海は陸を深くえぐり返し、それぞれの高さに長い崖の列——段丘の崖——をつくった。崖は、階段のように後ろへ後ろへと高くなっていく平原と平原のあいだを、仕切っている」。ビーグル号の航海（1831〜36年）でパタゴニアの海岸を見た記録である。ここで崖は、風景の一部としてではなく、陸の持ち上がりが何回休んだかを数えるための目盛りとして読まれている。崖が何本あるか、が答えになっている。⚠️ 「少なくとも八回」はダーウィン自身の見立てであって、いまの区分がそのまま八段だという意味ではない。"}, {"t": "art", "f": "gake_a1.jpg", "date": "1869年ごろ", "place": "フランス", "title": "オートピエールの岩（The Rock of Hautepierre）", "artist": "ギュスターヴ・クールベ", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/27027", "note": "油彩。画面の右半分を、岩の帯と草の帯が交互に三段、ほぼ水平に積み重なって占めている。岩の段は灰色で、ところどころ白く光る。段と段のあいだの棚には草木が横一列に並んで生えていて、層の切れ目がそのまま緑の線になって見える。崖の上は一面の緑、足もとには赤茶けた屋根の農家が身を寄せ、左手には水面と遠い山がある。館は解説を付けていない。題の Hautepierre は、クールベの生地オルナン（フランス東部・ジュラ）に近いルー川の谷にある岩山を指すとされるが、その場所であることをこの一枚から確かめることはできない。画面は80.2×100.3cm。"}, {"t": "art", "f": "gake_a2.jpg", "date": "1871年ごろ", "place": "アメリカ（コロラド川）", "title": "アイスバーグ峡谷、コロラド川、上流を望む（Iceberg Canyon, Colorado River Looking Above）", "artist": "ティモシー・H・オサリヴァン", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2002.46", "note": "湿板からの鶏卵紙印画。台紙の下に「ICEBERG CAÑON, COLORADO RIVER, LOOKING ABOVE」と刷られ、左下に「T. H. O'Sullivan, Phot.」、右下に「No 15」とある。左の壁一面に、右下がりの平行な筋がびっしり走っている。ただし、この筋が地層なのか、岩そのものの割れ目なのかは、この一枚からは決められない。水ぎわの岩の上に、つばの広い帽子をかぶった人がひとり、膝をかかえて座っている——この人がいるおかげで、壁の高さが分かる。館は、オサリヴァンがウィーラー中尉の率いる西経100度以西の測量隊に加わり、自分の舟を与えられて低い視点から峡谷をたどったこと、この一枚で記録と美しさを両立させたことを記す。画面は20.2×27.3cm。"}, {"t": "art", "f": "gake_a3.jpg", "date": "1872年", "place": "アメリカ（アリゾナ・グランドキャニオン）", "title": "カナブ・ウォッシュの峡谷、南を望む（Canon of Kanab Wash, Looking South, Colorado River）", "artist": "ウィリアム・H・ベル", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2021.204", "note": "ガラス乾板からの鶏卵紙印画。台紙の上には陸軍省（WAR DEPARTMENT）の鷲の印章、左に「Explorations in Nevada and Arizona」、右に「Expedition of 1872.  Lieut. Geo. M. Wheeler, Com'd'g.」。画像の下には「COLORADO RIVER SERIES.／CAÑON OF KANAB WASH, LOOKING SOUTH.／No 21.」、画像の左下に「W. Bell, Phot.」。正面の岩山にも左右の壁にも、横向きの帯が幾段も重なって見える。上の帯ほど新しい、と読むのが地層累重の法則だが、この写真からその順番を確かめられるわけではない。見えているのは、帯が水平に揃っていること、それだけである。館は、ベルがウィーラー隊の写真師として1872年にアリゾナとユタの川や峡谷を記録したこと、同じ場所を西向きに撮った一枚が別にあることを記す。画面は35.5×27.8cm。"}, {"t": "art", "f": "gake_a4.jpg", "date": "1872年以降", "place": "フランス（ノルマンディー・エトルタ）", "title": "エトルタの崖（The Cliff at Étretat）", "artist": "ギュスターヴ・クールベ", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1929.465", "note": "油彩。画面の左半分を、海に足を突き出した大きな岩の塊が占める。右端では岩が一本の脚になって海へ降り、その脚と本体のあいだに穴が開いている——波に削られたあと、残ったところが門の形になっている。浜には舟が三艘。いちばん右の一艘は赤茶けた帆を張ったまま波打ちぎわに立つ。館は解説を付けていない。エトルタの崖は白亜（チョーク）でできていて、海峡をはさんだドーヴァーの白い崖と同じく、およそ七千万〜八千万年前の浅い海に降り積もった石灰質の殻に由来するとされる。ただし、この絵の崖は白くない。薄桃色の空を背に、ほとんど黒く塗られている。白亜の崖という説明と、画面に見える色は、ここでは一致していない。画面は54.5×65.5cm。"}, {"t": "art", "f": "gake_a5.jpg", "date": "1879〜92年", "place": "アメリカ（ワイオミング）", "title": "ワイオミングのバッドランズ（Badlands of Wyoming）・立体写真", "artist": "ウィリアム・ヘンリー・ジャクソン", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/103150", "note": "鶏卵紙の立体写真（ステレオ）。ほとんど同じ写真が二枚、わずかに違う角度から並べて貼ってある。専用の眼鏡で覗くと、二枚が一つに重なって奥行きが立つ仕掛けである。写っているのは雨水に刻まれた尾根の列で、横縞が肋骨のように並び、その向こうは地平線まで平らな原がひろがる。尾根の上に、黒い人影がひとつ立っている。左の写真の下端に白い文字で「3306 BAD LANDS OF WYOMING」、台紙の両脇に「W. H. Jackson & Co., Photographers」「414 Larimer Street, Denver, Colo.」と刷ってある。ジャクソンは1870年から78年までヘイデン隊の写真師をつとめ、79年にデンヴァーで写真館を開いた人で、この住所はその店のものである。崖は、覗いて楽しむ商品にもなった。画像は一枚が9.4×7.5cm、台紙は10×17.7cm。"}, {"t": "photo", "f": "gake_p1.jpg", "date": "いま（2025年）", "place": "千葉県銚子市", "title": "屏風ヶ浦（写真）", "author": "くろふね", "lic": "CC BY 4.0", "url": "https://commons.wikimedia.org/wiki/File:%E5%B1%8F%E9%A2%A8%E3%83%B6%E6%B5%A6%EF%BC%88%E5%8D%83%E8%91%89%E7%9C%8C%E9%8A%9A%E5%AD%90%E5%B8%82%EF%BC%8920250222-IMG_3150.jpg", "note": "撮影者の説明は「屏風ヶ浦（千葉県銚子市）」、撮影日は2025年2月22日。真っ青な空の下に、黄土色の崖が斜めに立ち上がる。崖の面には濃淡の細い帯が何十本も、左へゆるく下がりながら重なっている。上は枯れ草に覆われ、足もとを白いコンクリートの護岸と、等間隔に柱の立つ柵が横切る。屏風ヶ浦の海食崖は銚子市から旭市の刑部岬まで約10km続き、高さは40〜50mとされ、2016年3月に国の名勝および天然記念物に指定された。下から犬吠層群（名洗層・飯岡層）、その上に不整合面をはさんで香取層と関東ローム層が載る、と説明される——ただし、この一枚のどの縞がどの層にあたるかは、写真からは決められない。ドーヴァーの白い崖に似ているとして「東洋のドーバー」とも呼ばれるが、こちらの崖は白くない。"}]}, {"id": "ni", "no": "第十四景", "kind": "tsuchi", "name": "丹", "yomi": "に", "en": "Ni — red earth: iron-rich soil, ground into one of the oldest pigments", "rep": "ni_p1.jpg", "lead": "古い日本語で、赤い土を「に」と呼んだ。人はこの土を砕き、水や油で溶いて、肌に、器に、石に、木に塗ってきた。いちばん古い絵具のひとつであり、その赤は、土にまじる鉄の色である。", "layers": [["赤いのは、鉄", "土の赤は、鉄が酸素と結びついてできた鉱物の色である。土、とくに下層の土が黄褐色から赤褐色に見えることが多いのは、鉄の酸化物・水酸化物のためで、代表的なものに次の二つがある。赤鉄鉱（ヘマタイト、Fe₂O₃）はあざやかな赤褐色で、熱帯の赤い土に多い。針鉄鉱（ゲータイト、FeOOH）は黄褐色で、温帯の土に典型的だという。黄色い針鉄鉱は、火にかけると水が抜けて赤鉄鉱に変わり、赤くなる。焚き火で届くおよそ300〜800℃の範囲なら、温度や焼く時間を変えても、できる赤の色みはほとんど変わらない、という実験がある。旧石器時代の画家は黄と赤の両方を顔料に使っていて、黄色を焼いて赤をつくることを知っていたのかどうかが、調べられてきた。⚠️ ただし漢字の「丹」は、赤い土（に）だけでなく、硫黄と水銀の化合物である辰砂（朱）や、鉛を焼いてつくる鉛丹にも当てられる。言葉のほうも分けていない——辞書は、辰砂を説く項の終わりにも「に」と添えている。辰砂は水銀の鉱物で、鉄の赤ではない。鉛丹は人がつくる顔料である。この景は土の赤、つまり鉄の赤だけを扱う。赤く見えるものが、いつも鉄の赤とはかぎらない。"], ["十万年の絵具", "赤い土は、少なくとも10万年前から人に使われ、手を加えられてきたとされる。南アフリカのブロンボス洞窟では、およそ10万年前の層から、赤い土を加工して混ぜ、貝殻に貯えた跡が見つかっている。同じ洞窟のおよそ7万3000年前の層から出た石のかけらには、赤い土のクレヨンで引いた格子の線があり、報告のあった2018年の時点で、それまでに知られていたいちばん古い素描を、少なくとも3万年さかのぼるという。赤い土は、描くためだけのものでもなかった。器の肌に塗られ、体に塗られ、彫った木を染めた。日本でも縄文時代早期の貝塚から出たものが古い例として知られ、のちには土器や埴輪にも塗られた。石に描き、器に塗り、肌にのせる——同じ土が、何にでも赤を移す道具だった。"], ["焼いて、練って、貝に貯える", "赤い土の扱い方は、遠く離れた土地どうしでよく似ている。ニュージーランドのマオリは、鉄を多く含む粘土（タコウ）や砂岩を専用の火で焼いて赤みを強め、粉にして、そのまま、あるいは水やサメの肝の油、ティートキの実の油と練って塗った。粉は、パウアやホタテや淡水の二枚貝の殻、軽石の壺、ひょうたんに貯えられた、とオークランド博物館の考古学の学芸員ルイーズ・フューリーは書く。十万年前のブロンボス洞窟でも、赤い土は貝殻の中にあった。中央オーストラリアのオーカー・ピッツは、いまも土地の伝統的な持ち主がオーカー（白から黄・赤まで、色のついた土）を掘りつづけている場所だと説明される。サンスクリットでは赤い土をゲールカと呼び、日本語では「に」と呼んだ——『デジタル大辞泉』は、この「に」を、土を指す「に」と同じ語源とする。日本で酸化鉄の赤を指す「ベンガラ」の名は、インドのベンガル地方に由来するとされるが、その言葉がオランダ語から来たのか（デジタル大辞泉）、ポルトガル語から来たのか（日本国語大辞典）は、辞書によって書き方が違う。工業でつくるベンガラも、硫酸鉄を焼くか、いったん黄色い酸化鉄をつくってから焼いて仕上げる。ここでも、赤は火を通して出す色である。"]], "invite": "乾いた日に、足もとの土をひとつまみ、白い紙にこすりつけてみる。場所を変えて、もう一か所。黄色みが強いか、赤みが強いかを、並べて見くらべる。表面の土は、植物が朽ちてできた腐植がまじって黒っぽく見えることが多く、鉄の黄や赤は、その下の土に出やすい。黒っぽい線しか引けなくても、それも一つの答えである。（濡れた土は暗く見えるので、乾いたものどうしで。よその庭や畑、立ち入りが禁じられた場所の土は取らない。触ったあとは手を洗う。）", "works": [{"t": "art", "f": "ni_a1.jpg", "date": "前2000〜前1600年ごろ", "place": "スーダン北部（下ヌビア・ファラス）", "title": "貯蔵の壺（Storage Jar）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/548347", "note": "館の記載は材料を「赤と黒の焼き物、刻線の飾り（Red and black ware, incised decoration）」とし、時代の区分を「Cグループ」（下ヌビアの文化の名）とする。1911〜12年のオックスフォード大学のヌビア発掘で、ファラスの第2墓地・3号墓から出た。高さ17cm、径19cm。丸くふくらんだ胴は赤褐色で、口のまわりの帯と、のぞいている口の内側が黒い。黒い帯には山形と斜めの格子が刻まれ、赤い胴には、格子を詰めた長方形をX字に組んだ文様と、点を縦に打ち並べた線がいくつか見える。⚠️ 胴の赤が、赤い土を塗って磨いたものなのか、器の土そのものが焼けて出た色なのかを、館は書いていない。この赤を土の中の鉄の色と読むのはこちら側で、この一枚からは決められない。"}, {"t": "art", "f": "ni_a2.jpg", "date": "前1900〜前1800年ごろ", "place": "エジプト（メンフィス地域・リシュト南）", "title": "瓶（Bottle）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/546468", "note": "館の記載は材料を「焼き物、ナイルの粘土、赤いオーカーの化粧がけ（red ochre wash）」とする。中王国時代。1933〜34年のメトロポリタンの発掘で、リシュト南の、センウセレトアンクの墓の西にある墓の、囲いの南西の隅の瓦礫から出た。高さ20cm。卵形の胴に、ラッパのように開いた口がつき、いまは金色の金属の台にのせてある。表面はつやのない、少し桃色がかった赤。首には、見えている側の端から端まで、ひびが横に走る。口の近くの欠けたところや、首の縦のひびに沿ったところでは、赤い面の下から、くすんだ薄茶色がのぞいている。館の記載と重ねると、赤は器の土そのものの色ではなく外から薄くかけた膜で、のぞいているのはその下の地だと読める。⚠️ ただし、割れを継いだときの詰め物がのぞいている見込みも、この写真からは除けない。館の記載どおりなら、ナイルの粘土を焼いた器の上に、別の赤い土を溶いてかけている——土の上に、土を塗っている。"}, {"t": "bun", "date": "4〜5世紀ごろ", "place": "インド（サンスクリット語）", "title": "『メーガドゥータ（雲の使者）』後雲篇（Uttaramegha）の一節", "author": "カーリダーサ", "quote": "tvām ālikhya praṇayakupitāṃ dhāturāgaiḥ śilāyām ātmānaṃ te caraṇapatitaṃ yāvad icchāmi kartum | asrais tāvan muhur upacitair dṛṣṭir ālupyate me krūras tasminn api na sahate saṃgamaṃ nau kṛtāntaḥ", "src": "本文は、サンスクリット語版ウィキソースにあるマッリナータ注『サンジーヴィニー』付きの1930年刊本（カナカ・ラール・タックル校訂、第3版、ベナレス、マスター・ケーラーリー・ラール刊。後雲篇第42詩節、本の82頁）のスキャンに拠る。ローマ字（IAST）は、スキャンのデーヴァナーガリーと一字ずつ照合してある。突き合わせに使った電子テキスト：ゲッティンゲン大学の GRETIL（S. K. De 校訂、V. Raghavan 改訂、1970年版にもとづく。通し番号 KMgD_102。CC BY-NC-SA 4.0 で配布。本文は満了したスキャン本に拠る）。異同：同じくウィキソースのスキャンにある、ヴァッラバデーヴァ注付きのフルチ校訂本（ロンドン、王立アジア協会、1911年。通し番号102、本の53頁）だけが dṛṣṭir ālipyate（目が塗りこめられる）と読み、脚注に、マッリナータ注本・ステンツラー版・ジナセーナ『パールシュヴァーブユダヤ』（パータク版）・写本 D が lupyate と読むことを挙げる。ここでは1930年刊本と GRETIL の ālupyate を採った。詩節の番号は版によって違う。作者カーリダーサは4〜5世紀ごろの人とされる", "note": "「恋ゆえにすねているあなたを、鉱物の色で石の上に描き、そのあなたの足もとに伏している自分を描き添えようとすると、そのたびに、こみ上げる涙で目がふさがれる。むごい運命は、絵の中でさえ、わたしたちが会うのを許さない」（この作品の訳）。主人に一年のあいだ遠くへ追われたヤクシャが、雲に託して遠い妻へ送る言葉の一節である。絵具は dhāturāga＝「鉱物の色」としか言われていない。モニエル＝ウィリアムズの辞典（1899年）は dhātu を「金属・鉱物・鉱石（とくに赤い色の鉱物）」と説く。14〜15世紀の注釈者マッリナータはここに「ダートゥとは、ゲールカなど」と注し、同じ辞典はゲールカを「赤いチョーク（red chalk）」と訳す——赤い土である。ところが10世紀のカシミールの注釈者ヴァッラバデーヴァは、同じ語を「シンドゥーラなどの色」と言い換える。シンドゥーラは同じ辞典で「鉛丹・ミニウム・朱（vermilion）」、鉛や水銀からつくる赤で、土ではない。⚠️ 石に描かれた恋人の赤が、赤い土だったのか、鉛や水銀の赤だったのか。その読みは、10世紀と14〜15世紀の注釈者のあいだで、すでに割れている。詩そのものは、何色とも書いていない。"}, {"t": "art", "f": "ni_a3.jpg", "date": "500〜600年ごろ（古墳時代）", "place": "日本", "title": "男子埴輪の頭部（Male Haniwa Head）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1977.206", "note": "館の記載は材料を「土器に、オーカーの化粧がけ（earthenware with ochre wash）」とする。解説は付いていない。高さ28cm。つばの広い帽子の上に、前から後ろへ反りかえる高い冠のような部分がのり、そこに二重の弧が何本も刻まれている。上から垂れる帯の先には丸い粒がつき、つばのふちにも小さな粒が並ぶ。目は細長い穴としてくり抜かれ、鼻は盛り上げ、口は細い線で表されている。⚠️ 館は「オーカーの化粧がけ」と書くが、この写真では、塗った赤と、焼いた土の地の色との境目は見分けられない。全体が、むらのある薄い橙色に見えるだけである。埴輪の「はに」は、きめの細かい黄赤色の粘土を指す古い言葉で、上代には衣にすりつけて模様を表すのにも使われた、と辞書は説く。辞書の説明と館の記載を重ねると、黄赤色の土を焼いた像に、さらにオーカーをかけている、と読める。"}, {"t": "art", "f": "ni_a4.jpg", "date": "1790〜1800年ごろ", "place": "インド（パハーリー地方・カーングラ派）", "title": "テラスでチャウパルを打つ男女（Couple Playing Chaupar on a Terrace）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1936.683", "note": "館の記載は技法を「赤いオーカーの下描きのある素描（drawing with red ochre underdrawing）」と一行で書くだけで、解説は付いていない。19.4×13.2cm。屋根の下のテラスで、男と女が向かい合って座り、あいだには細長い板を十字に組んだような盤が置かれている。女は小さな棒のようなものをつまみ、男は盤へ手を伸ばす。まわりに女が四人——左上のひとりは腕を伸ばして指さし、右上のひとりは長い柄のついたものを掲げている。灰色の細い線の下に、薄い赤の線が見える。男の膝まわりの衣や女の裾のあたりでとくにはっきりしていて、赤い線と灰色の線は、ところどころずれている。赤で先に形を取り、あとから灰色の線で引き直した跡に見え、館の言う「赤いオーカーの下描き」は、この赤い線のことだと読める。⚠️ ただし、この赤が土かどうかを一枚の写真から確かめる手立てはない。ここでは館の記載に従っている。"}, {"t": "art", "f": "ni_a5.jpg", "date": "1820年代", "place": "ニュージーランド（マオリ・テ・アラワ）", "title": "テコテコ（切妻の像）（Tekoteko (gable figure)）", "artist": "マオリの作者", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/313626", "note": "館の記載は材料を「木、塗料（Wood, paint）」とし、テ・アラワ（マオリの部族）の作、1820年代とする。テコテコは、家の切妻屋根の頂に立てる像である。高さ66cm。全身が赤く、腕と胴のすきまや、脚のあいだの奥は黒い。胸の前に握ったものは白い。大きく開いた口のまわりや、肩と腿の渦巻きには細かな刻みがびっしり入っている。赤は一様ではなく、眉の出っ張りや向かって右の腿の渦巻きでは擦れたように明るい茶色がのぞき、額の細かな刻みの奥には白っぽいものが残って見える。目には渦巻きのある白っぽい円盤がはまっているが、何でできているかは記載にない。足もとには、もうひとつ小さな顔がある。⚠️ マオリには、鉄を多く含む土を焼いて赤みを強め、サメの肝の油などと練ったコーコーワイを彫刻に塗る習いがあった、とオークランド博物館の学芸員ルイーズ・フューリーは書く。同じ人は、20世紀のはじめに博物館で、彫刻に赤い塗料が、ときにはもとの多色の彩りの上から塗られたことも書いている。館がこの像の赤を「塗料」とだけ書き、何の赤かを言っていない以上、この赤が土なのか、のちの時代の塗料なのかは、この一枚からは決められない。"}, {"t": "photo", "f": "ni_p1.jpg", "date": "いま（2017年）", "place": "オーストラリア・ノーザンテリトリー（ウェスト・マクドネル国立公園）", "title": "オーカー・ピッツ（写真）", "author": "Ian Cochrane", "lic": "CC BY 2.0", "url": "https://commons.wikimedia.org/wiki/File%3AOchre_Pits_IMG_2019_NT_%2825370100798%29.jpg", "note": "撮影者の説明は「Ochre Pits IMG_2019 NT」だけ。写真に記録された撮影日は2017年10月21日で、位置は南緯23.7度・東経132.9度、Commons ではウェスト・マクドネル国立公園の写真に分類されている。真っ青な空の下に、土の壁が一枚立っている。左半分は淡い黄とクリーム色で、斜めの筋が何本も走り、右半分は暗い、紫がかった赤。壁の足もとには赤い土がこぼれて小さな斜面をつくり、手前は小石まじりの乾いた地面で、草の株がいくつか。右端から、細い葉の枝がかかる。オーカー・ピッツはアリススプリングスの西およそ110km、アレンテの人びとの土地にあり、中央オーストラリアで訪れる人に開かれた唯一のオーカーの採掘場で、いまも伝統的な持ち主による採掘がつづくと説明される。色は白から土色の茶、黄・橙・赤まで幅があるという。⚠️ 黄が針鉄鉱、赤が赤鉄鉱だと、この写真の色だけから決めることはできない（分析の記載はない）。見えているのは、黄と赤が一枚の壁に並んでいること、それだけである。"}]}, {"id": "dorozome", "no": "第十五景", "kind": "tsuchi", "name": "泥染め", "yomi": "どろぞめ", "en": "Dorozome — mud dyeing: iron in the earth binds plant tannins into the cloth", "rep": "dorozome_a3.jpg", "lead": "泥で染める、と聞くと、泥の色が布に移るのだと思いやすい。けれど泥染めの黒は、泥の色ではない。先に植物の渋で染めておいた糸や布が、泥の中の鉄に出会って、はじめて黒へ寄っていく。泥は、色を運ぶのではなく、色を定める。", "layers": [["鉄が、渋を黒くする", "泥染めの黒は、泥の色が布に移ったものではない。多くの説明に共通するのは、植物に含まれるタンニン（渋のもとになるポリフェノールの一群）と、泥に含まれる鉄が、繊維の上で結びついて黒っぽい化合物をつくる、という筋である。鉄とタンニンで黒をつくる仕組みは、昔の没食子インク（没食子のタンニンと鉄の塩で書いたインク）と同じだとされる。染めの言葉では、色を繊維に留める金属のはたらきを媒染（ばいせん）と呼び、泥染めでは泥の中の鉄がその役を受け持つ。だから手順はどこでも二段になる。先に渋の多い植物の汁で染め——奄美ではシャリンバイ（テーチ木）の樹皮、広東では薯莨（しょりょう）の塊根——それから泥に触れさせる。マリでは、葉の汁で黄に染めたあとに泥を塗る。植物の汁で染めただけでは色は黄や赤茶の側にとどまり、泥に触れて黒へ寄っていく、と説明される。⚠️ どの泥に、どの形の鉄がどれだけ含まれるかは土地ごとに違うので、ここでは数を挙げない。"], ["浸ける、塗る、描く", "泥の使い方は土地ごとに違う。奄美大島の大島紬は、布ではなく糸を染める。シャリンバイの樹皮を長く煮出した汁に絹糸を揉みこむことを何十回も重ね、泥田の泥に浸けることも繰り返す。テーチ木で染めた糸はピンクに寄り、そこへ泥染めを重ねるうちに灰、赤茶、黒へと変わっていく、と説明される。薩摩藩は1720年（享保5年）に、島役人のほかが紬を着ることを禁じた、と伝えられる。広東・順徳の香雲紗（こううんしゃ。莨綢とも呼ばれる）は、織りあがった絹を薯莨の汁で何度も染めては日に干し、そのあとで河の泥を片面にだけ塗って草地に広げ、洗い流す。表は黒く、裏は黄褐色に残る。この染めと仕上げの技は、2008年に中国の国家級無形文化遺産の名録に入った。マリのボゴラン（bògòlanfini）は、細く織った木綿を縫い合わせ、葉の汁で黄に染めてから、川底から集めて壺で長いと一年ほど寝かせた泥で文様を描く。泥の触れなかった黄色は、あとで抜いて白くする。同じ泥でも、糸を浸すか、布の片面に塗るか、線で描くかで、黒の置き場所が変わる。"], ["土から離れられない技", "泥染めは、その土地の土から離れにくい。広東の香雲紗は順徳の倫教あたりの河泥でなければならない、と作り手の側は言う。奄美では、染まりが悪くなった泥田にソテツの葉を入れる、と言われる。マリの bògòlanfini という語は、bɔgɔ（土・泥）と lan（〜で）と fini（布）からなるとされ、bògòlan は、ただの泥ではなく、鉄の多い粘土を指すという。布の名前や作り方の中に、特定の土が書きこまれている。いっぽうでボゴランは、1980年ごろからマリの文化の象徴として国に推され、2000年ごろには型紙を使う簡略な作り方で、観光と輸出向けに大量に作られるようになった、とも説明される。土から離れられない技が、土から離れた形で世界に出ていく。⚠️ 泥染めの布は体に良い、虫を寄せつけない、といった言い方があるが、この景では確かめていないので扱わない。"]], "invite": "濃く淹れた紅茶に白い木綿の端切れを浸して乾かす。別に、台所用の鉄たわし（スチールウール）をひとつまみ、酢に二、三日浸けておく（瓶のふたは固く閉めない）。その液を端切れに一滴落として、茶色が灰色から黒のほうへ寄るかどうかを見る。泥田の泥がしている仕事の、いちばん小さな模型である。（液は口に入れず、終わったら水でうすめて流す。）", "works": [{"t": "art", "f": "dorozome_a1.jpg", "date": "1848年（道光二十八年刊）", "place": "中国（清。図の草は閩・廣＝福建・広東あたりの山に産するとされる）", "title": "薯莨（しょりょう）──『植物名實圖考』卷九・山草類の図", "artist": "吳其濬（撰）", "museum": "Wikimedia Commons（中国語版ウィキソースの道光刻本スキャン 第9冊 56葉と同じ図）", "lic": "パブリックドメイン", "url": "https://commons.wikimedia.org/wiki/File:%E6%A4%8D%E7%89%A9%E5%90%8D%E5%AF%A6%E5%9C%96%E8%80%83%C2%B7%E8%96%AF%E8%8E%A8.jpg", "note": "木版の線画。細い蔓がうねりながら上へ伸びて枝分かれし、その先は巻きひげのように丸まる。茎には短い刺が点々と並び、葉は細く尖っている。根もとには、点を打った丸い塊が四つ、斜め下へ数珠のように連なり、塊のまわりから毛のような根が四方へ出ている。次の頁で吳其濬は書く——閩・廣（福建・広東あたり）の山に産し、蔓で、葉は尖って長く、節ごとに小さな刺がある。根は山薬のようで毛があり、大小ふぞろい、外の皮は紫黒、中の肉は紅黄。土地の人はその根を掘り、煮た汁で網を染める。続けて李調元『南越筆記』を引き、「薯莨膠液本紅見水則黑」——薯莨の汁はもとは紅く、水に会うと黒くなる、と写す。⚠️ 引かれた文は、黒くなる理由を「魚は火に属して水を好む」という魚の性で説明している。水の中の鉄と結びつくから、とはどこにも書かれていない。そう読むのは、いまのこちら側である。本文は「毎年一節を生ず」とも書くが、図の四つの塊を四年と読めるかは、この一枚からは決められない。また本文は「花が無い」と書くが、いまの植物の記載は、薯莨に穂状の花序があるとする。吳其濬は1847年に没し、書はその翌年（1848年）、太原府知府の陸應穀が校刊した。"}, {"t": "art", "f": "dorozome_a2.jpg", "date": "19世紀末〜20世紀初め（清末）", "place": "中国・広東", "title": "衣装（Costume）", "artist": "作者不詳", "museum": "ホノルル美術館（写真は Wikimedia Commons・撮影 Hiart、2016年）", "lic": "CC0", "url": "https://commons.wikimedia.org/wiki/File:Costume_from_China%2C_Guandong%2C_Honolulu_Museum_of_Art_12863.1-2.JPG", "note": "展示室で撮られた写真。Commons に写真を上げた撮影者が書き写した館の記載によれば、清末（19世紀末〜20世紀初め）の広東の衣装で、材料と技法は「絹、薯莨（Dioscorea cirrhosa）、泥染め（mud dye）、紋紗織、手縫い」。所蔵番号は12863.1-2。写っているのは、袖に棒を通して白い壁に掛けた、丈の長い上衣が一着である。色は黒に近い炭色で、光の当たる袖や胸は灰色に白んで見える。立ち襟で、襟もとから向かって左の脇へ合わせの線が弧を描き、結び玉の留め具が襟もとと脇に付いている。襟の内側には、外より明るい色の面に、小さな菱形が網目のように並んでいるのがのぞく。書き写された記載にある紋紗（模様を織り出した紗）の目と見えるが、その明るさが布の裏の色なのか、光に透けた色なのかは、この写真からは決められない。⚠️ 材料の記載は、撮影者が書き写したものを館のデータベースで照らし合わせることができなかった。薯莨で染めてから泥をかけて表を黒くする広東の絹は香雲紗と呼ばれるが、書き写された記載にこの名は無い。この衣が香雲紗かどうかは、ここでは言わない。"}, {"t": "art", "f": "dorozome_a3.jpg", "date": "1900年代初めごろ（1917年に館へ寄贈）", "place": "フィリピン・ミンダナオ島南東部（マンダヤの人びと）", "title": "マンダヤの絣布（ダグマイ ／ Mandaya ikat textile (dagmay)）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1917.748.a", "note": "アバカ（マニラ麻）の糸で織った平織の布。館によれば、ミンダナオ南東部のマンダヤの絣で、経糸の一部をあらかじめ固く縛ってから染め、縛ったところを染め残して、織ると文様が現れるようにする。縦に長い布の両脇に、赤茶と生成りの細い縞が走る。内側の三つの列は焦げ茶の地で、そこに生成りの文様が抜けている——腕を上げて脚を曲げた人のような姿、菱形に曲線の腕が絡んだ形、ぎざぎざの山形。館は、文様がマンダヤの宇宙観を映し、守りや豊穣、祖霊（umagad）と結びつけられてきたと記す。下の端では経糸がほつれて房になっている。館は別の欄に、この種のアバカの絣布は織りあがったあと鉄分の多い川の泥に浸けられ、それで茶と黒が深まり、繊維が強くなり、染めが定まった、と書く。⚠️ これはこの種の布についての一般の説明で、この一枚が泥に浸けられたかどうかを、館は個別には書いていない。「繊維が強くなる」も館の記載をそのまま写した。大きさは157.8×78.7cm。ほぼ同じ文様の一枚（1917.748.b）と組になっている。"}, {"t": "bun", "date": "1917年（上海・商務印書館刊）", "place": "中国（上海で刊行。記述は福建・広東の植物）", "title": "『清稗類鈔』植物類「薯莨」", "author": "徐珂", "quote": "皮紫黑色。肉紅黃色。煑汁以染紗絹之屬。爲暑月之衣。", "src": "1917年上海・商務印書館刊の初版。Internet Archive の qingbaileichao924148xuke（イリノイ大学蔵本・第41〜48冊を一つに綴じたスキャン）の植物類81頁（画像の376葉目）を画像で開いて一字ずつ読み、中国語版ウィキソース『清稗類鈔/099』（植物類一）の本文と突き合わせた。違いは字体と句読点だけで、ウィキソースは煑を煮、爲を為、産を產と書き、句点を現代の句読点に直している。見出しの「薯莨」の莨は、1917年の印刷では艸に艮（茛）に見える（→台帳）。引用はスキャンの字体に従った。徐珂は1869〜1928年の人（生年を1868年とする資料もある）", "note": "「皮は紫がかった黒、中身は赤みのある黄。煮た汁で紗や絹のたぐいを染め、夏の衣にする」（この作品の訳）。項はこう続く——これを薯莨綢、また拷綢という。広東の人はこれで漁の網も染める。苧麻の網を張りのある丈夫なものにし、水切れがよく、潮にも強く、腐りにくいからだ、と。1917年のこの書は、夏の絹と漁の網を、同じ汁の二つの使い道として並べている。前半は七十年前の吳其濬（a1）の本文と、後半は吳其濬が引いた『南越筆記』と、言い回しがほとんど同じである。徐珂がどこから写したかは、項には書かれていない。⚠️ 泥のことは、この項のどこにも書かれていない。薯莨で染めた絹に泥をかける仕上げはこの項の外の話で、ここからは読めない。"}, {"t": "art", "f": "dorozome_a4.jpg", "date": "1945年以前（戦前の絵葉書）", "place": "日本・鹿児島県（大島紬の産地。絵葉書に地名は刷られていない）", "title": "大嶋紬原料ヲ染メル圖（其二）・絵葉書", "artist": "撮影者不詳", "museum": "Wikimedia Commons（戦前の絵葉書。Commons の出典は那覇市歴史博物館のデジタルアーカイブ）", "lic": "パブリックドメイン", "url": "https://commons.wikimedia.org/wiki/File:Colour_materials_of_Oshima-tsumugi.jpg", "note": "写真の絵葉書。下の余白に「大嶋紬原料ヲ染メル圖（其二）」と刷られ、英語で「COLOUR MATERIALS OF OSHIMATSUMUGI.」と添えてある。左端には版元の名が小さく刷られているが、この画像では読み切れない。水の張った田に五人が入っている。四人は腰をかがめて両手を水に沈め、左端の一人だけは脛から膝ほどの深さに立って、腰のあたりで何かを手にしている。鍔のある帽子をかぶった人が多い。奥には茅葺きの家が並び、右手には石垣が見える。⚠️ 題は「染める」と言うだけで、泥の字は無い。これを泥田での泥染めと読むのは、大島紬の染めが泥田で行われるという説明に照らした、こちら側の読みである。何を水に沈めているのかも、この一枚からは見えない。同じ題の（其一）には、少年たちが桶で糸を揉み、黒い糸の束が竿に何十も干されている場面が写っている。"}, {"t": "art", "f": "dorozome_a5.jpg", "date": "1972年以前（1972年に館へ寄贈）", "place": "マリ（バマナの人びと）", "title": "ボゴランの布（Bogolan-weefsel）", "artist": "作者不詳（館の作り手の欄は「Bamana［volk］」＝バマナの人びと）", "museum": "MAS（Museum aan de Stroom・ベルギー、アントワープ。写真は Wikimedia Commons 経由）", "lic": "CC0", "url": "https://commons.wikimedia.org/wiki/File:Bogolan-weefsel%2C_asset_oNCMiENcQdYrUSRTTphtAx1o.tif", "note": "黒い地を背に撮った館の写真。縦に長い布で、紫がかった焦げ茶の地に、黄土色の三角が左右の二列に向きを変えながら並び、そのあいだに焦げ茶の地がジグザグに残る。二列のあいだを黄土色の太い縦帯が一本通り、上と下の端の近くにも横帯が一本ずつ走る。布には細い白い縫い目が縦に四本見える。館の記載によれば、マリの布で、在来の木綿の細い帯を五本縫い合わせ、二列のジグザグ文様で飾ったもの。材料の欄には「木綿、泥（modder）」とある。館は続けて、細い帯織りは伝統的に男が織って衣に仕立て、その布を女が bogolan という手わざで飾ると書く——泥と自然の材料で布に文様を置く、何世紀も前からのやり方だという。そして、伝統的には女だけが描いてきた bogolanfani（泥の布）は、誕生・成人の儀礼・結婚・死という人生の節目と結びついてきた、と記す。大きさは67×144cm、1972年に寄贈された。⚠️ 年代は館の記載に無く、寄贈の年より前としか言えない。景の本文（二の層）では「泥の触れなかった黄色は、あとで抜いて白くする」と書いたが、この布の明るいところは白ではなく黄土色に見える。黄を抜かずに残した作り方なのか、年月や写真の色でそう見えるのかは、この一枚からは決められない。"}, {"t": "photo", "f": "dorozome_p1.jpg", "date": "いま（2007年）", "place": "マリ・ドゴンの土地（サンガ村）", "title": "ボゴランの染め場（写真）", "author": "BluesyPete", "lic": "CC BY-SA 3.0", "url": "https://commons.wikimedia.org/wiki/File:BogolanMali4.JPG", "note": "撮影者の説明は「ボゴランの染め場——サンガ村、ドゴンの土地、マリ」、撮影日は2007年11月27日。土の壁に、大きな布が一枚掛けてある。黄土色の地に、黒い太い線と白い細い線で、三角、格子、点、S字、そして菱形の左右に曲線の腕を伸ばした形が、額縁のように幾重にも組まれている。右の低い壁にも、菱形を並べた布がもう一枚。壁の土と布の地が、ほとんど同じ色をしている。⚠️ この二枚が泥で描かれた布なのかは、写真からは決められない。ボゴランには型紙を使う簡略な作り方もあり、2000年ごろからは観光と輸出向けに大量に作られている、と説明される。"}]}, {"id": "kawara", "no": "第十六景", "kind": "tsuchi", "name": "瓦", "yomi": "かわら", "en": "Kawara — roof tile: clay pressed in a mould, fired, and laid to shed the rain", "rep": "kawara_a3.jpg", "lead": "粘土を型に押しつけ、乾かし、窯で焼いて、屋根に並べる——瓦。焼いた土は、もう雨に溶けない。瓦は大陸から半島へ、半島からは寺といっしょに列島へ渡り、軒先の一枚には、文字や花や顔が入れられてきた。", "layers": [["焼くと、泥に戻らなくなる", "干しただけの粘土は、水に浸せばまた泥に戻る。窯で焼くと、もう戻らない。粘土のおもな鉱物の一つカオリナイトは、500℃ほどに熱すると結晶の中の水酸基を手放して、粘土としての性質を失う。さらに温度を上げると、粒どうしが溶けきらないまま境目でくっつき合い、締まって硬くなる——これを焼結という。愛知の三州瓦は、およそ1,150℃で焼き締めるとされる。それでも焼きものには細かな孔が残り、水を吸う。しみこんだ水が凍ると体積が11分の1ほどふくらみ、内側から瓦を割ったり、表面をはがしたりする（凍害）。だから日本の規格（JIS A 5208）は瓦の吸水率に上限を置いて、釉薬瓦と無釉の瓦は12％以下、いぶし瓦は15％以下とし、必要なときは凍結の試験も課す。いぶし瓦の銀色は、900〜1,000℃ほどに焼けた瓦を空気から断ち、炭化水素のガス（かつては松の割り木や松葉を焚いた煙）を当てて、表面に1〜3マイクロメートルの炭素の膜をつけた色とされる。その膜が光を返して、あの鈍い銀になる。"], ["寺といっしょに、海を渡った", "中国の瓦は、少なくとも西周（前1050ころ〜前770）まではさかのぼることができるとされ、陝西省岐山の鳳雛村にある西周初期の宮殿跡からは大きな平瓦が出ている。軒先に並ぶ丸瓦の口をふさぐ瓦当（がとう）は、西周の半円形の素朴なものから始まるとも、春秋時代に現れるともいわれ、資料によって幅がある。戦国時代には、各地の城で半円の瓦当が文様で飾られるいっぽう、秦で円い瓦当があらわれた。この景に並ぶ前漢の二枚も、円い。朝鮮半島では、百済の瓦当の文様が、中国の南朝のものをまっすぐ取り入れたとされる。その百済から588年、寺を建てる工人の一行に四人の瓦博士が加わって海を渡った、と『日本書紀』は記す。同じ年に飛鳥寺（法興寺）の造営が始まり、日本で瓦がつくられたのはここからとされる。そのころ宮殿はまだ板葺きや茅葺きで、宮殿が瓦で葺かれるのは持統天皇の藤原宮からとされる。日本では、瓦はまず寺の屋根として、仏教と同じ道を通ってきた。"], ["軒先の一枚に、文字と花と顔", "軒先に並ぶ瓦の端は、雨をいちばん先に受け、下を通る人の目にもいちばん触れる。そこに、文様が入れられた。漢の瓦当には「長楽未央」「長生無極」「千秋万歳」といった吉祥の四字が型で押された。文字の瓦当は前漢の景帝のころ（前157〜前141）に現れた可能性があり、前漢の中ごろから後期に盛りを迎えたとされる。仏教が広まると、中国の南北朝の軒先には蓮の花が咲き、その花は半島と列島の軒先へも渡った。飛鳥寺の軒丸瓦も、素弁蓮華文（花びらの中に飾りのない蓮の文様）である。棟の端をふさぐ鬼瓦は、日本では白鳳時代まで主に蓮華文で、鬼の顔が現れるのは天平時代からとされ、その顔は魔よけの意味をもつと説明される。地中海では、ギリシアやエトルリアの神殿の軒先に、同じ役目の飾り瓦（アンテフィクサ）が並び、その顔にはゴルゴンの首も選ばれた。東と西の「軒先の顔」がつながっていたかどうかは、ここからは分からない。文字は、いまも瓦に書かれる。韓国の寺では、堂を建てるときなどに、人びとが瓦を一枚ずつ求めて願いや名前を書き、寺がそれを屋根に使う——瓦仏事（기와불사）と呼ばれる。"]], "invite": "瓦屋根の寺や古い家の前を通ったら、道から軒先を見上げて、丸い瓦の端に何が入っているかを見てみる——花か、文字か、家の紋か、顔か、何も無いか。棟の端の鬼瓦も見る。雨の日なら、瓦の列から水がどこへ落ちているかも。（屋根には上らない。見るのは道から。）", "works": [{"t": "art", "f": "kawara_a1.jpg", "date": "前500年ごろ", "place": "イタリア南部・ターラント（館の記載は Greek / South Italian）", "title": "ゴルゴネイオンのアンテフィクサ（軒先の飾り瓦）（Gorgoneion Antefix (Ornamental Roof Tile)）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2021.3", "note": "型で抜いた素焼きの土。ほぼ円い面いっぱいに、ひとつの顔がある。アーモンド形に見開いた目、歯と牙をむき出して笑うように開いた口、その口から大きく垂れた舌。額の上には渦巻く巻き毛が一列にならび、顔のまわりを S 字にうねる蛇が囲んで、右上では二匹が鎌首を立てている。上の縁は割れて欠けている。館はこれを、屋根瓦の一種である飾り瓦（アンテフィクサ）で、首だけになったゴルゴン——ゴルゴネイオン——をかたどったものと記し、顔料の痕から、もとはもっと鮮やかで、恐ろしいと同時に守るものと考えられたのかもしれない、と書く。アンテフィクサは、軒に並ぶ覆い瓦の端をふさいで継ぎ目を雨から守る部材で、東アジアの瓦当と同じ場所に立つ。⚠️ 900px の画面では、顔料の痕は見分けられない。高さ24.5cm。"}, {"t": "art", "f": "kawara_a2.jpg", "date": "前206〜後9年（前漢）", "place": "中国（前漢）", "title": "吉祥の文字のある瓦当「長樂未央」（Roof-Tile End with Auspicious Inscription）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/44399", "note": "焼いた土（土器）の円盤。二本線の十字が面を四つに割り、中心の丸い突起を小さな粒の輪が囲む。四つの区画に一字ずつ、線の太い字が浮き出ている。館は英語では「吉祥の銘のある瓦当」とだけ題し、公開目録の中国語の題で、この四字を「長樂未央」と読む。その読みに字を当てると、右上が長、右下が樂、左上が未、左下が央に見え、右の列から縦に読むことになる（この作品の読み）。「長楽未央」は、楽しみは長く、まだ尽きない、という意味の吉語である（この作品の訳）。館はもう一枚、裏から撮った写真も公開していて、上の縁に沿って割れ口が弧を描いている。ここから後ろへ半円筒の丸瓦が伸びていたとみるのが自然だが、⚠️ それは写真からの推測で、館の記載にはない。直径19.4cm、厚さ4.1cm。"}, {"t": "art", "f": "kawara_a3.jpg", "date": "前206〜後9年（前漢）", "place": "中国（前漢）", "title": "虎の瓦当（四神のうち白虎）（Roof tile end with tiger）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/49528", "note": "土器の円盤の内側に、一頭の獣が浮き彫りになっている。左を向いて口を開き、前足を一本高く上げ、胴には縞の線が刻まれる。背と腰からは、渦を巻いて S 字に立ち上がる線が二本。円の中心には、長樂未央の瓦当と同じく丸い突起があり、ここでは獣の胴に重なっている。館は英語では「虎の瓦当」、公開目録の中国語の題では「四神陶瓦當―白虎」とする——東西南北を守る四つの神獣（青龍・白虎・朱雀・玄武）のうち、西の白虎にあたる、という読みである。外側の縁は幅が広く、表面が荒れて剥がれている。直径18.4cm、奥行き4.8cm。⚠️ 同じ館が同じ1918年に受け入れた隣の番号の一枚（18.56.31）は、中国語の題を「四神紋瓦當（白虎/朱雀）」と両論併記していて、画面には翼のある鳥が見える。館の読みにも揺れがある。"}, {"t": "art", "f": "kawara_a4.jpg", "date": "700〜800年代（統一新羅）", "place": "朝鮮半島（統一新羅）", "title": "瓦当（Roof End Tile）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/42264", "note": "炻器（せっき）。展示室で、灰色の台の上に立てて撮った一枚で、館が公開している写真はこれだけである。円い面の中心に小さな丸い突起があり、そのまわりを花弁が内と外の二重にめぐる。外の花弁は輪郭が二重で、ひとつひとつの中にも小さな盛り上がりがある。その外を一本の線が囲み、縁には小さな珠の粒が一周ならぶ。右下には割れ目が走る。花の文様は、朝鮮半島と日本の軒先に多い蓮華文によく似て見える——⚠️ ただしそれはこちらの見立てで、館は文様の名を記さず、題は「Roof End Tile」、年代は8〜9世紀、材は炻器、とだけ書く。寸法は幅14cm・直径7.9cmと記録されているが、二つの数が何を測ったものかは記載からは分からない。"}, {"t": "bun", "date": "720年（記事は588年・崇峻天皇元年）", "place": "日本（記述は百済から渡った工人）", "title": "『日本書紀』巻第二十一 崇峻天皇元年是歳条", "author": "舎人親王ら撰", "quote": "寺工太良未太。文賈古子。鑪盤博士將徳白昧淳。瓦博士麻奈文奴。陽貴文陵貴文。昔麻帝彌。畫工白加。……始作法興寺。", "src": "中国語版ウィキソース『日本書紀/卷第廿一』の本文で引用し、韓国・国史編纂委員会の韓国史データベース「日本六国史 韓国関係記事」jm_001_0180_0030 の原文、および国立国会図書館の次世代デジタルライブラリーが文政三年（1820）刊本『日本書紀』のスキャンから起こした OCR 本文と突き合わせた。四人の名などの字は版によって揺れる——国史編纂委員会の原文は「㥄貴文」、ウィキソースと文政刊本は「陵貴文」。国史編纂委員会の原文は「鑢盤博士」「將德」、ウィキソースは「鑪盤博士」「將徳」。文政刊本の OCR は「白味淳」と読む。明治〜昭和の書物には「麻奈父奴」と引くものが多い。句読点（。）と、省いた部分の「……」の前後はウィキソースのまま。『日本書紀』は養老四年（720）に舎人親王らが撰上した", "note": "「寺の工人、太良未太と文賈古子。鑪盤の博士、将徳の白昧淳。瓦博士、麻奈文奴・陽貴文・陵貴文・昔麻帝彌。画工、白加。……はじめて法興寺をつくる」（この作品の訳）。百済が仏舎利と僧を送ってきた年の記事で、僧の名のあとに、寺工・鑪盤博士・瓦博士・画工と、職の名が続く。瓦は、ひとりで来たのではなく、寺を建てる仕事の一式の中にあった。同じ年、飛鳥の真神原で法興寺（飛鳥寺）の造営が始まる。これが日本で瓦がつくられた始まりとされる。⚠️ 鑪盤博士は、塔の頂の相輪など金属の部分を受け持つ工人とみられているが、記事そのものに役目は書かれていない。四人の名の字は版によって揺れる（→台帳）。"}, {"t": "bun", "date": "1145年（記事は880年・憲康王六年）", "place": "朝鮮半島（高麗・記述は新羅の王都）", "title": "『三国史記』巻第十一 新羅本紀 憲康王六年九月条", "author": "金富軾ら撰", "quote": "九月九日，王與左右，登月上樓，四望，京都民屋相屬，歌吹連聲。王顧謂侍中敏恭曰：「孤聞今之民間，覆屋以瓦不以茅，炊飯以炭不以薪，有是耶？」", "src": "中国語版ウィキソース『三國史記/卷11』（新羅本紀第十一）の本文で引用し、韓国・国史編纂委員会の韓国史データベース『三国史記』sg_011_0050_0170 の原文（玉山書院本〔1573〕・正徳本〔1512〕による校勘本文）と突き合わせた。異同は三つ——国史編纂委員会は「民閒」と書き、校勘注029で「間の異体字」とする（ウィキソースは「民間」）。国史編纂委員会は「登月上樓四望」と区切らずに続ける。引用のすぐ後、敏恭の答え「臣亦嘗聞之如此」の「嘗」を、国史編纂委員会は「甞」と書く。『三国史記』は高麗の金富軾らが1145年に撰進した", "note": "「九月九日、王は側近たちと月上楼に登り、四方を見わたした。都の民の家は軒を連ね、歌と笛の音が絶えない。王は侍中の敏恭をふり返って言った。『聞けば、いまの民は屋根を茅でなく瓦で葺き、飯を薪でなく炭で炊くという。まことか』」（この作品の訳）。敏恭は「臣もそのように聞いております」と答え、王の徳をたたえる。瓦の屋根と炭の火が、都の豊かさのしるしとして王の口から語られている——茅と薪は、それまでの暮らしの側にある。⚠️ これは王が「聞いた」話と、臣下の答えを記した記事で、都の家がすべて瓦葺きになったという調べではない。書かれたのも、出来事から二百六十年あまりのち、高麗の時代である。"}, {"t": "art", "f": "kawara_a5.jpg", "date": "1300年代後半〜1400年代", "place": "東南アジア・タイ中北部（スコータイの窯）", "title": "マカラの形の棟飾り（アンテフィクサ）（Architectural antefix in form of a makara finial）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/828454", "note": "炻器に鉄の茶色で文様を描き、その上から釉を掛けて焼いたもの（館の記載は iron-brown underglaze décor＝鉄褐色の釉下の絵付け）。四角い台の上に、獣が胸を張って座る。大きく開いた顎には尖った歯が上下にならび、丸い目玉が飛び出し、頭の後ろからは炎のような形の飾りが高くそびえる。首から胴にかけては、うろこの模様。館はこれを、スコータイの窯で焼かれた、マカラ（インドの神話に出てくる怪魚）の形の棟飾りで、アンテフィクサと呼ぶ。ギリシアのゴルゴンの飾り瓦と同じ「アンテフィクサ」の語が、館の題に使われている。館が公開する別の角度の写真では、背の側の足もとがアーチ形に口を開け、中が空洞になっている。⚠️ それを屋根のどこに、どう据えたかは、館の記載にない。高さ70.5cm。"}, {"t": "photo", "f": "kawara_p1.jpg", "date": "いま（2009年）", "place": "韓国・慶尚北道慶州市（石窟庵）", "title": "石窟庵の鐘楼の屋根（写真）", "author": "myllissa", "lic": "CC BY 2.0", "url": "https://commons.wikimedia.org/wiki/File%3AKorea-Gyeongju-Seokguram-Bell_Pavilion-01.jpg", "note": "撮影者の説明は「Seokguram-Bell Pavilion」（石窟庵の鐘楼）だけで、Flickr での元の題は「Buddhist temple roof top」、撮影日は2009年4月8日。白くとんだ空を背に、瓦で葺いた屋根がいくつか重なって見える。屋根の面には、半円の筒の形の丸瓦が上から下へ何列も並び、列が軒先で終わるところごとに、円い面の瓦当が一枚ずつこちらを向く。丸瓦の端と端のあいだ、平瓦の列の先には、下へ垂れた形の瓦がはさまっている。瓦当の面に何かが浮き出ているのは見えるが、何の文様かは900pxの画面では見分けられない。棟の端には黒っぽい尖った瓦が立ち、まんなかには白い壺のような飾りが立って、その先に細い棒が伸びる。瓦の列の下、垂木の端とみられる丸い面には、花の形の彩色が一つずつ並ぶ——これは瓦ではなく、木に塗った色（丹青。Commons の分類も Dancheong）とみられる。⚠️ 瓦当の文様の名も、この屋根の瓦がいつ焼かれたものかも、撮影者は書いていない。"}]}, {"id": "tsuka", "no": "第十七景", "kind": "tsuchi", "name": "塚", "yomi": "つか", "en": "Tsuka — the mound: earth heaped up to mark a place, over the dead but also beside roads, as copies of a sacred mountain, and out of discarded shells", "rep": "tsuka_a5.jpg", "lead": "土を盛り上げると、平らな地面に一点、目じるしが立つ。人は墓の上にも、道のりの区切りにも、遠い山を写す場所にも土を盛り、食べ終えた貝の殻も同じ場所に積み上げてきた。盛った土は、少しずつ崩れながら、何百年、何千年と形を残す。", "layers": [["盛った土が、残るわけ", "盛る土は、たいていすぐそばを掘って得る。世界遺産の百舌鳥・古市古墳群の説明では、墳丘は濠や周りを掘って出た土を盛り上げてつくられ、斜面は25度前後の坂と平らな段を組み合わせて2〜3段に築かれた。土・粘土・礫を使い分け、細かい単位で規則正しく積んだ層が見つかった古墳もある。土は薄く広げては突き固めるのを繰り返すと、粒のすき間が詰まって重く硬くなり、水も通しにくくなる——いまの盛土の工事でも基本になっている締め固めである。それでも雨は表面を打ち、斜面を流れる水が少しずつ土を運び去る。古墳の斜面に人の頭ほどから拳ほどの石を葺いた葺石には、盛土の崩れを防ぐ意味もあったと考えられている。新羅の王陵には、墳丘の裾を石で囲んだもの（護石）があり、韓国の国家遺産庁は、この石ははじめ墳丘を守る役目だった、と説明する。草や木が土を覆っているあいだ、削られ方はずっと遅く、覆いを剥がすと速くなる。ジェファソンは、ヴァージニアの塚が木を払って畑にされてからおよそ12年で、高さ約12フィート（およそ3.7m）から7フィート半（およそ2.3m）まで、畑を耕す鋤で削られた、と書いている（雨ではなく、鋤による削れである）。⚠️ もとの高さは本人が about（およそ）と書いた見積もりで、どう測ったのかは書かれていない。"], ["塚を盛った人たち", "前一千年紀の朝鮮半島では、大きな石の板を組んだ墓——支石墓（ドルメン）——が数多くつくられ、高敞・和順・江華の遺跡群は2000年に世界遺産になった。同じころ、黒海の北からカザフスタンにかけての草原では、馬とともに暮らす人びとが大きな塚（クルガン）を築いた。ヘロドトスは前5世紀に、スキタイの王の墓に皆で土を盛るようすを書き留めている。カザフスタン南東部のイシク・クルガンでは、1969年の発掘で、四千点を超える金の飾りを縫いつけた衣の埋葬が見つかったとされ、葬られたのが若い男だったのか女だったのかは、いまも議論が続く。朝鮮半島南部の加耶では1世紀から6世紀の後半にかけて塚が築かれ、七つの塚群が2023年に世界遺産になった。日本列島では、3世紀ごろから7世紀ごろにかけて古墳が築かれたとされる。北アメリカのオハイオ川流域でも、アデナの文化（前800年ごろ〜後100年ごろとされる）の人びとが土を盛って塚を築いた。19世紀のアメリカでは、これらの塚を築いたのは「いまの先住民とは別の、消えた民族」だという説が広く信じられた。それを退け、先住民の祖先が築いたことを示したのは、1894年に出たスミソニアン民族学局のサイラス・トーマスの報告とされる。"], ["墓ではない塚", "塚は、墓だけではない。慶長9年（1604）の定めによって、江戸の日本橋から数えて一里（およそ4km）ごとに、街道の両側へ対の塚が築かれ、多くは上に榎や松が植えられた。東京都北区の西ヶ原一里塚は日本橋から二里の地点にあり、国の史跡に指定された1922年の説明には、道の両側の塚の頂にそれぞれ一本ずつ榎が生えている、とある。富士塚は富士山をかたどった塚で、安永9年（1780）に江戸高田の行者藤四郎が、老若男女だれでも心安く富士に登れるようにと、高田水稲荷の境内に築いたのが始まりとされる。練馬区の江古田の富士塚は高さ約8m、直径約30mで、塚全体が富士の溶岩で覆われている。遠い山を、近くの土で写した塚である。貝塚は、食べたあとの貝の殻などを同じ場所に捨てつづけてできた塚で、日本では縄文時代のものがよく知られる。ただの捨て場とは言い切れず、亡くなった人や飼っていた犬を貝塚に葬った例もある。貝殻のカルシウムが酸性の土を中和するので、ふつうの遺跡では分解されて残らない骨などが、ここではよく残る。日本の土の中では消えてしまうはずのものを、捨てられた殻の塚が守ってきた。オハイオの蛇の形の塚のように、中から埋葬が見つかっていない塚もある。"]], "invite": "近くの神社の境内や公園、古い街道沿いで、まわりより少し盛り上がった土の高まりを探してみる。見つけたら、裾をひとまわり歩いて、草や木に覆われているところと、土がむき出しになっているところを見分ける。雨に削られていくのは、むき出しのほうである。⚠️ 史跡や塚の上には登らない。掘らない。土器のかけらや貝殻が落ちていても拾わず、その場に残す。立ち入りを禁じている場所には入らない。", "works": [{"t": "art", "f": "tsuka_a1.jpg", "date": "前7世紀〜前4世紀", "place": "朝鮮半島（青銅器時代）", "title": "短い首の貯蔵壺（Short-necked Storage Jar）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1986.82", "note": "館の記載＝朝鮮半島・青銅器時代（前1000〜前300年）、土器、直径25.1cm。年代の表記は「600s–300s BCE」で、前7世紀から前4世紀にあたる。赤茶けた素焼きの丸い胴に、短く立ち上がる口がつく。胴の下半分には白いものが斑にこびりつき、左下には青灰色に見えるところもある。これが何なのかを館は書いておらず、この一枚からは決められない。館は、農耕が広まるにつれてこうした土器が大量につくられたこと、細かい粘土でつくった大きな壺は穀物の貯えに使われ、のちに墓に納められて墓の主に添えられたこと、この時代に多くの農民が朝鮮半島から日本列島の西部へ渡り、進んだ稲作と土器づくりを伝えたことを書く。⚠️ ただし墓に納められたというのはこの種の壺についての説明で、この一つがどの墓から出たのかは書かれていない（来歴は1986年のニューヨークの競売から始まる）。この時代の朝鮮半島の墓としてよく知られているのは、土を盛った塚ではなく、大きな石の板を組んだ支石墓のほうである。"}, {"t": "art", "f": "tsuka_a2.jpg", "date": "前6世紀〜前5世紀", "place": "カザフスタン", "title": "鹿の形の衣の飾り板（Garment Plaque in the Shape of a Stag）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/59561", "note": "館の記載＝カザフスタン、前6〜前5世紀、青銅、高さ7.6 × 幅9.5cm。題は「鹿の形の、衣につける飾り板」。鹿は脚を腹の下へ折りたたみ、首をまっすぐ前へ伸ばしている。角は頭から背の上を尾のほうまで、S字の渦をいくつもつないだ一本の帯になって流れ、枝の先は小さな丸い瘤で終わる。角と脚のふちには細かい刻みが並び、目は大きな輪で表される。⚠️ この一枚がどこから出たのかを、館は書いていない（館の公開データでは出土地の欄も発掘の欄も空で、分かるのは2002年に寄贈されたことだけである）。だから、これを塚から出たものと言うことはできない。言えるのは、この時代のカザフスタンの草原で人びとが大きな塚を築いていた、ということまでである。南東部のイシク・クルガンでは、四千点を超える金の飾りを縫いつけた衣が、葬られた人とともに見つかったとされる（この塚の年代は前4〜前3世紀ごろとする見方があり、この飾り板と同じ時代とは限らない）。どこから出たかの記録がないということは、どう掘り出されたかの記録もない、ということでもある。"}, {"t": "bun", "date": "前430年ごろ", "place": "ギリシャ（記述は黒海北岸の草原・スキタイ）", "title": "『歴史』第四巻・七一", "author": "ヘロドトス", "quote": "ταῦτα δὲ ποιήσαντες χοῦσι πάντες χῶμα μέγα, ἁμιλλώμενοι καὶ προθυμεόμενοι ὡς μέγιστον ποιῆσαι.", "src": "『歴史』第四巻（メルポメネ）71章5節。ギリシャ語本文はペルセウス・デジタル・ライブラリー（ゴドリー校訂・1920年）と、ギリシャ語版ウィキソース「Ιστορίαι (Ηροδότου)/Μελπομένη」（同じくゴドリー版に拠る）で照合し、両者が一字一句同じであることを確かめた。意味は、英語版ウィキソース所収のローリンソン訳（George Rawlinson／1812〜1902）『The History of Herodotus』Book 4 と、ペルセウス所収のゴドリー英訳（A. D. Godley／1856〜1925）で突き合わせた。訳はこの作品の訳。ヘロドトスは前5世紀の人", "note": "「こうしたことを終えると、皆で大きな塚を盛る。互いに競い合い、できるかぎり大きくしようと力を尽くして」（この作品の訳）。χοῦσι（クーシ）は土を盛り上げるという動詞、χῶμα（コーマ）はそうして盛った土の山で、一文の中で、盛る動作と盛られた山が同じ語根でつながっている。「こうしたこと」とは、直前に書かれた、地面に大きな四角い穴を掘って王の遺体を納め、そばに従者と馬を殺して葬ることを指す。王の墓地は、ボリュステネス川（いまのドニエプル川）を舟で遡れる果ての、ゲロイ（Gerrhi）の地にある、とヘロドトスは書く。⚠️ ヘロドトスがこれを自分の目で見たのか、人から聞いたのかは、この一節からは決められない。訳にも揺れがある——ローリンソン訳は「できるかぎり高く」、ゴドリー訳は「できるかぎり大きく」と訳す。原文の μέγιστον（いちばん大きく）は、高さとも広さとも言っていない。"}, {"t": "art", "f": "tsuka_a3.jpg", "date": "4世紀〜5世紀", "place": "朝鮮半島（加耶）", "title": "帯の把手の蓋つき杯（Lidded Cup with Strap Handles）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1997.9", "note": "館の記載＝朝鮮半島・加耶（42〜562年）、300〜400年代、自然釉のかかった炻器（館の英語は stoneware）、高さ21.1cm。黒に近い灰色の杯に、小さなつまみのある蓋がのる。蓋の上には短い刻みが輪になって並び、胴には細い稜が何本かめぐる。両脇に帯のような把手が二つ。高い脚には、三角の透かしが上下二段に開いている（館は、脚に並ぶ三角の透かしを加耶の焼き物の決まった特徴と書く）。館は、こうした脚つきの器が知られるかぎり最も早い高温焼成の焼き物であること、灰色は閉じた窯の中で酸素を絞って焼いた結果であること、そして日々の器ではなく、死者に供え物を捧げるためのものだったことを書く。自然釉とは、焼くあいだに燃料の灰が降りかかり、土と溶け合ってできるガラス質の膜のことである。⚠️ どの塚から出たのかは書かれていない（来歴はニューヨークの画廊 Kang Collection から始まる）。加耶の塚は1世紀から6世紀の後半にかけて築かれ、七つの塚群が2023年に世界遺産になった。"}, {"t": "art", "f": "tsuka_a4.jpg", "date": "5世紀〜7世紀", "place": "日本（古墳時代）", "title": "埴輪 踊る人の頭と胴（Head and Torso of a Dancing Figure）", "artist": "作者不詳", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/73800", "note": "館の記載＝日本、5〜7世紀、素焼きの土器。高くとがった帽子の先は前へ折れ、額の上には小さな飾りを並べた帯がめぐる。目と口は細い切れ込みで、鼻だけが盛り上がり、耳は丸い。首には丸い玉を連ねた首飾り。両腕は横へ広げて先を下へ曲げ、胴の下は割れて失われ、黒い台に据えられている。胴には細いひびが幾筋も走る（割れを継いだ跡かどうかは、館は書いていない）。館の説明はこうである——埴輪は、中国の墓の人形のように地下の部屋に葬られたのではなく、土を盛った墓の表面に置かれた。何列にも並べ、倒れないよう一部を土に埋めて、墓の聖なる輪郭をなぞり、あるいはその前に立てた。この人物は踊っているように見え、葬送の儀礼では踊りがよく行われたのかもしれない、とも。⚠️ どの古墳から出たのかは書かれていない。説明のとおりなら、この像も足もとを塚の土に埋めて立っていたことになるが、それをこの一点で確かめることはできない。"}, {"t": "bun", "date": "1785年（パリでの私家版。書きはじめたのは1781年）", "place": "アメリカ（ヴァージニア）", "title": "『ヴァージニア覚え書』第十一問「先住民（Aborigines）」", "author": "トマス・ジェファソン", "quote": "a party passing, about thirty years ago, through the part of the country where this barrow is, went through the woods directly to it, without any instructions or enquiry, and having staid about it some time, with expressions which were construed to be those of sorrow, they returned to the high road, which they had left about half a dozen miles to pay this visit, and pursued their journey.", "src": "『Notes on the State of Virginia』Query XI「Aborigines」のうち、自宅近くの塚（barrow）を掘った記述に続く段の、一文の後半。英語版ウィキソースの1853年リッチモンド版（J. W. Randolph）のスキャン（Notes on the State of Virginia (1853).djvu）から起こした本文で照合し、同じくウィキソースの1802年ボストン版（H. Sprague）のスキャンから起こした本文と突き合わせた。引用した部分は両版で同じで、違うのは直前の句読点（1802年版は Indians のあとがコロン、1853年版はセミコロン）と、1802年版の長いs（ſ）の字形だけ。ここでは1853年版の綴りを採った。1787年のロンドン版（John Stockdale）も、Internet Archive のスキャン（notesonstateofvi1787jeff）の OCR 本文161〜162頁で同じ文があることを確かめた（長いsと OCR の読み誤りを除いて同文。Indians のあとは1802年版と同じくコロン）。1785年の私家版の本文には当たっていない。ジェファソンは1743〜1826年の人", "note": "「三十年ほど前、この塚のある一帯を通りかかった一行が、道を教わることも尋ねることもなく、森を抜けてまっすぐ塚へ向かい、しばらくそのまわりにとどまった。その様子は悲しみの表れと受けとられた。それから一行は、この訪れのために六マイル（およそ10km）ほど外れてきた街道へ戻り、旅を続けた」（この作品の訳）。一行とは先住民の一団で、原文はこの文の頭で、こうした塚が先住民のあいだでよく知られている、と書く。この段の前で、ジェファソンは自宅近くのリヴァンナ川の低地にあったこの塚を掘り返し、縦に切り開いて、骨と土が幾層にも重なっているのを数えている。本人は一人称で書くが、掘りの大きさからほかの人の手も加わっていたとみられ、それはおそらくモンティチェロの農園で奴隷にされていた人びとだった、と推測されている。層を見て掘った早い例としてよく引かれる記述だが、掘られたのは人の墓だった。⚠️ 「悲しみの表れと受けとられた」は、見ていた側の受けとり方である（三十年ほど前の出来事で、誰が見て、誰がそう受けとったのかは書かれていない）。一行が何をしていたのかを、本人たちの言葉で伝えるものではない。塚のあった一帯はモナカンの人びとの土地で、築いたのはモナカンかその祖先かもしれないとされるが、考古学者のあいだには異論もある。塚はその後しだいに低くなり、いまは正確な場所も分からないとされる。2000年には、塚があったと考えられる場所と結びつく村の跡の近くで開発の話が持ち上がったのを受けて、モナカン・インディアン・ネーションが祈りの儀式を行っている。"}, {"t": "art", "f": "tsuka_a5.jpg", "date": "1848年（測量は1846年）", "place": "アメリカ（オハイオ州アダムズ郡）", "title": "「大蛇」の測量図（“The Serpent,” Adams County, Ohio）──『ミシシッピ川流域の古代の記念物』図版XXXV", "artist": "エフライム・G・スクワイア（1821〜1888）／エドウィン・H・デーヴィス（1811〜1888）（測量と作図。石版はサロニー＆メジャー）", "museum": "Wikimedia Commons（アメリカ議会図書館のスキャン）", "lic": "パブリックドメイン", "url": "https://commons.wikimedia.org/wiki/File:SD35_Serpent_Mound_Squier_and_Davis_Plate_XXXV.png", "note": "石版の測量図。右上に「“THE SERPENT,”」「ADAMS COUNTY OHIO.」「E. G. Squier & E. H. Davis Surveyor 1846」。左の川（BRUSH CREEK）に沿って台地が弓なりに張り出し、その上を一本の土の高まりがいくつもうねりながら伸びて、下の端でくるくると渦を巻く。上の端、崖（Precipice）のきわには楕円の囲いがあり、その真ん中に小さな点がある。上の丘には「Indian Graves」の書き込みと印、下には「Mound 10 ft. high」。下の余白には、台地の断面（崖・急斜面・土手）と、土手を横切る断面の二つが添えられている。左下に「E. G. Squier, del. 1846」、枠の外に「Face P. 96.」「Lith. by Sarony & Major.」。この本は1848年に、スミソニアン協会の最初の出版物として出た。蛇の形の塚は長さおよそ400m、高さ1mほどとされ、中から埋葬は見つかっていない——墓ではない塚である。いつ誰が築いたのかは定まっておらず、1991年の放射性炭素年代ではおよそ900年前、2014年の年代では前300年ごろと出ている。⚠️ 楕円を、蛇がくわえた卵と見る説明は広く行われている。そのもとはこの本そのもので、本文は、蛇が口を大きく開いて楕円を「呑みこむか、吐き出すかしているよう」だと書き、楕円を「卵の形の図形」と呼んでいる（どちらもこの作品の訳）。ただし図のどこにも、卵とは書かれていない。また、この本は、塚を築いたのは「いまの先住民とは別の民族」だとする当時広く信じられていた見方に立っていた、と説明される。"}, {"t": "photo", "f": "tsuka_p1.jpg", "date": "いま（2008年）", "place": "千葉県千葉市", "title": "加曽利貝塚 北貝塚の貝層断面（写真）", "author": "Namazu-tron", "lic": "CC BY-SA 3.0", "url": "https://commons.wikimedia.org/wiki/File:Kasori_midden_preserve_north.jpg", "note": "撮影者の説明は「加曽利貝塚の小さな丘を切った土層（貝層）の展示」、撮影は2008年10月13日。観覧施設の中で、切り出された断面が壁一面に見えている。いちばん上に黒っぽい土の帯（札は「表土層」）、その下に細かい貝殻がぎっしり詰まった厚い層（「イボキサゴ純貝層」）、さらに下に白っぽい殻が帯になって寄った層（「ハマグリ純貝層」）があり、右寄りには「マテガイ」「ツメタガイ」「マガキ」の札が立つ。いちばん下は茶色い土で、札は「旧表土」——貝が捨てられはじめる前の地面である。白い札は現地の展示のもので、黄色い番号(1)〜(7)は撮影者が書き足したもの。北貝塚は直径およそ140mの環の形をした縄文時代中期の貝塚で、長径およそ190mの南貝塚（後期）と合わせて日本最大級とされ、2017年に貝塚として初めて国の特別史跡になった。貝殻のカルシウムが酸性の土を中和するので、ふつうの遺跡では分解されてしまう骨などが、ここではよく残る。⚠️ 写真のどの深さが何年前にあたるかは、この一枚からは決められない。"}]}, {"id": "tsutsumi", "no": "第十八景", "kind": "tsuchi", "name": "堤", "yomi": "つつみ", "en": "Tsutsumi — the embankment: earth heaped up and packed down to hold back water", "rep": "tsutsumi_a3.jpg", "lead": "土を盛って、水を押しとどめる。堤は土木のいちばん古い仕事のひとつで、いまも日本の川の堤防は、国の基準で、土を盛ってつくる堤（土堤）が原則とされている。土は安く、手に入りやすく、傷んでも盛り直し、高くし直せるからだ。そして盛った土は、切れる。だから堤は、築くことと見まもることが、ひと続きの仕事になる。", "layers": [["土で水を止めるしくみ", "土の粒と粒のあいだには隙間があり、水はそこを伝って進む。粒の細かい粘土は隙間も細かく、水をほとんど通さない。地盤工学会の整理では、粘性土の透水係数はおよそ10⁻¹¹〜10⁻⁹ m/s、砂や礫はおよそ10⁻⁵〜10⁻² m/s とされ、水の通しやすさには少なくとも一万倍の開きがある。盛った土は、薄く撒いては突き固める（締め固め）。隙間が減って水を通しにくくなり、流れにも削られにくくなる——国の研究所がまとめた、水が堤を越えるときの実験では、よく締め固めた堤の土は、締め固めの足りない土より削られる速さが数倍以上小さく、湿り気の多い堤は、少ない堤より数倍速く削られた。形は下が広く上が狭い台形で、日本の基準では斜面（法面・のりめん）の傾きを、高さ1に対して水平2より緩くし（2割）、3割より緩くするのが望ましいとされる。それでも堤は壊れる。国の資料は、その壊れ方を浸透・越水・侵食・地震に分けて整理している。越流（越水）では、水が上を越え、町の側の斜面を多くは足もと（法尻）から削っていく。浸透には二つある。長い雨や高い水位で水が堤の中へしみ込み、土の強さが落ちて斜面ごと滑るすべりと、多くは堤の下の地盤を水が抜けて、町の側の足もとに砂を噴き上げ、土の粒を運び出しながら水の道を広げていくパイピングである。侵食では、川の側の斜面や、その足もとの川底が速い流れに削られ、そこから崩れていく。地震の揺れで壊れることもある。2019年の東日本台風では全国で142か所の堤防が決壊し、その86％は越水が主な原因だった。⚠️ 目の前の堤がどこまで持つかを判断するのは、この景の役目ではない。住んでいる自治体の出す情報と、気象庁の発表に従ってほしい。"], ["嵩上げの二千年", "前漢の終わり（前1世紀末）、賈讓（かじょう）は皇帝に治水の策を上奏し、堤防はそう古いものではなく、戦国時代に国々がそれぞれの利のために川を塞いだのが始まりだと書いた（『漢書』溝洫志）。数年前の大水では水が堤の上まであと二尺に迫り、堤の上から北を望むと、河は民の家より高かったという。彼自身も堤の上を歩いて水を見てまわり、ある所では水面が地面より五尺ほど高かったと記す。泥の多い川を堤で閉じこめると、泥は川底にたまり、川は周りの土地より高くなる。堤を上げれば、また川底が上がる。ネーデルラントでは13世紀に、堤を共同で築き、守るための水の組織（waterschap）が生まれ、いまも、住民の選挙で選ばれた議員と、農地や自然地の持ち主・事業者の代表とで組む理事会が治めている。その連合会は、砂丘と水を防ぐ構造物がなければ国の半分以上が水に沈む、と書く。日本の国の基準の解説も、堤防は「洪水による被害を経験するたびに嵩上げ及び拡幅等を繰り返して築造されてきた」と言う。堤は一度には完成しない。切れた高さの記憶を、上へ上へと積んでいく。"], ["わざと切れ目を残す", "堤は高く、長く、切れ目なく——というのが直観だが、逆の考え方も各地で生まれている。急な川の治水として合理的とされる霞堤（かすみてい）は、堤をわざと途中で切り、上流側と下流側の堤を二重に重ねた不連続な堤である。洪水のときは開口部から水が逆流して堤の内側にたまり、下流へ流れる量を減らす。洪水が過ぎれば、たまった水を抜く。戦国時代の武田信玄が考えたと言われる。賈讓も、水の当たる土地の民を移し、堤を切って河を北の海へ放つ策を「上策」とし、古い堤を繕って低い所を上げ、薄い所を厚くしつづけるのを「最下策」と呼んで、どうして水とわずかな土地を争うのか、と書いた。オランダはおよそ30か所で、堤を内陸へ引き下げ、河川敷を掘り下げ、放水路を設けて、川に場所を返してきた（Ruimte voor de Rivier＝川に場所を、2006年に計画決定）。バングラデシュ南西部では1960年代に海岸の土地が堤で囲まれ、潮が締め出された。泥は内側に積もらずに外の川底にたまり、水は抜けなくなった。1990年9月、ダカティアの低地では住民が集まって、自ら堤を四か所で切った。潮を一時的に内側へ戻すこのやり方は、のちに潮汐河川管理（TRM）と呼ばれるようになる。上げ潮が泥を低地に置いていき、引き潮の澄んだ水が川底を掘る。堤は水を止めるが、水が運んでくる土も止めてしまう。"]], "invite": "晴れた日に、近くの川の堤防の上の道（天端・てんば）に上がって、川の側と町の側を見くらべてみる。町の側の家の一階や田畑が足もとより低ければ、その差が、この堤が町の側に対して持っている高さである。どちらの斜面がゆるいか、草がどう生えているかも見ておく。（歩いてよい道かどうかは、現地の表示に従う。車や自転車の通る天端もある。）⚠️ 雨が続いているとき、川が増水しているときは、堤に近づかない。川の近くの危険については、住んでいる自治体の出す情報と、気象庁の発表に従ってほしい。", "works": [{"t": "bun", "date": "前1世紀（前26年ごろ劉向が編んだとされる。篇の成立は戦国〜前漢で諸説）", "place": "中国", "title": "『管子』度地篇（第五十七）", "author": "作者不詳（管仲の名に託された書）", "quote": "土乃益剛，令甲士作堤大水之旁，大其下，小其上，隨水而行。……歲埤增之，樹以荆棘，以固其地，雜之以柏楊，以備決水。", "src": "中国語版ウィキソース『管子/第57篇度地』（句読点つきの本文）で引用し、同じくウィキソースにある二つの版と突き合わせた。①『管子（四部叢刊本）』巻第十八 ── 常熟瞿氏鐵琴銅劍樓蔵の宋刊本を影印したもの。ウィキソースの翻字は機械読み取りのままの未校正だったので、ウィキメディア・コモンズの影印（Sibu Congkan0346-房玄齡-管子-4-3.djvu の117頁）を開いて一字ずつ見た。②『管子（四庫全書本）』巻十八。三つの違いは字体だけで、四庫全書本は「堤」を「隄」、「歲」を「嵗」、「雜」を「襍」、「柏」を「栢」と書き、宋刊本も「柏」を「栢」と書き、「歲」を「歳」の形に作る。文意は変わらない。「……」は「地有不生草者，必爲之囊。大者爲之堤，小者爲之防，夾水四道，禾稼不傷。」を省いたしるし。『管子』は前7世紀の管仲の名に託された書で、多くの書き手の文章を含み、前26年ごろ前漢の劉向が86篇に編んだとされる（いま残るのは76篇）", "note": "大意「（春分を過ぎて昼が長くなるころ、）土はいっそう固くなる。兵に命じて、大きな川のほとりに堤をつくらせる。下を大きく、上を小さくし、水の流れに沿わせる。……年ごとに少しずつ盛り足し、茨を植えて地を固め、柏と楊をまじえて植えて、決壊に備える」。柏は中国ではヒノキ科の木を、楊はヤナギ科の木を指す。桓公と管仲の問答の形をとる一篇で、管仲は国を損なう五つの害——水・旱・風霧雹霜・疫病・虫——のうち「水、最も大なり」と言い、水の役人を置いて、冬の暇なうちに、もっこ・鋤・板築の道具をそろえておけ、と説く。下が広く上が狭い台形、年ごとの嵩上げ、植え込みで土を固めること。いまの堤の基本が、ここにひととおり並んでいる。いつ築くかにも一節を割き、夏は農事の季節で土の仕事に向かず、秋は湿りが日に日に増して「土弱く成り難し」、冬は「土剛くして立たず」、だから春がよいという。⚠️ 湿り気の多い堤の土が削られやすいことは、いまの実験でも確かめられているが、この書き手がそれを測ったわけではない。響きあって見えるのは、こちら側の読みである。"}, {"t": "bun", "date": "1479年（記事は1248年）", "place": "ベトナム（大越・陳朝）", "title": "『大越史記全書』本紀全書巻之五・陳紀 太宗 戊申十七年（1248年）三月の条", "author": "呉士連（ゴ・シ・リエン）ほか", "quote": "令諸路築堤防水，名曰鼎耳，自源頭至海岸，以遏洪水漲溢。置河堤正副使管督之。所築之處，視民田地，度其所築，依價還錢。", "src": "国立国会図書館デジタルコレクション『大越史記全書』3・4 本紀全書（引田利章校点、明治18年＝1885年刊、info:ndljp/pid/776355、パブリックドメイン）のコマ106の影印を開いて一字ずつ読み、中国語版ウィキソース『大越史記全書/本紀卷之五』の本文と突き合わせた。引用の範囲で違うのは一字だけで、ウィキソースは「自原頭至海岸」、1885年版の影印は「自源頭至海岸」と書く。影印の側を採った。引用の外でも、ウィキソースの「遣風水者適觀」を影印は「遍觀」と作っていて、二つが別々に起こされた本文であることが分かる。句読点はウィキソースに従った。『大越史記全書』は黎朝の官撰の編年体の史書で、呉士連が1479年に15巻にまとめ、のちに范公著（1665年）・黎僖（1697年）が書き継いだとされる。同じ年の条の終わりには「史臣呉士連曰く」で始まる論評が置かれているが、それは風水師に国中の山川の王気を厭わせた件（同じ年の後の条）に向けたもので、堤の条への論評ではない", "note": "大意「諸路に命じて堤を築かせ、水を防がせた。名づけて鼎耳（鼎の耳）という。源から海岸まで続き、洪水のあふれを遏めるためである。河堤の正使・副使を置いて、これを管理・監督させた。堤を築いた所では、民の田地を調べ、築くのに取った分を測って、値に応じて銭を返した」。条はこのあと「鼎耳の築くこと、此れより始まる」と結ぶ。陳朝の1248年のことで、同じ書の百四十年前、李朝の1108年の条にも「堤を機舎坊に築く」とある（こちらも1885年版の影印とウィキソースの両方で確かめた）。堤は誰かの田の上に立つ。この条がいちばん具体的に書いているのは、土の盛り方ではなく、田を取られた人への払い方である。⚠️ 鼎耳の堤を、いまの紅河の堤防の始まりとする説明は多いが、この条そのものは川の名を書いていない。"}, {"t": "art", "f": "tsutsumi_a1.jpg", "date": "1624年", "place": "ネーデルラント", "title": "1624年1月10日の大洪水（またはヴィアネン近くのレク川の切れた堤の修復）（The Great Flood of January 10, 1624 (or Repairing the Broken Dike on the River Lek by Vianen, 1624)）", "artist": "エサイアス・ファン・デ・フェルデ", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1982.171", "note": "エッチング。館は題を二つ並べて記す——「1624年1月10日の大洪水」と「ヴィアネン近くのレク川の切れた堤の修復」。画面に見えるのは、水そのものではなく後始末の仕事である。手前から中ほどにかけて、何人もの男が、葉を落とした枝を束ねたもの（粗朶・そだ）を肩にかつぎ、あるいは地面に並べて束ねている。左手には細い枝を編んだ垣が長く続き、中ほどの一段高い土手の上には、人が一列に並んで身をかがめている。舟が何艘も岸に上げられ、右手には板張りの小屋。木はみな葉を落としていて、題の一月と食い違わない。画面には A から F までの文字が振られているが、何を指すかの凡例はこの一枚には刷られていない。左下に「Esijas vande Velde feset.」、右下に「Broer Jansen excu.」（excudit＝刷って出した、の略）と入る。館は解説を付けていない。⚠️ 束ねた枝を修復のどこにどう使うのかは、この一枚からは決められない。この景の乾隆帝の絵巻に、館が「堤の切れ目をふさぐための高粱の束」と書くものがあり、束ねて使うという点だけは同じである。"}, {"t": "art", "f": "tsutsumi_a2.jpg", "date": "1650年ごろ", "place": "ネーデルラント（画題はアムステルダムの東）", "title": "ディーメルダイクの眺め、牛乳売りと農家（View of the Diemerdijk with a Milkman and Cottages ('Het Melkboertje')）", "artist": "レンブラント・ファン・レイン", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/391944", "note": "エッチングとドライポイント（三つある状態のうちの第三）。紙は6.7×17.6cm、手のひらに載る大きさである。右手に一段高い道がまっすぐ延び、その上を、天秤棒で桶を二つ下げた男が犬を連れて歩いていく——題の「牛乳売り（Het Melkboertje）」である。道の向こうには水面がひろがり、帆船が幾艘も浮かぶ。道の左の低いところには藁葺きの農家と木立、水路と小舟。水のある側と人の住む側のあいだを、一本の高い道が仕切っている。館のいまの題は、この道を Diemerdijk（ディーメルダイク）の眺めと呼ぶ。ただ、2014年にインターネット・アーカイブへ写された館の記載では、題は「Landscape with a Milkman」だった。堤の名は、あとから題に入った。Diemerdijk は、アムステルダムの東で IJ の岸に沿って延びる堤を指すとされる。左の奥には山並みのような線が薄く引かれているが、この低地にそういう山は無く、何を描いたものかはこの一枚からは決められない。⚠️ 版画は刷ると版の左右が反転するので、画面の左右をそのまま土地の方角に当てることはできない。"}, {"t": "art", "f": "tsutsumi_a3.jpg", "date": "1651年以後（館の記載は「17世紀」）", "place": "ネーデルラント（画題はアムステルダム郊外）", "title": "聖アントニウス堤の決壊、1651年3月5日（The Bursting of St. Anthony's Dike, 5 March 1651. Vertoninge...Amsterdam）", "artist": "ピーテル・ノルペ", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/371401", "note": "銅版画、33.7×50.8cm。画面の真ん中で、堤が切れている。切れ目から水が白く泡立ちながら手前へ落ち、その勢いは滝そのものに見える——館がこの版画に付けた分類の語も「Waterfalls（滝）」である。切れ残った堤の上を、人びとが帽子と外套を風にあおられながら左へ走り、犬も駆ける。右上の崩れかけた縁では、ひとりの男が身を乗り出して下の人の手をつかみ、引き上げている。その後ろに白い馬。奥には教会の塔が幾本も立ち、左手に家並みがある。下の余白に「VERTONINGE ENDE NAE T'LEVEN AFGEBEELT, HET DOOR BREECKEN VANDE S.T ANTHONIS DYCK BUYTEN AMSTERDAM」（アムステルダム郊外、聖アントニウス堤の決壊を、実物を見て描いて示す）と刷ってある。この一枚では、その下に何も刷られておらず、日付は館の題にあるだけである。ところがアムステルダム国立美術館にある同じ図柄の刷り（RP-P-OB-102.713）では、題の行の下に文が三行続き、「1651年3月5日」の日付と、A〜C の凡例（A 二つの切れ目のあいだの堤に立つ人びと、B 堤から切れ落ちた一片、C ハウテワール）が刷られ、右下には、ノルペがアムステルダムで作って刷り、W・スヘリンクスが描いた、という旨の一文がある。この一枚でも、左手の家の屋根に C、左端の茂みのそばに B の文字が見える。メトロポリタンの一枚が、その文の手前で紙が切られたものなのか、文を彫り足す前の刷りなのかは、この一枚からは決められない。1651年3月4〜5日の高潮（聖ペテロの洪水）では、IJ の南岸に沿うこの堤がアムステルダムのすぐ東で切れたとされる。館はノルペの生没年を1613/14〜1652/53年と記すので、版は出来事からせいぜい二年ほどのうちのものになる（アムステルダム国立美術館も1651〜1653年とする）。⚠️「実物を見て描いた」は版の側の言い分で、確かめる手立ては無い。しかも下絵を描いたのはスヘリンクスだと、同じ版の別の刷りの文字が言っている。"}, {"t": "art", "f": "tsutsumi_a4.jpg", "date": "1770年", "place": "中国（清）", "title": "乾隆帝南巡図 第四巻「黄淮交流」（The Qianlong Emperor's Southern Inspection Tour, Scroll Four: The Confluence of the Huai and Yellow Rivers）", "artist": "徐揚と工房", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/49251", "note": "絹に墨と色の絵巻で、縦68.8cm、長さはおよそ11m（1096.2cm）。乾隆帝が1751年にはじめて南方を巡ったときの記録として描かせた十二巻のうちの第四巻である。館によれば、この巻は黄河沿いの治水の施設を見てまわる皇帝を描き、皇帝は、澄んだ淮河の水を泥の多い黄河へ導いて泥を薄め、海へ押し流すための放水口のそばに立つ。巻の残りには、洪水を防ぐさまざまな技——大運河へ入る水の勢いを弱める二重の水門、突き固めた土の堤と石で表を張った堤、そして堤の切れ目をふさぐための大きな高粱（コーリャン）の束——が描かれている、という。ここに載せたのは巻の一部分だけである。茶色に波立つ水の右手を、まっすぐな土手が一本、画面の奥から手前へ斜めに走り、平らな天端の上を小さな人の列が歩き、見張り台のような櫓と小屋が建つ。土手の川の側の斜面は急で細かな筋が入り、陸の側はゆるやかに下って木立と家々に続く。手前の岸には舟が寄り、陸に人が立つ。⚠️ この部分に写る土手が、館のいう「突き固めた土の堤」なのか「石張りの堤」なのかは、画面からは決められない。館は徐揚を、蘇州で乾隆帝に見いだされて宮廷の画院に入った画家とし、全体をひとつの視点でまとめた「西洋風」の画面に、カスティリオーネらイエズス会士の画家の影響を見る。"}, {"t": "art", "f": "tsutsumi_a5.jpg", "date": "1857年", "place": "日本（江戸）", "title": "名所江戸百景「よし原日本堤」（“Nihon Embankment at Yoshiwara,” from the series One Hundred Famous Views of Edo）", "artist": "歌川広重", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/56931", "note": "木版画、36.2×24.1cm。暮れていく空に細い月が出て、鳥が長い列をつくって渡っていく。その下を、堤が画面の左下から右上へ斜めに横切っている。堤の上は道で、葭簀（よしず）で囲った掛け茶屋が道の両側に並び、駕籠をかつぐ人、歩いていく人が行き交う。堤の斜面には草がまばらに生え、左手の低いところには青い水面と木立、青い屋根の建物がのぞく。上の余白には丸い印が二つ（「改」と、「巳」「四」と読めるもの）、左下の余白には版元の印（「下谷」「魚栄」と読める。左の行は紙の端にかかって一部が切れている）。館は解説を付けていない。国立国会図書館の電子展示によれば、日本堤は隅田川の出水の害を防ぐために幕府が築いた堤で、明暦の大火（1657年）のあと、吉原遊郭が堤の半ばの南側へ移ってからは、吉原へ通う道になった。水を防ぐために盛った土の上が、そのまま人の通う道になっている。"}, {"t": "photo", "f": "tsutsumi_p1.jpg", "date": "いま（2013年）", "place": "バングラデシュ", "title": "バングラデシュの堤（写真）", "author": "Helena Wright", "lic": "CC BY 2.0", "url": "https://commons.wikimedia.org/wiki/File:Embankments_in_Bangladesh_(15258695952).jpg", "note": "撮影者の題は「Embankments in Bangladesh」、撮影は2013年3月1日。どこの堤かは書かれていない。土手の水の側の斜面を、四角いコンクリートのブロックが間をあけて互い違いに並んで覆い、そのまま水ぎわまで降りている。ブロックの上を男がひとり歩き、左手の天端には乾いた藁が散り、その奥に、束ねた竹のようなものが置かれている。水には木造の舟が何艘も寄せられ、一艘には網が積まれ、水の中からは木が何本も立っている。斜面をブロックで覆うのは、流れや波が土を直接削らないようにするためである（法面の保護）。バングラデシュの海岸には、四方を堤で囲んだ土地——オランダ語でポルダー——が139あり、外側の川に土砂がたまることや手入れの不足が、堤の働きをおびやかしている、と世界銀行の評価報告は書く。⚠️ この一枚の堤が、ポルダーを囲む堤なのか、川岸の護岸なのかは、写真からは決められない。"}]}, {"id": "ido", "no": "第十九景", "kind": "tsuchi", "name": "井戸", "yomi": "いど", "en": "Ido — the well: digging down through the earth until it gives up the water held inside it", "rep": "ido_a3.jpg", "lead": "井戸は、土を掘って、土の中にたまっている水に届かせる穴である。地面の下では、ある深さから先の土や砂や礫のすき間が水で満たされていて、井戸の水面はおおむねその高さにそろう。井戸は、見えない水の層を、上から指さしている。", "layers": [["すき間を満たす水", "地面を掘り下げていくと、はじめのうち土の粒のすき間には空気と水がまじっている（不飽和帯）。ある深さを越えると、すき間がすっかり水で満たされる（飽和帯）。その境の面が地下水面で、ふつうの井戸の水面はおおむねこの高さにそろう。水をよく通してたくわえる砂や礫の層を帯水層、粘土のように水を通しにくい層を難透水層（ほとんど通さないものを不透水層）と呼び、地下では帯水層がいくつも重なって、あいだを難透水層が仕切っていることが多い。いちばん上の不透水層より上の水（不圧地下水）を汲むのが浅井戸、その下の、上から押さえられた水（被圧地下水）まで届くのが深井戸である。深さの目安は20〜30メートルとされるが、学問上の決まった線はなく、帯水層の深さは土地ごとに違う。被圧地下水は、掘り当てると井戸の中を自分で上がってきて、地表より高くなれば噴き出す（自噴井）。地球の淡水のうち、およそ三割が地下にあるとされる（七割近くは氷河と氷）。⚠️ 地下の水が「脈」のような細い筋を流れている、という見方は古くからある（下のヴァラーハミヒラ）。けれども多くの場合、水は筋ではなく、砂や礫のすき間を満たした層として広がっている。岩の割れ目や石灰岩の洞を流れる場合もある。"], ["下へ、段で、横へ", "人の入れる太さの穴を手で掘り下げ、崩れないよう内側を石や煉瓦で組みながら地下水面まで届かせるのが掘井戸である。地下水面が深い土地では、掘り方そのものが形を変えた。西インドのグジャラートやラージャスターンの階段井戸（ヴァーヴ／バーオリー）は、地面に長い溝を掘り下げ、石の階段と柱廊で水の高さまで人が降りられるようにしたもので、6〜7世紀には造られていたとされる。雨季と乾季で上下する水の高さに合わせて、人のほうが段を上り下りする。パータンのラーニー・キ・ヴァーヴ（11世紀）は七層、深さおよそ28メートルとされ、2014年に世界遺産になった。イランのカナートは、まず山すその扇状地に試しの竪穴を掘って、地下水面の深さを確かめる。それから、水を出したい低い側から試しの竪穴へ向かって、数十メートルおきに竪坑をあけながら、ゆるく上る横穴を掘り進める。できあがった横穴は水源から出口へゆるく下り、水を重力だけで地表へ導く。イランのカナートの多くは長さ5キロメートルに満たないが、70キロメートルほどのものもあるとされる。横穴を掘った土は竪坑で運び上げられ、口のまわりに積まれる。2016年、十一のカナートが「ペルシアのカナート」として世界遺産になった。日本では明治のはじめに上総（いまの千葉県中西部）で、細く割った竹のひごで鉄管を吊り、竹の弾みと人の力で突き下ろして掘り抜く上総掘りが生まれ、1887年ごろに方法が定まったとされる。一日に掘り進めるのは5〜6メートルほどで、少ない道具と人手で、深い帯水層の水まで届いた。"], ["井戸のまわり", "水の出る穴には、持ち主と、名前と、争いがついてまわる。『創世記』では、父の代に掘った井戸が土で埋められ、息子がそれを掘り直して父のつけた名で呼び、新しく掘った井戸は、羊飼いどうしの争いのたびに名を変えていく。村や町の井戸は、水場であると同時に、人が毎日同じころに顔を合わせる場所でもあった。十八世紀の朝鮮の金弘道は井戸端の一瞬を描き、十九世紀のグジャラートの写真では、女たちが頭に壺を重ねて階段井戸の段に立っている。サハラの南の縁のアガデスでは、井戸の上に木の枠を組み、長い綱で革袋を引き上げていた。日本語の「井戸端会議」も、そういう場所から来たことばである。井戸は、土の中の見えない水を、地上の人の集まりに変える穴でもある。"]], "invite": "町を歩いて、名前のついた井戸や湧き水の跡（「〇〇の井」「〇〇清水」などの案内板）を探し、見つけたら、その場所が台地の上か、坂の下か、川のそばかを地図で確かめてみる。水の出やすい場所は、土地の高さと結びついている。（⚠️ 古井戸や穴、ふたをした井戸には、のぞき込まず、上に乗らず、近づかない。ポンプや井戸には触れず、見るだけにする。私有地には、許しなく入らない。その水は飲まない——飲めるかどうかは、この景では判断しない。）", "works": [{"t": "bun", "date": "前6〜前5世紀ごろ（現在の形にまとまった時期とされる）", "place": "レヴァント", "title": "『創世記』26章15節（ヘブライ語聖書）", "author": "作者不詳（ヘブライ語聖書）", "quote": "וְכׇל הַבְּאֵרֹת אֲשֶׁר חָפְרוּ עַבְדֵי אָבִיו בִּימֵי אַבְרָהָם אָבִיו סִתְּמוּם פְּלִשְׁתִּים וַיְמַלְאוּם עָפָר", "src": "ヘブライ語版ウィキソース「בראשית כו/ניקוד」（母音符号つきの本文）第15節で照合 <https://he.wikisource.org/wiki/בראשית_כו/ניקוד>。英訳は、英語版ウィキソース所収の欽定訳（King James Version・1611年刊・著作権満了）「Bible (King James)/Genesis」26:15 と、Project Gutenberg の欽定訳（#10）の同節で突き合わせ、両者が一字も違わないことを確かめた（Gutenberg は ’ の字形だけが違う）。18〜22節（掘り直し・生きた水・エセク・シトナ・レホボト）も同じ二つで確かめた。日本語の訳はこの作品の訳", "note": "「彼の父のしもべたちが、父アブラハムの時代に掘った井戸は、みなペリシテ人がふさぎ、土（עָפָר アファル）で満たしてしまった」。イサクが住んだゲラルの地の話である。続く節で、イサクはその井戸を掘り直し、父がつけたのと同じ名で呼ぶ（18節）。谷で新しく掘ると「生きた水（מַיִם חַיִּים）」の井戸に当たるが、土地の羊飼いと争いになり、その井戸を「争い（エセク）」と名づける。次の井戸も争いになって「敵意（シトナ）」、三つめでようやく争いがやみ、「広い場所（レホボト）」と呼ぶ（19〜22節）。欽定訳は「生きた水」を springing water（湧き出る水）と訳している。水の出る穴が、土を詰めればふさがるもの、掘り直せば戻るもの、名で呼ばれて奪い合われるものとして書かれている。⚠️ 物語の出来事が史実かどうかは、この一節からは決められない。"}, {"t": "bun", "date": "6世紀", "place": "インド", "title": "『ブリハット・サンヒター』第54章「ダカールガラ（地下の水を知る術）」第1詩節の後半", "author": "ヴァラーハミヒラ", "quote": "puṃsāṃ yathāṅgeṣu śirās tathaiva kṣitāv api pronnatanimnasaṃsthāḥ", "src": "筆頭の典拠＝保護期間の満了したスキャン本。ケルン校訂本（H. Kern ed., The Bṛhat Sañhitá of Varáha-Mihira, Bibliotheca Indica, Calcutta 1865）第54章 p.280 の頁画像を Internet Archive（bhatsahitavarha00kerngoog）で開き、デーヴァナーガリーを一字ずつ照合した。突き合わせに使った電子テキスト＝GRETIL「Varāhamihira: Bṛhatsaṃhitā」（Tripathi 校訂本に拠る。ファイルは CC BY-NC-SA 4.0）の 53.01cd。引用の部分は両者で一字も違わない。異同は章の名の一語で、ケルン本は dagārgalaṃ、GRETIL（Tripathi 本）は dakārgalaṃ（GRETIL 自身が「K.dagārgalaṃ」と注記）。章の番号もケルン本54・Tripathi 本53とずれる。英訳はチダンバラム・アイヤル訳（1884年刊・ウェルカム図書館蔵本のスキャン）第7章（54）「On Under-currents」pp.43–44 で意味を確かめた。日本語の訳はこの作品の訳。ヴァラーハミヒラは6世紀の人（587年没とされる）", "note": "「人のからだの肢体に脈（シラー）が通っているように、大地にも、高いところと低いところに脈がある」。6世紀の天文学者ヴァラーハミヒラが、百科の書『ブリハット・サンヒター』の一章を、井戸を掘るための地下の水の見つけ方にあてた、その冒頭の詩節の後半である。すぐあとの第2詩節は、「空から落ちる水は一つの色、一つの味だが、大地の違いによって、さまざまな味とさまざまな色になる。だから土に照らして調べよ」と続く。章の本文は、乾いた土地にどんな木があれば、その木からどちらへ何キュビット離れ、人の背丈いくつ分を掘れば脈に当たるかを並べ、掘り進めると途中で何が出るか——白っぽい蛙、黄色い土、石——まで書く（英訳者アイヤルの注によれば、章の中に百を超える木の名が出る）。⚠️ ここに書かれた木と脈の対応が当たるかどうかを確かめた記録を、この景は持っていない。見立てとして読むこと。地下の水を細い「脈」と見る考え方も、いまの見方（水の多くは砂や礫のすき間を満たした層として広がる）とは違う。いっぽう、地面を通ってきた水が土や岩の成分を溶かしこみ、通ってきた地層によって違う水になることは、いまの地下水の説明にも書かれている。"}, {"t": "art", "f": "ido_a1.jpg", "date": "16世紀第2四半期", "place": "インド", "title": "兎と獅子と井戸（The Hare, the Lion, and the Well）・『カリーラとディムナ』の一葉", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/453088", "note": "紙にインクと不透明水彩。『カリーラとディムナ』は、インドの『パンチャタントラ』にさかのぼるとされる動物寓話集で、館はこの一葉を写本の一葉とし、制作地をインド、時期を16世紀第2四半期とする（館の分類語には「井戸」「獅子」「兎」がある）。兎が獅子を井戸へ連れていき、水に映った獅子自身の姿を「もう一頭の獅子」と思わせて飛び込ませる、という話とされる。画面では、上の縁に獅子が立って下をのぞき、右の縁には兎がすわる。その下は、赤茶の土の壁に左右と上を囲まれた青い水で、水の中に兎と獅子の姿がもう一組いる——映った姿である。井戸は地面を縦に切った断面として描かれ、土の壁のむこうにたまった水が、横から見えている。上の欄外の一行は、アラビア語で「これは兎と獅子の絵で、（獅子は）水をのぞき込み……」と読めるところまでで、後半は当方には確かに読み切れない。獅子の足もとの赤い書き込み（اصلان طوشان）はトルコ系のことばで獅子と兎を指す語に見えるが、誰がいつ書き入れたのかは館の記載にない。"}, {"t": "art", "f": "ido_a2.jpg", "date": "18世紀後半（画家の40代ごろの作と推定される）", "place": "朝鮮（朝鮮王朝）", "title": "井戸端（우물가／井邊）・『檀園風俗図帖』より", "artist": "金弘道（キム・ホンド／号は檀園）", "museum": "Wikimedia Commons（原本は韓国・国立中央博物館蔵、本館6504-11）", "lic": "パブリックドメイン", "url": "https://commons.wikimedia.org/wiki/File:Danwon_Umulga.jpg", "note": "館の記載は、紙、縦28.1cm・横23.9cm、題は「井邊（井戸端）」。十八世紀の朝鮮の画家・金弘道の風俗画帖（25図）の一枚である。左下に、石を輪に組んだ丸い井戸の縁がある。縁の左では女が身をかがめて綱をたぐり、縁の上には箍をかけた木の桶が置かれている。井戸の内側にも短い筆の線が並び、石の積み目が下へ続いているように見える。まんなかでは、上着の前をはだけた男が器を口にあてて水を飲み、左手に黒い笠をさげている。そのそばで、もう一人の女が綱を手にして立つ。右上では、三人めの女が頭に器をのせ、手に綱の束を持って立っている。右下に印がある。館の説明は、胸をはだけて水を飲む男と、恥じらって顔をそむけたり、よそを見たりする女たち、と読み、朝鮮時代の男女の別の風俗を示す、とする。井戸の深さも、水面も、画面には描かれていない——描かれているのは、縁のまわりに人が寄ってくる、その一瞬である。"}, {"t": "art", "f": "ido_a3.jpg", "date": "1874年", "place": "インド・グジャラート（アダラジ）", "title": "アダラジのヴァーヴ、すなわち井戸（Wav or Well at Adalaj）・『グジャラートとラージプターナの建築と風景の写真』第3図", "artist": "ボーン・アンド・シェパード（写真館）", "museum": "Wikimedia Commons（原本はフランス国立美術史研究所〔INHA〕図書館のデジタル版）", "lic": "パブリックドメイン", "url": "https://commons.wikimedia.org/wiki/File:Wav_or_well_at_Adalaj,_Ahmedabad.jpg", "note": "写真館ボーン・アンド・シェパードの写真に、考古学者ジェイムズ・バージェスが歴史と解説の文を付けた写真集の第3図（写真集の扉による）。台紙に「III. WAV OR WELL AT ADALAJ.」と刷られ、写真の右下には「Bourne & Shepherd 2243」と原板の番号が書き込まれている。左下に赤い蔵書印。上の階の踊り場から、柱の並ぶ回廊が段をなして奥へ奥へと下っていくのを見通した一枚で、踊り場から一段下がったところに、三人の女が頭に壺を二つずつ重ねて立ち、右の女のうしろには、もう一組の壺が流れるようにぶれて写っている（長い露光のあいだに動いた、もう一人か）。欄干の向こうでは、もう一つ下の階が暗がりへ口を開けている。ヴァーヴはグジャラート語で階段井戸のことで、写真集の題は、それを英語の well で言い直している。アダラジの階段井戸は、銘文によって15世紀の終わり（1498〜99年）に造られたとされ、ふつう五層の深さと説明される（バージェスの解説は、回廊を三つと数える）。そのバージェスの解説は、ヴァーヴを二つの部分からなる大きな井戸と書く——牛が革袋で水を引き上げる井戸と、女たちが水の高さまで降りて壺を満たす広い階段である。段が何層もあるのは、雨季と乾季で上下する水の高さまで人が降りていけるようにするため、と説明される。⚠️ 撮影の季節も、このとき水がどの高さにあったかも、写真からは決められない。"}, {"t": "art", "f": "ido_a4.jpg", "date": "1909年（刊行）", "place": "ニジェール（アガデス）", "title": "アガデスのティンシャマンの井戸（Le puits de Tinchamane, à Agadez）", "artist": "ルイ・ジャック・ポスト（撮影）", "museum": "Wikimedia Commons（R・シュドー『Missions au Sahara』第2巻・1909年 p.63 の図版）", "lic": "パブリックドメイン", "url": "https://commons.wikimedia.org/wiki/File:Posth-Le-puits-de-Tinchamane-a-Agadez.jpg", "note": "地質学者ルネ・シュドーの『サハラの調査行』第2巻「スーダンのサハラ」（パリ、1909年）に載った写真で、撮影はフランスの植民地の将校ルイ・ジャック・ポスト（1874〜1947）。説明文は「アガデスのティンシャマンの井戸。袖のついた革袋と二本の綱に注意」（Commons の記載による）。画面の中央に、股になった木を組んだ枠が立ち、上の横木に小さな輪（滑車か）、その下に黒く丸いものが下がる。枠の足もとは丸太で囲われ、左へ向かって綱が何本ものび、宙にぴんと張ったものと、地面を長く這うものとがある。右手には布をまとった人びとが立ち、手前には丸い器が置かれている。長い綱は、引き手が遠くまで歩いて引き上げることを思わせるが、井戸の深さも、誰が何で引くのかも、この一枚と説明文からは決められない。⚠️ 原本のスキャンには当たれず、説明文と頁は Commons の記載に拠った。"}, {"t": "art", "f": "ido_a5.jpg", "date": "1925年2月", "place": "イラン（カーシャーン近郊）", "title": "高度400メートルから見たカーシャーンの外側の地区（Aussenquartiere von Kaschan aus 400 m Höhe）・「ペルシア飛行 1924〜1925」より", "artist": "ヴァルター・ミッテルホルツァー", "museum": "ETH図書館（チューリヒ工科大学）画像アーカイブ（Wikimedia Commons 経由）", "lic": "パブリックドメイン", "url": "https://commons.wikimedia.org/wiki/File:ETH-BIB-Aussenquartiere_von_Kaschan_aus_400_m_H%C3%B6he-Persienflug_1924-1925-LBS_MH02-02-0133-AL-FL.tif", "note": "台紙に貼った紙焼き、12×17cm。スイスの飛行家ミッテルホルツァーの1924〜25年のペルシアへの飛行の写真で、館（ETH図書館）では249枚からなる「ペルシア飛行」のまとまりの一枚。写っているものについての館の記載は、題の「高度400メートルから見たカーシャーンの外側の地区」だけで、Commons も場所を「原題によればカーシャーン近郊。正確な位置は不明」とする。遠くに町と四角い畑がひろがり、手前の白っぽい平地を、小さな輪の形のくぼみが点線のように並んで、何本も斜めに横切っている。輪のひとつひとつは、真ん中が黒く、まわりが盛り上がって見える。右下に手書きの番号。⚠️ 館の記載には、この列が何かは書かれていない。カナートは、横穴を掘った土を竪坑で運び上げて口のまわりに積むので、空から見ると竪坑が点線のように連なるとされる——この列をカナートの竪坑と読むのは、こちら側である。"}, {"t": "photo", "f": "ido_p1.jpg", "date": "いま（2004年10月12日の観測）", "place": "イラン（ザグロス山脈）", "title": "イランの扇状地（衛星画像）", "author": "NASA／METI／AIST／Japan Space Systems、日米 ASTER 科学チーム", "lic": "パブリックドメイン（合衆国政府の作品）", "url": "https://commons.wikimedia.org/wiki/File:Alluvial_Fan,_Iran_(ASTER).jpg", "note": "NASA の地球観測衛星テラに積まれた日本の観測器 ASTER の画像。範囲は24.4×26.8km、北緯28.9度・東経54.9度。NASA の説明はこう書く——ザグロス山脈のこのあたりは雨が少なく、村は灌漑を地下の水に頼っている。急な山の前面から出てくる一時的な流れが半円形の大きな扇状地をつくり、水は扇状地の地下を通って平らな砂漠の平地へ向かう。扇状地と平地の境目で、水は地表の近くへ押し上げられ、井戸で汲みやすくなる。画面では、山から出た谷の口に白っぽい扇が開き、そのへりに沿って緑の畑が弓なりに並ぶ。扇の面には白く枝分かれした筋が見えるが、畑はその筋に沿ってではなく、扇のへりに集まっている。地面の下の水の居場所が、地上の緑の並び方に出ている。⚠️ この画像の細かさでは、井戸やカナートそのものは見分けられず、NASA の説明もカナートとは書いていない。ASTER には青の波長の観測がないので、カラーの画像は観測した波長を色に割り当てて作られている——見えている緑が、目で見た緑と同じとは限らない。"}]}];